// @system @ref LLP 0231 — Runtime Contract dataflow inspector.
import type { ActionIR } from '../compiler/ir.js';
import { isValueChannelSet } from './capabilities.js';
import {
  getContractClauseVerdictsForInstance,
  noteContractActionInvocation,
  registerContractMonitorInstance,
} from './contract-monitor.js';
import type { ComponentInstance } from './instance.js';
import {
  getDataReceiptLog,
  resetDataReceiptsForTests,
  setCurrentActionInvocationId,
  setCurrentDataRootId,
} from './receipts.js';
import { reactiveChurn, snapshotReactiveGraph, untrack } from './signals.js';

export interface ContractDataflowSnapshotOptions {
  component?: string;
  instanceId?: string;
  include?: readonly string[];
  sinceActionSeq?: number;
  sinceWave?: number;
  includeValues?: 'none' | 'summary' | 'full';
}

export interface ActualWriteRecord {
  name: string;
  changed: boolean;
}

export interface ActionLogRecord {
  seq: number;
  /**
   * Stable invocation id (`<instanceId>#a<seq>`) — the join key
   * `MutationReceipt.actionInvocationId` carries (LLP 0284 §2.6).
   */
  invocationId: string;
  wave: number;
  atMs: number;
  action: string;
  args: unknown[];
  declaredWrites: string[];
  declaredMutates: string[];
  actualWrites: ActualWriteRecord[];
  writeContractOk: boolean;
  status: 'ok' | 'error';
  error?: string;
}

interface InstanceRecord {
  instanceId: string;
  instance: ComponentInstance;
  mountedAtMs: number;
  highWaterActionSeq: number;
  actionLog: ActionLogRecord[];
}

interface ActiveAction {
  record: InstanceRecord;
  log: ActionLogRecord;
}

const MAX_ACTION_LOG = 200;
let mountEpoch = 1;
let instanceCounter = 1;
let activeAction: ActiveAction | null = null;
const records = new Map<ComponentInstance, InstanceRecord>();

function summarizeValue(value: unknown, includeValues: 'none' | 'summary' | 'full'): Record<string, unknown> {
  if (includeValues === 'none') {
    return { available: true };
  }
  if (includeValues === 'full') {
    if (typeof value === 'string') return { value };
    if (value === null || typeof value === 'number' || typeof value === 'boolean') {
      return { value };
    }
  }
  if (typeof value === 'string') {
    return {
      valueKind: 'string',
      redacted: true,
      utf16Length: value.length,
      graphemeCount: Array.from(value).length,
    };
  }
  if (Array.isArray(value)) return { valueKind: 'array', length: value.length };
  if (value === null) return { valueKind: 'null', value: null };
  if (typeof value === 'number' || typeof value === 'boolean') {
    return { valueKind: typeof value, value };
  }
  if (typeof value === 'object') {
    return {
      valueKind: 'object',
      keys: Object.keys(value as Record<string, unknown>).slice(0, 8),
    };
  }
  return { valueKind: typeof value };
}

function writeContractOk(declaredWrites: readonly string[], actualWrites: readonly ActualWriteRecord[]): boolean {
  const declared = new Set(declaredWrites);
  const actual = new Set(actualWrites.map((write) => write.name));
  if (declared.size !== actual.size) return false;
  for (const name of declared) {
    if (!actual.has(name)) return false;
  }
  return true;
}

function pushActionLog(record: InstanceRecord, log: ActionLogRecord): void {
  record.highWaterActionSeq = Math.max(record.highWaterActionSeq, log.seq);
  record.actionLog.push(log);
  while (record.actionLog.length > MAX_ACTION_LOG) {
    record.actionLog.shift();
  }
  // Live action-writes clause verdicts (LLP 0278 §2 item 3, dev-gated).
  noteContractActionInvocation(record.instance, record.instanceId, log);
}

/**
 * Set the ambient receipt rootId (LLP 0284 §2.6) to the current mount epoch.
 * Called at the START of component instantiation — binding wiring subscribes
 * (and providers emit `established` receipts) before the instance registers
 * below, so the session key must be primed first.
 */
export function primeContractDataflowSession(): void {
  setCurrentDataRootId(`mount_${mountEpoch}`);
}

export function registerContractDataflowInstance(instance: ComponentInstance): void {
  if (records.has(instance)) return;
  // The mount epoch is the receipt rootId (LLP 0284 §2.6): every instanceId
  // below is prefixed with it, so receipts join the action log and the mount
  // session by construction.
  primeContractDataflowSession();
  const record: InstanceRecord = {
    instance,
    instanceId: `mount_${mountEpoch}/ci_${instanceCounter++}`,
    mountedAtMs: Date.now(),
    highWaterActionSeq: 0,
    actionLog: [],
  };
  records.set(instance, record);
  registerContractMonitorInstance(instance, record.instanceId);
  instance.owner.register(() => {
    records.delete(instance);
    if (records.size === 0) {
      mountEpoch += 1;
      instanceCounter = 1;
    }
  });
}

export function recordContractStateWrite(
  instance: ComponentInstance,
  name: string,
  before: unknown,
  after: unknown,
): void {
  if (!activeAction || activeAction.record.instance !== instance) return;
  const existing = activeAction.log.actualWrites.find((write) => write.name === name);
  const changed = !Object.is(before, after);
  if (existing) {
    existing.changed = existing.changed || changed;
    return;
  }
  activeAction.log.actualWrites.push({ name, changed });
}

export function runContractActionWithLog<T>(
  instance: ComponentInstance,
  action: ActionIR,
  args: unknown[],
  fn: () => T,
): T {
  const record = records.get(instance);
  if (!record) return fn();
  // Reserve the seq at ENTRY (not completion): a nested same-instance action
  // must get a distinct seq — and therefore a distinct invocationId, the
  // §2.6 receipt join key — even though it completes (and logs) first.
  const seq = record.highWaterActionSeq + 1;
  record.highWaterActionSeq = seq;
  const invocationId = `${record.instanceId}#a${seq}`;
  const log: ActionLogRecord = {
    seq,
    invocationId,
    wave: reactiveChurn().wave,
    atMs: Date.now(),
    action: action.name,
    args: args.map((arg) => summarizeValue(arg, 'summary')),
    declaredWrites: [...(action.writes ?? [])],
    declaredMutates: [...(action.mutates ?? [])],
    actualWrites: [],
    writeContractOk: false,
    status: 'ok',
  };
  const previous = activeAction;
  activeAction = { record, log };
  // Ambient §2.6 join key: provider `mutate` calls run synchronously inside
  // the action body and capture this id onto their mutation receipts.
  setCurrentActionInvocationId(invocationId);
  try {
    const result = fn();
    log.writeContractOk = writeContractOk(log.declaredWrites, log.actualWrites);
    pushActionLog(record, log);
    return result;
  } catch (error) {
    log.status = 'error';
    log.error = error instanceof Error ? error.message : String(error);
    log.writeContractOk = writeContractOk(log.declaredWrites, log.actualWrites);
    pushActionLog(record, log);
    throw error;
  } finally {
    activeAction = previous;
    setCurrentActionInvocationId(previous ? previous.log.invocationId : null);
  }
}

export function getContractDataflowSnapshot(
  options: ContractDataflowSnapshotOptions = {},
): Record<string, unknown> {
  const includeValues = options.includeValues ?? 'summary';
  const include = new Set(
    options.include ?? [
      'state',
      'derives',
      'bindings',
      'actionLog',
      'clauseVerdicts',
      'receipts',
      'channels',
      'reactive',
    ],
  );
  const allRecords = [...records.values()];
  const candidates = allRecords.filter((record) => {
    if (options.instanceId && record.instanceId !== options.instanceId) return false;
    if (options.component && record.instance.def.ir.name !== options.component) return false;
    return true;
  });
  const record = candidates[0] ?? null;
  if (!record) {
    return {
      instances: allRecords.map((candidate) => ({
        instanceId: candidate.instanceId,
        component: candidate.instance.def.ir.name,
        irRef: `${candidate.instance.def.file.sourcePath ?? 'contract'}#${candidate.instance.def.ir.name}`,
        mountedAtMs: candidate.mountedAtMs,
      })),
      degraded: true,
      degradedReason: 'No mounted Contract component instance matched the query.',
    };
  }

  const { instance } = record;
  const data: Record<string, unknown> = {
    component: instance.def.ir.name,
    instanceId: record.instanceId,
    irRef: `${instance.def.file.sourcePath ?? 'contract'}#${instance.def.ir.name}`,
    highWaterActionSeq: record.highWaterActionSeq,
    degraded: false,
  };

  if (include.has('state')) {
    data.state = instance.def.ir.states.map((state) => {
      const binding = instance.scope.lookup(state.name);
      return {
        name: state.name,
        ...summarizeValue(
          binding && (binding.kind === 'state' || binding.kind === 'getter')
            ? untrack(() => binding.get())
            : undefined,
          includeValues,
        ),
      };
    });
  }

  if (include.has('derives')) {
    data.derives = instance.def.ir.derives.map((derive) => {
      const binding = instance.scope.lookup(derive.name);
      return {
        name: derive.name,
        ...summarizeValue(
          binding && (binding.kind === 'state' || binding.kind === 'getter')
            ? untrack(() => binding.get())
            : undefined,
          includeValues,
        ),
      };
    });
  }

  if (include.has('bindings')) {
    data.bindings = instance.def.ir.actions.map((action) => ({
      handler: action.name,
      resolves: Boolean(instance.scope.lookup(action.name)),
      declaredWrites: [...(action.writes ?? [])],
      declaredMutates: [...(action.mutates ?? [])],
    }));
  }

  if (include.has('actionLog')) {
    data.actionLog = record.actionLog.filter((entry) =>
      options.sinceActionSeq === undefined ? true : entry.seq > options.sinceActionSeq!,
    );
  }

  if (include.has('clauseVerdicts')) {
    // Live contract clause verdicts (LLP 0278 §2 item 3) — queryable through
    // the same agent surface as the action log.
    data.clauseVerdicts = getContractClauseVerdictsForInstance(instance);
  }

  if (include.has('receipts')) {
    // Provider data receipts (LLP 0284 §2.6 / §5 item 5) — global to the
    // runtime, not per-instance: `receipt.rootId` joins the mount session
    // (the `mount_N` prefix of instanceId) and
    // `receipt.actionInvocationId` joins `actionLog[].invocationId`.
    data.receipts = getDataReceiptLog({ limit: 50 });
  }

  if (include.has('channels')) {
    // LLP 0281 §3.5 — value channels are live-observable, never
    // replay-asserted: the current sample, write/coalesce counters, and
    // the publish descriptor facts (declared rate, budget, counters) are
    // readable here; transient value HISTORIES stay excluded from traces
    // and replay by design.
    data.channels = instance.def.ir.behaviors
      .map((behavior) => {
        const binding = instance.scope.lookup(behavior.name);
        const value =
          binding && (binding.kind === 'value' || binding.kind === 'local')
            ? binding.value
            : undefined;
        return isValueChannelSet(value) ? value.__inspect() : null;
      })
      .filter((entry): entry is Record<string, unknown> => entry !== null);
  }

  if (include.has('reactive') || include.has('reactiveGraph')) {
    const churn = reactiveChurn({ sinceWave: options.sinceWave });
    data.reactive = {
      wave: churn.wave,
      churnSinceWave: churn,
      ...(include.has('reactiveGraph') ? { graph: snapshotReactiveGraph() } : {}),
    };
  }

  return data;
}

export function resetContractDataflowInspectorForTests(): void {
  records.clear();
  activeAction = null;
  mountEpoch = 1;
  instanceCounter = 1;
  resetDataReceiptsForTests();
}
