// @system @ref LLP 0085, LLP 0157 §8 — Contract clauses -> Phase A verifier.
//
// Converts a component's `contract` block into the UiContract shape consumed
// by the 0094 Phase A JS/TS verifier (packages/exact-devtools/src/agent/
// contracts.ts). The shapes are emitted structurally so this package does
// not depend on @exact/devtools; `verifyContract` accepts the plain data.
//
// Conversion coverage: has / missing / count (literal) / state
// (enabled|disabled|checked|unchecked|visible|hidden) / press -> action /
// press -> navigate / change -> action (with `then` outcome expectations on
// both press and change, LLP 0187 S0a + LLP 0278 §2) / standalone navigate /
// exits. Clauses the live verifier cannot express yet (`when ... then`,
// dynamic count, action-writes, derive-depends) are checked statically by
// the compiler and skipped here with a note.

import type {
  ContractAssertionClauseIR,
  ComponentIR,
  ContractClauseIR,
  Expr,
  ContractSelectorIR,
} from '../compiler/ir.js';
import { printExpression } from '../compiler/format.js';
import {
  getContractClauseVerdictsForInstance,
  type ContractClauseVerdict,
} from './contract-monitor.js';
import type { CompiledComponent } from './define.js';
import { evalRuntimeExpr } from './execution.js';
import type { ComponentInstance } from './instance.js';
import { untrack } from './signals.js';

interface EmittedSelector {
  role?: string;
  label?: string;
  text?: string;
  testId?: string;
  /**
   * Prefix match on testId (authored as `testId="^todo-"`, LLP 0278 §2
   * item 2). Exactly one of testId / testIdPrefix is set.
   */
  testIdPrefix?: string;
  type?: string;
  visible?: boolean;
  description?: string;
}

/**
 * A dynamic clause expression the verifier resolves through the contract's
 * `evaluate(exprId)` hook. `source` is the printed Contract expression for
 * diagnostics; the verifier treats the id as opaque.
 */
export interface EmittedExprRef {
  id: string;
  source: string;
}

interface EmitContext {
  exprs: Map<string, Expr>;
  nextExprId: number;
}

function emitExprRef(ctx: EmitContext, expr: Expr): EmittedExprRef {
  const id = `expr_${ctx.nextExprId}`;
  ctx.nextExprId += 1;
  ctx.exprs.set(id, expr);
  return { id, source: printExpression(expr) };
}

interface EmittedClause {
  kind: string;
  checkedBy?: 'static' | 'live-tree' | 'visual' | 'timed' | 'perf';
  confidence?: 'exact' | 'computed' | 'inferred' | 'unknown';
  [key: string]: unknown;
}

export interface EmittedUiContract {
  id: string;
  title: string;
  description?: string;
  surface: { basePath: string };
  prepare?: Array<{ kind: string; [key: string]: unknown }>;
  clauses: EmittedClause[];
  /**
   * Resolves a dynamic clause expression (`expectedExpr` / `guardExpr`) by
   * id against the mounted instance scope. Present when toUiContract was
   * given an `instance` and the contract has dynamic expressions; the
   * devtools verifier consumes this as an opaque callback so it never
   * depends on @exact/contract (LLP 0278 §2 evaluator seam).
   */
  evaluate?: (exprId: string) => unknown;
  /**
   * Live clause verdicts recorded by the runtime contract monitor for the
   * mounted instance (action-writes today). Present when toUiContract was
   * given an `instance` and the contract has monitor-checked clauses.
   */
  verdicts?: () => ContractClauseVerdict[];
}

export interface ToUiContractOptions {
  id?: string;
  title?: string;
  basePath: string;
  prepare?: Array<{ kind: string; [key: string]: unknown }>;
  /**
   * A mounted instance of the emitted component. Backs the contract's
   * `evaluate(exprId)` hook so dynamic clause expressions (expression-valued
   * counts, `when` guards) resolve against live component state. Dynamic
   * clauses still emit without it, but a verifier run then reports them as
   * unresolvable rather than checking them.
   */
  instance?: ComponentInstance;
}

/** Splits an authored testId into exact vs `^`-prefixed prefix matching. */
function emitTestId(testId: string | undefined): {
  testId?: string;
  testIdPrefix?: string;
} {
  if (testId === undefined) {
    return {};
  }
  if (testId.startsWith('^')) {
    return { testIdPrefix: testId.slice(1) };
  }
  return { testId };
}

function emitSelector(selector: ContractSelectorIR): EmittedSelector {
  switch (selector.kind) {
    case 'button':
      return {
        role: 'button',
        label: selector.value,
        visible: true,
        description: `button${selector.value ? ` "${selector.value}"` : ''}`,
      };
    case 'text':
      return {
        text: selector.value,
        visible: true,
        description: `text "${selector.value ?? ''}"`,
      };
    case 'input':
      return {
        type: 'input',
        label: selector.label,
        ...emitTestId(selector.testId),
        visible: true,
        description: `input${selector.label ? ` "${selector.label}"` : ''}`,
      };
    case 'toggle':
      return {
        role: 'switch',
        label: selector.label,
        ...emitTestId(selector.testId),
        visible: true,
        description: `toggle${selector.label ? ` "${selector.label}"` : ''}`,
      };
    case 'section':
      return {
        role: 'group',
        label: selector.value,
        visible: true,
        description: `section${selector.value ? ` "${selector.value}"` : ''}`,
      };
    case 'item':
      // `item` matches any visible node; attribute filters (testId /
      // testIdPrefix / label) carry the real selectivity.
      return {
        label: selector.label,
        ...emitTestId(selector.testId),
        visible: true,
        description: selector.testId
          ? `item testId="${selector.testId}"`
          : selector.label
            ? `item label="${selector.label}"`
            : 'item',
      };
    case 'node':
      return {
        role: selector.role,
        ...emitTestId(selector.testId),
        label: selector.label,
        visible: true,
        description: selector.testId
          ? `node testId="${selector.testId}"`
          : selector.role
            ? `node role="${selector.role}"`
            : 'node',
      };
    default:
      return { visible: true, description: selector.kind };
  }
}

function withLiveTreeMetadata(clause: EmittedClause): EmittedClause {
  return {
    checkedBy: 'live-tree',
    confidence: 'exact',
    ...clause,
  };
}

function withStaticMetadata(clause: EmittedClause): EmittedClause {
  return {
    checkedBy: 'static',
    confidence: 'computed',
    ...clause,
  };
}

function emitNavigationTarget(expr: Expr): Record<string, unknown> {
  if (expr.kind === 'string') {
    return {
      kind: 'literal',
      path: expr.value,
    };
  }
  return {
    kind: 'expression',
    expression: expr,
  };
}

function emitAssertionClause(
  clause: ContractAssertionClauseIR,
  ctx: EmitContext,
): EmittedClause | null {
  switch (clause.kind) {
    case 'has':
      return withLiveTreeMetadata({ kind: 'has', selector: emitSelector(clause.selector) });
    case 'missing':
      return withLiveTreeMetadata({ kind: 'missing', selector: emitSelector(clause.selector) });
    case 'count': {
      if (clause.expected.kind === 'number') {
        return withLiveTreeMetadata({
          kind: 'count',
          selector: emitSelector(clause.selector),
          expected: clause.expected.value,
        });
      }
      // Expression-valued counts (LLP 0278 §2 item 2) emit an expression
      // reference the verifier resolves through the contract's evaluate hook.
      return withLiveTreeMetadata({
        kind: 'count',
        selector: emitSelector(clause.selector),
        expectedExpr: emitExprRef(ctx, clause.expected),
      });
    }
    case 'state': {
      const expected: Record<string, unknown> = {};
      switch (clause.state) {
        case 'enabled':
          expected.disabled = false;
          break;
        case 'disabled':
          expected.disabled = true;
          break;
        case 'checked':
          expected.checked = true;
          break;
        case 'unchecked':
          expected.checked = false;
          break;
        case 'visible':
          expected.interactable = true;
          break;
        case 'hidden':
          return withLiveTreeMetadata({ kind: 'missing', selector: emitSelector(clause.selector) });
      }
      return withLiveTreeMetadata({ kind: 'state', selector: emitSelector(clause.selector), expected });
    }
  }
}

function emitClause(clause: ContractClauseIR, ctx: EmitContext): EmittedClause | null {
  switch (clause.kind) {
    case 'has':
    case 'missing':
    case 'count':
    case 'state':
      return emitAssertionClause(clause, ctx);
    case 'press':
      const action = clause.navigate
        ? {
            kind: 'navigate',
            target: emitNavigationTarget(clause.navigate),
          }
        : clause.action
          ? { kind: 'action', name: clause.action }
          : undefined;
      const pressClause = withLiveTreeMetadata({
        kind: 'press',
        target: emitSelector(clause.selector),
        expects: (clause.expects ?? [])
          .map((expectation) => emitAssertionClause(expectation, ctx))
          .filter((expectation): expectation is EmittedClause => expectation !== null),
        description: clause.navigate
          ? 'press navigates to route target'
          : clause.action
          ? `press routes to action ${clause.action}`
          : 'press satisfies outcome assertion',
      });
      if (action) {
        if (clause.navigate && clause.expectedRedirects && clause.expectedRedirects.length > 0) {
          (action as Record<string, unknown>).expectedRedirects =
            clause.expectedRedirects.map(emitNavigationTarget);
        }
        if (clause.navigate && clause.alternates && clause.alternates.length > 0) {
          (action as Record<string, unknown>).alternates = clause.alternates.map(emitNavigationTarget);
        }
        pressClause.action = action;
      }
      return pressClause;
    case 'navigate':
      const navigateClause = {
        kind: 'navigate',
        target: emitNavigationTarget(clause.target),
        description: 'declares navigation edge',
      };
      if (clause.expectedRedirects && clause.expectedRedirects.length > 0) {
        (navigateClause as Record<string, unknown>).expectedRedirects =
          clause.expectedRedirects.map(emitNavigationTarget);
      }
      if (clause.alternates && clause.alternates.length > 0) {
        (navigateClause as Record<string, unknown>).alternates =
          clause.alternates.map(emitNavigationTarget);
      }
      return withStaticMetadata(navigateClause);
    case 'exits':
      return withStaticMetadata({
        kind: 'exits',
        only: clause.only,
        targets: clause.targets.map(emitNavigationTarget),
        description: clause.only
          ? 'declares closed navigation exit set'
          : 'declares navigation exit set',
      });
    case 'change': {
      // LLP 0278 §2 item 1 — mirror of the press path: the verifier sets the
      // target's value (a probe type) and then checks the outcome assertions.
      return withLiveTreeMetadata({
        kind: 'change',
        target: emitSelector(clause.selector),
        action: { kind: 'action', name: clause.action },
        expects: (clause.expects ?? [])
          .map((expectation) => emitAssertionClause(expectation, ctx))
          .filter((expectation): expectation is EmittedClause => expectation !== null),
        description:
          clause.expects && clause.expects.length > 0
            ? `change routes to action ${clause.action} and satisfies outcome assertion`
            : `change routes to action ${clause.action}`,
      });
    }
    case 'when': {
      // LLP 0278 §2 item 4 — live when clauses: the guard emits an expression
      // ref evaluated against instance scope at verification time; when it
      // holds the inner clause is checked, otherwise the verifier reports
      // skipped-guard-false (distinct from pass). Only inner clauses the live
      // verifier can execute emit; `when` around navigate/exits/static kinds
      // stays compile-time only.
      const inner = emitClause(clause.clause, ctx);
      if (!inner || !LIVE_WHEN_INNER_KINDS.has(String(inner.kind))) {
        return null;
      }
      return withLiveTreeMetadata({
        kind: 'when',
        guardExpr: emitExprRef(ctx, clause.test),
        clause: inner,
        description: `when ${printExpression(clause.test)} then ${
          typeof inner.description === 'string' ? inner.description : String(inner.kind)
        }`,
      });
    }
    case 'invariant': {
      // LLP 0278 §4 mode 1 — the runtime checks invariants passively after
      // every settled flush in dev (contract-monitor.ts); a verifier run
      // checks the clause once, as an ordinary assertion holding now.
      const inner = emitClause(clause.clause, ctx);
      if (!inner) {
        return null;
      }
      return withLiveTreeMetadata({
        kind: 'invariant',
        clause: inner,
        description: `invariant: ${
          typeof inner.description === 'string' ? inner.description : String(inner.kind)
        }`,
      });
    }
    case 'action-writes':
      // LLP 0278 §2 item 3 — checked two ways: statically by the compiler
      // (contract_action_writes_mismatch, error severity) and live by the
      // runtime contract monitor, which fails the clause for any invocation
      // whose actual writes escape the declared set. Verdicts flow through
      // the contract's `verdicts` hook and the dataflow snapshot.
      return withLiveTreeMetadata({
        kind: 'action-writes',
        action: clause.action,
        writes: [...clause.writes],
        description: `action ${clause.action} writes only ${clause.writes.join(', ')}`,
      });
    case 'derive-depends':
      // Enforced by the compiler (contract_derive_depends_mismatch, error
      // severity); emitted so the claim is visible in the contract instead
      // of vanishing. There is no runtime read-tracking per derive yet.
      return withStaticMetadata({
        kind: 'derive-depends',
        derive: clause.derive,
        deps: [...clause.deps],
        description: `derive ${clause.derive} depends only on ${clause.deps.join(', ')}`,
      });
  }
}

/** Inner clause kinds the live verifier can execute under a `when` guard. */
const LIVE_WHEN_INNER_KINDS: ReadonlySet<string> = new Set([
  'has',
  'missing',
  'count',
  'state',
  'press',
  'change',
  'when',
]);

export type ContractClauseEmissionStatus = 'live' | 'static' | 'none';

export interface ContractClauseEmissionClassification {
  kind: ContractClauseIR['kind'];
  /**
   * `live` — the clause emits with live verification metadata (live-tree
   * verifier execution or runtime-monitor verdicts). `static` — the clause
   * emits but its enforcement is compile-time/registry-side (navigation
   * edges, derive-depends). `none` — the clause does not emit at all and is
   * at best compile-checked (currently only `when` wrapping a non-live
   * inner clause).
   */
  status: ContractClauseEmissionStatus;
  checkedBy?: string;
}

/**
 * Classifies one authored contract clause by what actually verifies it —
 * the single source for the live-coverage metric (LLP 0278 §2) and the
 * contract-check CLI's per-clause status. Derives the answer from emission
 * itself so classification cannot drift from behavior.
 */
export function classifyContractClauseEmission(
  clause: ContractClauseIR,
): ContractClauseEmissionClassification {
  const ctx: EmitContext = { exprs: new Map(), nextExprId: 0 };
  const emitted = emitClause(clause, ctx);
  if (!emitted) {
    return { kind: clause.kind, status: 'none' };
  }
  const checkedBy = typeof emitted.checkedBy === 'string' ? emitted.checkedBy : undefined;
  return {
    kind: clause.kind,
    status: checkedBy === 'static' ? 'static' : 'live',
    checkedBy,
  };
}

/**
 * Emits the verifier-ready contract for a compiled component. Skipped
 * clause kinds are statically checked at compile time instead.
 */
export function toUiContract(
  component: CompiledComponent | ComponentIR,
  options: ToUiContractOptions,
): EmittedUiContract {
  const ir = 'ir' in component ? component.ir : component;
  if (options.instance && options.instance.def.ir.name !== ir.name) {
    throw new Error(
      `[contract] toUiContract instance is a mounted ${options.instance.def.ir.name}, ` +
        `not the emitted component ${ir.name}`,
    );
  }
  const ctx: EmitContext = { exprs: new Map(), nextExprId: 0 };
  const clauses: EmittedClause[] = [];
  for (const clause of ir.contracts) {
    const emitted = emitClause(clause, ctx);
    if (emitted) {
      // Behavior-carried clauses keep their provenance in the emitted
      // metadata (LLP 0280 §2.1 / LLP 0278 §6): the live verifier treats
      // them as component clauses; results name where the claim came from.
      if (clause.provenance) {
        emitted.provenance = {
          behavior: clause.provenance.behavior,
          instance: clause.provenance.instance,
        };
      }
      clauses.push(emitted);
    }
  }
  const contract: EmittedUiContract = {
    id: options.id ?? `contract/${ir.name}`,
    title: options.title ?? `${ir.name} contract block`,
    surface: { basePath: options.basePath },
    prepare: options.prepare,
    clauses,
  };
  const instance = options.instance;
  if (instance && ctx.exprs.size > 0) {
    // Dynamic expressions evaluate against the live instance scope,
    // untracked so verification never subscribes the reactive graph.
    contract.evaluate = (exprId: string): unknown => {
      const expr = ctx.exprs.get(exprId);
      if (!expr) {
        throw new Error(`[contract] unknown contract expression id "${exprId}"`);
      }
      return untrack(() => evalRuntimeExpr(expr, instance.scope));
    };
  }
  if (instance && ir.contracts.some((clause) => clause.kind === 'action-writes')) {
    contract.verdicts = () => getContractClauseVerdictsForInstance(instance);
  }
  return contract;
}
