// @system @ref LLP 0263 S1 — Contract-facing data provider seam.
// @system @ref LLP 0284 §2.2/§2.4/§2.6 — source-seam v2: connection axis,
// manifest liveness facts, and receipt interfaces (additive on the S1 shape).
//
// This module is intentionally above the LLP 0207 query boundary: generated
// manifest-backed descriptors can project provider-specific queries/mutations
// into this neutral async-cell surface without making Contract depend on a
// backend such as Snapback.

import {
  isContractQueryHandle,
  type ContractQueryBoundary,
  type ContractQueryHandle,
  type ContractQuerySubscription,
} from './query-boundary.js';
import {
  buildDataMutationCorrelation,
  connectProviderReceipts,
  currentActionInvocationId,
  currentDataRootId,
  currentOptimisticWaveId,
} from './receipts.js';

export type DataTypeDescriptor =
  | { shape: 'unknown' }
  | { shape: 'primitive'; name: 'string' | 'number' | 'boolean' | 'null' }
  | { shape: 'object'; fields: Record<string, DataTypeDescriptor> }
  | { shape: 'array'; element: DataTypeDescriptor };

export type DataProviderCapabilities = {
  localReplica: boolean;
  subscriptions: boolean;
  initialSnapshot: boolean;
  optimisticMutations: boolean;
  rowSyncState: boolean;
  serverRunnableQueries: boolean;
  forceStates: boolean;
  branchableFixtures: boolean;
  headlessBoot: boolean;
};

export type DataProviderDiagnostic = {
  code: string;
  severity: 'error' | 'warning' | 'info';
  message: string;
  provider: 'snapback' | string;
  owner: 'contract' | 'provider' | 'vite' | 'schema' | 'handler' | 'generated';
  source?: {
    file?: string;
    line?: number;
    column?: number;
    generatedFrom?: string;
  };
  queryName?: string;
  mutationName?: string;
  table?: string;
  suggestedFix?: string;
};

/** How a source binding is kept current (LLP 0284 §2.4). */
export type DataQueryMode = 'snapshot' | 'live' | 'poll' | 'reconcile-on-mutate';

/** How deltas physically arrive; the static twin of the runtime `SubscriptionReceipt.transport` (LLP 0284 §2.1 rule 3 agreement). */
export type DataQueryTransport = 'push' | 'poll' | 'reconcile-on-mutate';

/**
 * Which receipt kinds the provider emits for this descriptor (LLP 0284
 * §2.4/§2.6). For the boundary provider this is load-bearing, not advisory:
 * subscription `established`/`disposed` receipts are emitted only under
 * `'mutation+subscription'`. Mutation receipts are governed by the mutation's
 * execution (there is no per-mutation policy field), so the boundary provider
 * always emits them; `'mutation'` therefore reads "mutations are
 * receipt-covered, this binding's subscription lifecycle is not".
 */
export type DataQueryReceiptsPolicy = 'none' | 'mutation' | 'mutation+subscription';

export type DataQueryDescriptor = {
  name: string;
  args: Record<string, DataTypeDescriptor>;
  argOrder?: string[];
  result:
    | { kind: 'list'; row: DataTypeDescriptor | { shape: 'unknown' } }
    | { kind: 'single'; value: DataTypeDescriptor | { shape: 'unknown' }; nullable: boolean }
    | { kind: 'scalar'; value: DataTypeDescriptor | { shape: 'unknown' } };
  serverRunnable: boolean;
  localRunnable: boolean;
  /** LLP 0263 subscription policy — fully supported; the v2 fields below refine it (LLP 0284 §2.4 migration table). */
  subscription: 'initial-snapshot' | 'change-only' | 'none';

  // --- Manifest v2 liveness/cost facts (LLP 0284 §2.4; all optional —
  // unknown fields are ignored by old consumers; old fields remain valid
  // inputs; `normalizeQueryLiveness` resolves the implied mappings). ---

  /** How the binding is kept current. */
  mode?: DataQueryMode;
  /** Whether the provider can push deltas for this descriptor (defaults to global `capabilities.subscriptions`). */
  livePush?: boolean;
  /** Whether the subscription primes with an authoritative snapshot (snapshot-with-subscribe, §2.1 rule 1). */
  initialSnapshot?: boolean;
  /** Cost guardrail: may be false on chatty/expensive descriptors even when `livePush` is true (§2.4). */
  defaultLive?: boolean;
  /** Poll cadence floor, provider-owned; authors may lengthen, never shorten. */
  pollCadenceMs?: number;
  /** Delivery-rate bound the provider coalesces toward (runtime/receipt fact). */
  maxDeltaRateHz?: number;
  /** Whether the provider coalesces bursts of deltas. */
  coalesce?: boolean;
  /** Marks an ephemeral collection descriptor (LLP 0284 §2.5; served by `subscribeEphemeral`, bound with `ephemeral`). */
  ephemeral?: boolean;
  /** Receipt emission policy for this descriptor. */
  receipts?: DataQueryReceiptsPolicy;
  /** Declared delta transport; must agree with the runtime-observed transport (§2.1 rule 3). */
  transport?: DataQueryTransport;
};

export type DataMutationDescriptor = {
  name: string;
  args: Record<string, DataTypeDescriptor>;
  argOrder?: string[];
  writes: string[];
  optimistic: boolean;
  serverRunnable: boolean;
};

export type ContractDataManifest = {
  /** 1 = LLP 0263; 2 = LLP 0284 §2.4 (additive liveness/cost fields — old consumers ignore them, old fields remain valid). */
  manifestVersion: 1 | 2;
  provider: string;
  generatedAt?: string;
  inputsHash?: string;
  capabilities: DataProviderCapabilities;
  queries: Record<string, DataQueryDescriptor>;
  mutations: Record<string, DataMutationDescriptor>;
  diagnostics?: DataProviderDiagnostic[];
};

export type SerializedError = {
  message: string;
  name?: string;
  stack?: string;
};

export type DataCell<T = unknown> =
  | { status: 'pending'; previous?: T }
  | { status: 'ready'; value: T; empty: boolean }
  | { status: 'error'; error: SerializedError; previous?: T }
  | { status: 'refreshing'; value: T };

/**
 * Connection axis (LLP 0284 §2.2) — orthogonal to the data axis above.
 *
 * Present on cells from subscription-backed bindings; absent for
 * non-subscription bindings (plain snapshot descriptors) — the field's
 * absence is itself a fact. Providers map their internals onto these
 * meanings; they are not provider-defined labels. (The `stale` spelling is
 * provisional pending the LLP 0194 amendment / B-4 freeze — it collides
 * with the retention meaning of "stale"; LLP 0284 OQ7.)
 */
export type DataConnection =
  /** Subscription being established. */
  | 'connecting'
  /** Push transport active, freshness within budget. */
  | 'live'
  /** No push; the provider refreshes on a declared cadence. */
  | 'polling'
  /**
   * Last-known value renderable; the provider's declared freshness budget
   * has been missed (retry/backoff may be in progress).
   */
  | 'stale'
  /** No active transport and no retry in progress. */
  | 'disconnected';

/**
 * LLP 0284 §2.2 — the v2 cell: the shipped data axis unchanged, plus the
 * optional connection axis. Additive: every existing consumer of `DataCell`
 * remains correct unmodified.
 */
export type DataCellV2<T = unknown> = DataCell<T> & { connection?: DataConnection };

export type DataObserver<T = unknown> = (cell: DataCellV2<T>) => void;
export type DataSubscription = { dispose(): void };
export type DataForceHandle = { dispose(): void };
/**
 * Forced cells extend to the connection axis (LLP 0284 §2.2 drivability):
 * tests, Design Mode, and the conformance profile can force
 * `polling`/`stale`/`disconnected` so connection sugar and clauses are
 * drivable deterministically.
 */
export type ForcedDataState<T = unknown> = DataCellV2<T>;

/**
 * LLP 0284 §2.5 — one entry of an ephemeral presence map. Normative shape.
 *
 * `value` deliberately promises no object identity across updates
 * (§2.5.1's reservation: per-entry values become channel-backable when
 * LLP 0281's value channels land, without a grammar or author migration).
 */
export interface EphemeralEntry<V = unknown> {
  /** Scope-unique; ordering key. */
  key: string;
  value: V;
  /** Provider clock, monotonic per key. */
  updatedAt: number;
  /** TTL horizon when the provider declares one. UI metadata only — the client never auto-expires locally (§2.5 expiry rule). */
  expiresAt?: number;
  /** Presence provenance. */
  sourceClientId: string;
  /** True for this client's own published entry — providers must not silently omit self-presence (§2.5). */
  self: boolean;
}

/**
 * LLP 0284 §2.5 — the typed reactive map an `ephemeral` binding exposes.
 * Normative shape.
 *
 * Entries are in stable ascending-`key` order. An entry past provider TTL is
 * deleted by the provider and never exposed again — there is no per-entry
 * "stale" state. Transport health is the map's `connection`: under
 * `stale`/`disconnected` the map freezes at last-known entries (which may age
 * past TTL locally) and the connection axis is the signal that they are no
 * longer trustworthy.
 */
export interface EphemeralMapCell<V = unknown> {
  status: 'pending' | 'ready' | 'error';
  /** Stable order: ascending key. */
  entries: EphemeralEntry<V>[];
  /** Same axis as §2.2. */
  connection?: DataConnection;
}

export type EphemeralObserver<V = unknown> = (cell: EphemeralMapCell<V>) => void;

/**
 * LLP 0284 §2.5 drivability — a forced ephemeral map is LOCAL-ONLY: it must
 * never publish or allocate backend presence. `forceEphemeralState` delivers
 * cells to local observers and defers any provider subscription for
 * observers that arrive while the force is active.
 */
export type ForcedEphemeralState<V = unknown> = EphemeralMapCell<V>;

/**
 * Per-scope forcing (LLP 0284 §2.6 scope identity; the §8.2 follow-up,
 * ENG-22526): a force with `scope` targets only bindings whose subscription
 * args normalize to the same scope (matching how the Snapback adapter keys
 * overlays per (collection, scope)); omitting it keeps the name-only
 * broadcast semantics.
 */
export interface DataForceOptions {
  scope?: Record<string, unknown>;
}

/**
 * LLP 0284 §2.6 / §5 item 5 — the runtime-supplied correlation keys a caller
 * attaches to `mutate`. Providers echo the object verbatim onto the
 * mutation's receipt (`correlation`); the Exact receipt log lifts the keys
 * when the provider did not set them itself (LLP 0034 §3.2).
 */
export interface DataMutationCorrelation {
  /** Joins `ActionLogRecord.invocationId` (LLP 0231). */
  actionInvocationId?: string;
  /** Joins the runtime flush that applied the optimistic write (`wave_<n>`). */
  optimisticWaveId?: string;
  /** Joins the mount/session (`mount_<n>`). */
  rootId?: string;
  /** Affected bindings, when the caller knows them (providers that track their own subscriptions win). */
  bindingIds?: string[];
}

export type DataMutationResult<T = unknown> =
  | { ok: true; value?: T }
  | { ok: false; error: SerializedError };

export type DataRowSyncState = {
  syncedVersion: string | number | null;
  approxSyncedAt: string | null;
  pendingMutations: boolean;
};

/**
 * LLP 0284 §2.6 — mutation receipt. Interface-normative correlation keys so
 * LLP 0278 can close verification loops deterministically; payloads are
 * provider-extensible. Emitted by the boundary provider below and by the
 * Snapback adapter (LLP 0034 D2); observed through `onReceipt`/`receipts`
 * and collected into the runtime receipt log (`receipts.ts`).
 *
 * Monotonicity: `snapshotVersion` is non-decreasing per binding. A live
 * provider may coalesce or drop intermediate deltas; verification asserts
 * eventual convergence to the latest version, never every-version
 * observation — receipts carry versions so "converged to v42" is a
 * checkable fact.
 */
export interface MutationReceipt {
  /** Provider-unique. */
  mutationId: string;
  /** Joins the LLP 0231 action log. */
  actionInvocationId?: string;
  /** Affected query/ephemeral bindings. */
  bindingIds: string[];
  /** Joins the mount/session. */
  rootId: string;
  /** Joins the runtime flush that applied it. */
  optimisticWaveId?: string;
  /**
   * Tables the mutation wrote. `null` is explicit-unknown — the mutation
   * declared no write set (the Snapback LLP 0034 D2 convention) — and is
   * distinct from `[]` (declared: none affected).
   */
  affectedTables: string[] | null;
  /** Provisional -> confirmed row ids. */
  provisionalRowIds?: Record<string, string>;
  outcome: 'confirmed' | 'rejected';
  rollbackReason?: string;
  /** How the mutation traveled (provider-declared; e.g. 'http'). Distinct from SubscriptionReceipt.transport's delta enum. */
  transport?: string;
  /** Provider version the outcome landed at. */
  snapshotVersion: number;
  /** Capability degradation in effect. */
  degradation?: string;
}

/**
 * LLP 0284 §2.6 — subscription receipt. Records which transport actually
 * served a binding; must agree with the compile-time diagnostic
 * (§2.1 rule 3's static↔runtime agreement rule).
 *
 * Monotonicity: `snapshotVersion` and `lastDeltaVersion` are non-decreasing
 * per binding.
 */
export interface SubscriptionReceipt {
  bindingId: string;
  rootId: string;
  /** e.g. `{ roomId }` — scope identity is required. */
  scope: Record<string, unknown>;
  event: 'established' | 'resubscribed' | 'disposed';
  transport: DataQueryTransport;
  snapshotVersion: number;
  /** Monotonic per binding. */
  lastDeltaVersion?: number;
}

/**
 * LLP 0284 §2.6 — a provider-emitted receipt as observed through the
 * `onReceipt`/`receipts` surface. `kind`-discriminated; the §2.6 keys are
 * interface-normative and payloads are provider-extensible (providers may
 * attach e.g. `receivedAtMs`, `reason`, or an echoed `correlation` object —
 * the LLP 0034 §3.2 join convention).
 */
export type DataReceipt =
  | (MutationReceipt & { kind: 'mutation' } & Record<string, unknown>)
  | (SubscriptionReceipt & { kind: 'subscription' } & Record<string, unknown>);

export type DataReceiptListener = (receipt: DataReceipt) => void;

export interface ContractDataProvider {
  readonly manifest: ContractDataManifest;
  subscribe<T>(
    queryName: string,
    args: Record<string, unknown>,
    observer: DataObserver<T>,
  ): DataSubscription;
  mutate<T>(
    mutationName: string,
    args: Record<string, unknown>,
    /** Optional §2.6 correlation keys, echoed verbatim onto the mutation receipt (LLP 0034 §3.2). */
    correlation?: DataMutationCorrelation,
  ): Promise<DataMutationResult<T>>;
  getRowSyncState?(table: string, rowId: string): Promise<DataRowSyncState | null>;
  forceQueryState?(
    queryName: string,
    state: ForcedDataState,
    /** Per-scope forcing (ENG-22526); omit for the name-only broadcast. */
    options?: DataForceOptions,
  ): DataForceHandle;
  /**
   * LLP 0284 §2.5 — subscribe an ephemeral presence map. Optional: presence
   * requires provider support; absence means the provider serves no
   * ephemeral collections (the descriptor-level fact is
   * `DataQueryDescriptor.ephemeral`).
   */
  subscribeEphemeral?<V>(
    name: string,
    args: Record<string, unknown>,
    observer: EphemeralObserver<V>,
  ): DataSubscription;
  /**
   * LLP 0284 §2.5 drivability — force an ephemeral map locally. LOCAL-ONLY
   * by rule: never publishes, never allocates backend presence.
   */
  forceEphemeralState?(
    name: string,
    state: ForcedEphemeralState,
    /** Per-scope forcing (ENG-22526); omit for the name-only broadcast. */
    options?: DataForceOptions,
  ): DataForceHandle;
  /**
   * LLP 0284 §2.6 — receipt observation, push half. The spelling matches the
   * Snapback kit convention exactly (callback returning a plain unsubscribe
   * function, not a `DataSubscription`); listener throws must be swallowed.
   * Optional: a provider without receipts contributes nothing — absence
   * degrades the verification loops, never the app.
   */
  onReceipt?(listener: DataReceiptListener): () => void;
  /**
   * LLP 0284 §2.6 — receipt observation, pull half: a bounded ring of recent
   * receipts, oldest first (the Snapback kit's `receipts()` shape).
   */
  receipts?(): DataReceipt[];
}

export type BoundaryDataQueryFactory<T = unknown> = (
  args: Record<string, unknown>,
  boundary: ContractQueryBoundary,
) => ContractQueryHandle<T> | readonly T[];

export type BoundaryDataMutation<T = unknown> = (
  args: Record<string, unknown>,
  boundary: ContractQueryBoundary,
) => T | Promise<T>;

/**
 * LLP 0284 §2.5 — a boundary-provider ephemeral source: receives an emit
 * callback for map cells and returns its disposal. The LLP 0207 query
 * boundary is deliberately not involved — ephemeral maps are not row
 * queries.
 */
export type BoundaryEphemeralSource<V = unknown> = (
  args: Record<string, unknown>,
  emit: EphemeralObserver<V>,
) => DataSubscription | (() => void) | void;

export interface BoundaryDataProviderOptions {
  queries: Record<string, BoundaryDataQueryFactory>;
  mutations?: Record<string, BoundaryDataMutation>;
  /** Ephemeral collection sources (LLP 0284 §2.5), keyed by descriptor name. */
  ephemerals?: Record<string, BoundaryEphemeralSource>;
  rowSyncState?: (table: string, rowId: string) => Promise<DataRowSyncState | null> | DataRowSyncState | null;
  /**
   * LLP 0284 §2.2 — connection-axis source consulted per delivery for
   * subscription-backed bindings. Fixtures and adapters use it to drive
   * `stale`/`disconnected` transitions ("providers map their internals onto
   * these meanings"); returning `undefined` falls through to the declared
   * serving mode (`live` → `'live'`, `poll` → `'polling'`; no ongoing
   * transport → absent), so overrides never restate the default.
   */
  connection?: (
    queryName: string,
    liveness: NormalizedQueryLiveness,
  ) => DataConnection | undefined;
}

export function serializeDataError(error: unknown): SerializedError {
  if (error instanceof Error) {
    return {
      message: error.message,
      name: error.name,
      stack: error.stack,
    };
  }
  return { message: String(error) };
}

export function readyDataCell<T>(
  value: T,
  descriptor?: DataQueryDescriptor,
): Extract<DataCell<T>, { status: 'ready' }> {
  return {
    status: 'ready',
    value,
    empty: isEmptyDataValue(value, descriptor),
  };
}

export function isEmptyDataValue(value: unknown, descriptor?: DataQueryDescriptor): boolean {
  if (descriptor?.result.kind === 'list') {
    return Array.isArray(value) && value.length === 0;
  }
  if (descriptor?.result.kind === 'single') {
    return value == null;
  }
  if (!descriptor && Array.isArray(value)) {
    return value.length === 0;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Manifest v2 liveness resolution (LLP 0284 §2.4)
// ---------------------------------------------------------------------------

/**
 * The resolved liveness facts for one descriptor — old (`subscription`,
 * global capabilities) and new (v2) fields folded into one place.
 */
export interface NormalizedQueryLiveness {
  mode: DataQueryMode;
  livePush: boolean;
  initialSnapshot: boolean;
  defaultLive: boolean;
  pollCadenceMs?: number;
  maxDeltaRateHz?: number;
  coalesce: boolean;
  ephemeral: boolean;
  receipts: DataQueryReceiptsPolicy;
  /** Effective delta transport; absent when the resolved mode is 'snapshot' (no ongoing transport). */
  transport?: DataQueryTransport;
  /** Contradictions (error) and degradations (info) found while resolving. */
  diagnostics: DataProviderDiagnostic[];
}

const MODE_TRANSPORT: Record<Exclude<DataQueryMode, 'snapshot'>, DataQueryTransport> = {
  live: 'push',
  poll: 'poll',
  'reconcile-on-mutate': 'reconcile-on-mutate',
};

/**
 * LLP 0284 §2.4 — resolve a descriptor's liveness facts.
 *
 * Implied mappings from the migration table:
 * - `subscription: 'initial-snapshot'` → `initialSnapshot: true`
 * - `subscription: 'change-only'` → `initialSnapshot: false`, `mode: 'live'`
 * - `subscription: 'none'` → `mode: 'snapshot'`
 * - global `capabilities.subscriptions` is the `livePush` default for
 *   descriptors that don't say.
 *
 * When old and new fields contradict, the conflict surfaces as an
 * error-severity `DataProviderDiagnostic` (the shape `data-doctor` and
 * `manifest.diagnostics` already carry) rather than throwing; a declared-live
 * descriptor on a push-less provider degrades to poll/reconcile with an info
 * diagnostic (§2.1 rule 3: degradation is declared, never silent).
 */
export function normalizeQueryLiveness(
  descriptor: DataQueryDescriptor,
  capabilities: DataProviderCapabilities,
): NormalizedQueryLiveness {
  const diagnostics: DataProviderDiagnostic[] = [];
  const report = (
    severity: DataProviderDiagnostic['severity'],
    code: string,
    message: string,
    suggestedFix?: string,
  ): void => {
    diagnostics.push({
      code,
      severity,
      message,
      provider: 'contract',
      owner: 'generated',
      queryName: descriptor.name,
      ...(suggestedFix ? { suggestedFix } : {}),
    });
  };
  const conflict = (message: string): void => {
    report(
      'error',
      'query_liveness_conflict',
      message,
      'Regenerate the manifest so the legacy subscription field and the v2 liveness fields agree (LLP 0284 §2.4).',
    );
  };

  // Legacy `subscription` implications (§2.4 rows 1-3).
  const impliedInitialSnapshot =
    descriptor.subscription === 'initial-snapshot'
      ? true
      : descriptor.subscription === 'change-only'
        ? false
        : undefined;
  const impliedMode: DataQueryMode | undefined =
    descriptor.subscription === 'change-only'
      ? 'live'
      : descriptor.subscription === 'none'
        ? 'snapshot'
        : undefined;

  if (
    impliedInitialSnapshot !== undefined &&
    descriptor.initialSnapshot !== undefined &&
    descriptor.initialSnapshot !== impliedInitialSnapshot
  ) {
    conflict(
      `query "${descriptor.name}": subscription "${descriptor.subscription}" implies initialSnapshot ${String(impliedInitialSnapshot)}, but the manifest declares initialSnapshot ${String(descriptor.initialSnapshot)}`,
    );
  }
  if (impliedMode !== undefined && descriptor.mode !== undefined && descriptor.mode !== impliedMode) {
    conflict(
      `query "${descriptor.name}": subscription "${descriptor.subscription}" implies mode "${impliedMode}", but the manifest declares mode "${descriptor.mode}"`,
    );
  }

  // §2.4: global capabilities.subscriptions is the default for descriptors
  // that don't say.
  const livePush = descriptor.livePush ?? capabilities.subscriptions;
  if (descriptor.livePush === true && !capabilities.subscriptions) {
    conflict(
      `query "${descriptor.name}" declares livePush while the provider's capabilities.subscriptions is false`,
    );
  }

  const initialSnapshot =
    descriptor.initialSnapshot ?? impliedInitialSnapshot ?? capabilities.initialSnapshot;

  let mode = descriptor.mode ?? impliedMode;
  if (mode === undefined) {
    // Declared facts beat defaults: a descriptor that states its transport
    // has stated its mode (livePush stays the capability bit — a capable
    // provider may still declare poll, e.g. the defaultLive:false pattern).
    // Only when nothing is declared does the global livePush default apply.
    mode =
      descriptor.transport === 'reconcile-on-mutate'
        ? 'reconcile-on-mutate'
        : descriptor.transport === 'poll'
          ? 'poll'
          : descriptor.transport === 'push'
            ? 'live'
            : livePush
              ? 'live'
              : descriptor.pollCadenceMs !== undefined
                ? 'poll'
                : 'snapshot';
  }

  // §2.1 rule 3: a declared-live binding on a push-less provider serves by
  // poll or reconcile-on-mutate — degraded, visible, never silent.
  if (mode === 'live' && !livePush) {
    const degraded: DataQueryMode =
      descriptor.transport === 'reconcile-on-mutate' ? 'reconcile-on-mutate' : 'poll';
    report(
      'info',
      'query_live_degraded',
      `query "${descriptor.name}" is declared live but the provider cannot push; the binding serves by ${degraded}${degraded === 'poll' ? " and connection will report 'polling'" : ''} (LLP 0284 §2.1 rule 3)`,
    );
    mode = degraded;
  }

  if (descriptor.transport !== undefined) {
    if (mode === 'snapshot') {
      conflict(
        `query "${descriptor.name}" declares transport "${descriptor.transport}" but resolves to mode "snapshot" (no ongoing transport)`,
      );
    } else if (MODE_TRANSPORT[mode] !== descriptor.transport) {
      conflict(
        `query "${descriptor.name}" declares transport "${descriptor.transport}" but resolves to mode "${mode}" (expected transport "${MODE_TRANSPORT[mode]}")`,
      );
    }
  }

  const transport = mode === 'snapshot' ? undefined : (descriptor.transport ?? MODE_TRANSPORT[mode]);

  return {
    mode,
    livePush,
    initialSnapshot,
    defaultLive: descriptor.defaultLive ?? mode === 'live',
    ...(descriptor.pollCadenceMs !== undefined ? { pollCadenceMs: descriptor.pollCadenceMs } : {}),
    ...(descriptor.maxDeltaRateHz !== undefined ? { maxDeltaRateHz: descriptor.maxDeltaRateHz } : {}),
    coalesce: descriptor.coalesce ?? false,
    ephemeral: descriptor.ephemeral ?? false,
    receipts: descriptor.receipts ?? 'none',
    ...(transport ? { transport } : {}),
    diagnostics,
  };
}

// ---------------------------------------------------------------------------
// Provider-backed query handles (LLP 0284 §2.2 plumbing)
// ---------------------------------------------------------------------------

// The cell rides with its rows delivery as a non-enumerable property (the
// same idiom the instance runtime uses for query-snapshot metadata), so the
// connection axis survives the rows-shaped ContractQueryHandle seam without
// changing its notify signature.
const QUERY_DELIVERY_CELL_KEY = '__exactContractQueryDeliveryCell';

/** Tag a rows delivery with the data cell it came from (LLP 0284 §2.2). */
export function attachQueryDeliveryCell<Row>(rows: Row[], cell: DataCellV2): Row[] {
  Object.defineProperty(rows, QUERY_DELIVERY_CELL_KEY, {
    value: cell,
    enumerable: false,
    configurable: true,
  });
  return rows;
}

/** Read the data cell riding a rows delivery, if the source was provider-backed. */
export function readQueryDeliveryCell(rows: readonly unknown[]): DataCellV2 | undefined {
  const cell = (rows as unknown as Record<string, unknown>)[QUERY_DELIVERY_CELL_KEY];
  if (cell && typeof cell === 'object' && typeof (cell as { status?: unknown }).status === 'string') {
    return cell as DataCellV2;
  }
  return undefined;
}

function toRows<Row>(value: unknown): readonly Row[] {
  if (Array.isArray(value)) {
    return value as readonly Row[];
  }
  return value == null ? [] : [value as Row];
}

/**
 * LLP 0284 §2.2 — project a provider query into the `ContractQueryHandle`
 * shape a `query` binding initializer returns. Data-axis statuses map onto
 * the binding's states, and each delivery carries its full cell (including
 * `connection`) so slot dispatch and `<binding>.connection` expressions see
 * the connection axis.
 */
/**
 * LLP 0284 §2.5 — the handle shape an `ephemeral` binding initializer
 * returns (the ephemeral analog of `ContractQueryHandle`; the LLP 0207 row
 * boundary is deliberately not involved).
 */
export interface ContractEphemeralHandle<V = unknown> {
  readonly __exactContractEphemeral: true;
  readonly name: string;
  readonly key?: string;
  subscribe(observer: EphemeralObserver<V>): DataSubscription;
}

export function isContractEphemeralHandle(value: unknown): value is ContractEphemeralHandle {
  return Boolean(
    value &&
      typeof value === 'object' &&
      (value as { __exactContractEphemeral?: unknown }).__exactContractEphemeral === true &&
      typeof (value as { name?: unknown }).name === 'string' &&
      typeof (value as { subscribe?: unknown }).subscribe === 'function',
  );
}

// Locale-independent ascending-key order (§2.5: stable order so `each ...
// key=c.key` renders deterministically and tests can assert sequences).
function compareEphemeralKeys(a: EphemeralEntry, b: EphemeralEntry): number {
  return a.key < b.key ? -1 : a.key > b.key ? 1 : 0;
}

/**
 * LLP 0284 §2.5 — project a provider ephemeral collection into the handle
 * shape an `ephemeral` binding accepts. Guarantees the §2.5 ascending-key
 * ordering on the Exact side regardless of provider discipline, and degrades
 * to an error map (with a dev warning) on providers without ephemeral
 * support.
 */
export function createProviderEphemeralHandle<V = unknown>(
  provider: ContractDataProvider,
  name: string,
  args: Record<string, unknown> = {},
): ContractEphemeralHandle<V> {
  // Any provider consumed through the generated-binding path becomes
  // receipt-inspectable without configuration (LLP 0284 §5 item 5).
  connectProviderReceipts(provider);
  return {
    __exactContractEphemeral: true,
    name,
    key: `provider:${name}`,
    subscribe(observer) {
      if (!provider.subscribeEphemeral) {
        console.warn(
          `[contract] provider "${provider.manifest.provider}" does not support ephemeral subscriptions; ephemeral map "${name}" renders as error`,
        );
        observer({ status: 'error', entries: [] });
        return { dispose() {} };
      }
      return provider.subscribeEphemeral<V>(name, args, (cell) => {
        observer({ ...cell, entries: [...cell.entries].sort(compareEphemeralKeys) });
      });
    },
  };
}

export function createProviderQueryHandle<Row = unknown>(
  provider: ContractDataProvider,
  queryName: string,
  args: Record<string, unknown> = {},
): ContractQueryHandle<Row> {
  // Any provider consumed through the generated-binding path becomes
  // receipt-inspectable without configuration (LLP 0284 §5 item 5).
  connectProviderReceipts(provider);
  let lastRows: readonly Row[] = [];
  const rowsForCell = (cell: DataCellV2): readonly Row[] => {
    if (cell.status === 'ready' || cell.status === 'refreshing') {
      return toRows<Row>(cell.value);
    }
    if (cell.previous !== undefined) {
      return toRows<Row>(cell.previous);
    }
    return lastRows;
  };
  const handle: ContractQueryHandle<Row> = {
    __exactContractQuery: true,
    table: queryName,
    key: `provider:${queryName}`,
    read: () => [...lastRows],
    subscribe(notify) {
      const subscription = provider.subscribe(queryName, args, (cell) => {
        lastRows = rowsForCell(cell);
        notify(attachQueryDeliveryCell([...lastRows], cell));
      });
      return {
        get current() {
          return lastRows;
        },
        dispose() {
          subscription.dispose();
        },
      };
    },
  };
  return handle;
}

/**
 * LLP 0284 §5 item 5 (runtime half, ENG-22526) — project a provider mutation
 * into the callable a `mutation` binding accepts, attaching the runtime's
 * §2.6 correlation keys (`actionInvocationId` / `optimisticWaveId` /
 * `rootId`) at each call. The keys are captured at call time — the callable
 * runs synchronously inside the action body — so out-of-process providers
 * that echo `correlation` (LLP 0034 §3.2) join the LLP 0231 action log
 * exactly like the in-process boundary provider's ambient capture does.
 */
export function createProviderMutation<T = unknown>(
  provider: ContractDataProvider,
  mutationName: string,
): (args?: Record<string, unknown>) => Promise<DataMutationResult<T>> {
  connectProviderReceipts(provider);
  return (args: Record<string, unknown> = {}) =>
    provider.mutate<T>(mutationName, args, buildDataMutationCorrelation());
}

// ---------------------------------------------------------------------------
// Force plane (ENG-22453; LLP 0284 §2.2/§2.5 drivability)
// ---------------------------------------------------------------------------
//
// One mechanism for both seams (query cells and ephemeral map cells):
// - Forcing delivers the forced cell to ALREADY-SUBSCRIBED observers, not
//   just observers that subscribe afterwards (the pre-existing gap: Design
//   Mode's force-then-clear gesture never reached a mounted binding).
// - While a force is active, live deliveries are suppressed but recorded.
// - Disposing the active force restores live delivery: suppressed observers
//   get the last live cell re-delivered; observers that subscribed while
//   forced start their live source only then (for ephemeral maps this is the
//   LOCAL-ONLY rule made structural — a forced map never reaches the
//   provider source, so it can never publish or allocate backend presence).

interface ForcePlaneRecord<Cell> {
  /** Normalized subscriber scope (`normalizeForceScope(args)`). */
  scopeKey: string;
  observer: (cell: Cell) => void;
  liveStarted: boolean;
  disposeLive: (() => void) | null;
  lastLiveCell: Cell | undefined;
  disposed: boolean;
  startLive: () => void;
}

interface ForcePlane<Cell> {
  subscribe(
    name: string,
    scopeKey: string,
    observer: (cell: Cell) => void,
    startLiveImpl: (record: ForcePlaneRecord<Cell>) => void,
  ): DataSubscription;
  /** `scopeKey` null = broadcast (name-only; the pre-scope semantics). */
  force(name: string, state: Cell, scopeKey?: string | null): DataForceHandle;
  isForced(name: string, scopeKey: string): boolean;
}

/**
 * Canonical scope identity for per-scope forcing (LLP 0284 §2.6 scope
 * identity; the §8.2 follow-up): sorted-key JSON so `{ a, b }` and `{ b, a }`
 * force together, matching how the Snapback adapter keys overlays per
 * (collection, scope). Non-serializable values degrade to String().
 */
export function normalizeForceScope(scope: Record<string, unknown>): string {
  const canonical = (value: unknown): unknown => {
    if (Array.isArray(value)) {
      return value.map(canonical);
    }
    if (value && typeof value === 'object') {
      const out: Record<string, unknown> = {};
      for (const key of Object.keys(value as Record<string, unknown>).sort()) {
        out[key] = canonical((value as Record<string, unknown>)[key]);
      }
      return out;
    }
    return value;
  };
  try {
    return JSON.stringify(canonical(scope));
  } catch {
    return String(scope);
  }
}

interface ActiveForce<Cell> {
  state: Cell;
  /** null = broadcast (name-only, the pre-scope semantics); string = one normalized scope. */
  scopeKey: string | null;
}

function createForcePlane<Cell>(pendingCell: () => Cell): ForcePlane<Cell> {
  // Per name, in force order — the LAST entry matching a record's scope
  // governs it (a later broadcast overrides an earlier scoped force and
  // vice versa, exactly like repeated name-only forces did).
  const forces = new Map<string, ActiveForce<Cell>[]>();
  const records = new Map<string, Set<ForcePlaneRecord<Cell>>>();

  const matches = (force: ActiveForce<Cell>, scopeKey: string): boolean =>
    force.scopeKey === null || force.scopeKey === scopeKey;
  const activeForceFor = (name: string, scopeKey: string): ActiveForce<Cell> | undefined => {
    const list = forces.get(name);
    if (!list) {
      return undefined;
    }
    for (let index = list.length - 1; index >= 0; index -= 1) {
      if (matches(list[index]!, scopeKey)) {
        return list[index];
      }
    }
    return undefined;
  };

  return {
    isForced(name: string, scopeKey: string): boolean {
      return activeForceFor(name, scopeKey) !== undefined;
    },

    subscribe(name, scopeKey, observer, startLiveImpl) {
      let set = records.get(name);
      if (!set) {
        set = new Set();
        records.set(name, set);
      }
      const record: ForcePlaneRecord<Cell> = {
        scopeKey,
        observer,
        liveStarted: false,
        disposeLive: null,
        lastLiveCell: undefined,
        disposed: false,
        startLive: () => {
          if (record.liveStarted || record.disposed) {
            return;
          }
          record.liveStarted = true;
          startLiveImpl(record);
        },
      };
      set.add(record);

      const force = activeForceFor(name, scopeKey);
      if (force) {
        // Live start deferred until the force disposes (local-only while
        // forced); the forced cell is the whole world for now.
        observer(force.state);
      } else {
        record.startLive();
      }

      return {
        dispose() {
          record.disposed = true;
          record.disposeLive?.();
          record.disposeLive = null;
          set.delete(record);
        },
      };
    },

    force(name, state, scopeKey = null) {
      let list = forces.get(name);
      if (!list) {
        list = [];
        forces.set(name, list);
      }
      const entry: ActiveForce<Cell> = { state, scopeKey };
      list.push(entry);
      for (const record of records.get(name) ?? []) {
        if (!record.disposed && matches(entry, record.scopeKey)) {
          record.observer(state);
        }
      }
      return {
        dispose() {
          const index = list!.indexOf(entry);
          if (index === -1) {
            return; // this handle already disposed
          }
          // Records this entry currently governs, captured before removal —
          // a superseded force (no longer anyone's active force) restores
          // nothing, exactly like the pre-scope superseded-handle no-op.
          const governed = [...(records.get(name) ?? [])].filter(
            (record) => !record.disposed && activeForceFor(name, record.scopeKey) === entry,
          );
          list!.splice(index, 1);
          for (const record of governed) {
            if (record.disposed) {
              // A restore delivery to an earlier record may synchronously
              // dispose a sibling (unmount cascade); re-check per iteration
              // so a disposed observer never receives a post-dispose cell.
              continue;
            }
            const next = activeForceFor(name, record.scopeKey);
            if (next) {
              // Another force (broadcast or this scope) still governs.
              record.observer(next.state);
              continue;
            }
            if (!record.liveStarted) {
              record.startLive();
            } else if (record.lastLiveCell !== undefined) {
              record.observer(record.lastLiveCell);
            } else {
              // The live source started but never delivered: restore to a
              // pending cell so forced data/connection cannot linger as if
              // it were current (adversarial-review hardening, ENG-22453).
              record.observer(pendingCell());
            }
          }
        },
      };
    },
  };
}

export function createBoundaryContractDataProvider(
  manifest: ContractDataManifest,
  boundary: ContractQueryBoundary,
  options: BoundaryDataProviderOptions,
): ContractDataProvider {
  const queryPlane = createForcePlane<DataCellV2>(() => ({ status: 'pending' }));
  const ephemeralPlane = createForcePlane<EphemeralMapCell>(() => ({
    status: 'pending',
    entries: [],
  }));

  // --- Receipts (LLP 0284 §2.6): bounded ring + listeners, the same
  // callback-plus-pull shape the Snapback kit exposes. ---
  const RECEIPT_RING_CAP = 256;
  const receiptRing: DataReceipt[] = [];
  const receiptListeners = new Set<DataReceiptListener>();
  let mutationSeq = 0;
  // One provider-level monotonic version, bumped per delivery: global
  // monotonicity implies the §2.6 per-binding monotonicity, and mutation
  // receipts land at a version subscription receipts can be joined against
  // ("converged to v42" stays checkable on this mock).
  let version = 0;
  const emitReceipt = (receipt: DataReceipt): void => {
    receiptRing.push(receipt);
    while (receiptRing.length > RECEIPT_RING_CAP) {
      receiptRing.shift();
    }
    receiptListeners.forEach((listener) => {
      try {
        listener(receipt);
      } catch {
        // Listener throws must never break provider delivery (kit parity).
      }
    });
  };

  // §2.6 binding identity: unique per subscription (`<name>#s<n>` — the
  // Snapback kit uses its subscriptionId the same way), so the per-binding
  // monotonicity rules hold under concurrent subscriptions on one
  // descriptor. Active row-query subscriptions are tracked so mutation
  // receipts can name the affected bindings (`bindingIds`).
  let subscriptionSeq = 0;
  const activeQueryBindings = new Map<string, { table: string | null }>();
  const activeBindingIdsFor = (affectedTables: readonly string[]): string[] =>
    [...activeQueryBindings.entries()]
      .filter(([, binding]) => binding.table !== null && affectedTables.includes(binding.table))
      .map(([bindingId]) => bindingId)
      .sort();

  const resolveLiveness = (name: string): NormalizedQueryLiveness | null => {
    const descriptor = manifest.queries[name];
    return descriptor ? normalizeQueryLiveness(descriptor, manifest.capabilities) : null;
  };
  // LLP 0284 §2.2 — the connection a delivery reports: the provider's
  // declared serving mode by default (`live`→'live', `poll`→'polling'; no
  // ongoing transport → absent); `options.connection` overrides per delivery
  // and falls through to the default when it returns undefined.
  const declaredConnection = (liveness: NormalizedQueryLiveness): DataConnection | undefined =>
    liveness.mode === 'live' ? 'live' : liveness.mode === 'poll' ? 'polling' : undefined;
  const connectionFor = (name: string, liveness: NormalizedQueryLiveness): DataConnection | undefined =>
    options.connection?.(name, liveness) ?? declaredConnection(liveness);

  // §2.6 subscription-receipt scaffold, shared by the row-query and
  // ephemeral seams: per-subscription-unique binding identity, versions,
  // established/disposed emission, and the connection stamp.
  const createSubscriptionReceipts = (
    name: string,
    args: Record<string, unknown>,
    liveness: NormalizedQueryLiveness | null,
    transportEligible: boolean,
  ) => {
    // §2.4 receipts policy is load-bearing: subscription receipts only when
    // the descriptor declares them (transport eligibility alone is not
    // consent to emit).
    const transport =
      transportEligible &&
      liveness &&
      liveness.mode !== 'snapshot' &&
      liveness.receipts === 'mutation+subscription'
        ? liveness.transport
        : undefined;
    // Captured at subscribe entry: the subscription belongs to the mount
    // that created it, so a disposal receipt emitted after a later mount
    // begins still joins the owning session.
    const rootId = currentDataRootId();
    const state = {
      bindingId: `${name}#s${++subscriptionSeq}`,
      established: false,
      snapshotVersion: 0,
      lastDeltaVersion: 0,
    };
    const emit = (event: SubscriptionReceipt['event']): void => {
      if (!transport) {
        return;
      }
      emitReceipt({
        kind: 'subscription',
        bindingId: state.bindingId,
        rootId,
        scope: { ...args },
        event,
        transport,
        snapshotVersion: state.snapshotVersion,
        lastDeltaVersion: state.lastDeltaVersion,
      });
    };
    return {
      state,
      /** Version every delivery and stamp its connection axis (§2.2). */
      note<Cell extends { connection?: DataConnection }>(cell: Cell): Cell {
        version += 1;
        state.lastDeltaVersion = version;
        if (cell.connection === undefined && liveness) {
          const connection = connectionFor(name, liveness);
          if (connection) {
            return { ...cell, connection };
          }
        }
        return cell;
      },
      /** Snapshot-with-subscribe (§2.1 rule 1): established carries the snapshot's version. */
      established(): void {
        state.snapshotVersion = state.lastDeltaVersion;
        if (!state.established) {
          state.established = true;
          emit('established');
        }
      },
      disposed(): void {
        if (state.established) {
          emit('disposed');
        }
      },
    };
  };

  return {
    manifest,
    subscribe<T>(
      queryName: string,
      args: Record<string, unknown>,
      observer: DataObserver<T>,
    ): DataSubscription {
      const descriptor = manifest.queries[queryName];
      const liveness = resolveLiveness(queryName);
      // §2.2/§2.6: connection and receipts only for subscription-backed
      // bindings — a resolved `snapshot` mode has no ongoing transport, so
      // the field's absence is itself the fact.
      const receipts = createSubscriptionReceipts(queryName, args, liveness, true);
      const scopeKey = normalizeForceScope(args);
      let registered = false;

      const subscription = queryPlane.subscribe(
        queryName,
        scopeKey,
        observer as (cell: DataCellV2) => void,
        (record) => {
          // Live deliveries: stamped with the connection axis, versioned for
          // receipts. Error paths that never establish a source deliver plain
          // cells (no connection claim on a binding with no transport).
          const deliver = (cell: DataCellV2): void => {
            const stamped = receipts.note(cell);
            record.lastLiveCell = stamped;
            if (!record.disposed && !queryPlane.isForced(queryName, scopeKey)) {
              record.observer(stamped);
            }
          };
          const deliverBindError = (error: SerializedError): void => {
            const cell: DataCellV2 = { status: 'error', error };
            record.lastLiveCell = cell;
            if (!record.disposed && !queryPlane.isForced(queryName, scopeKey)) {
              record.observer(cell);
            }
          };
          if (liveness?.ephemeral) {
            // LLP 0284 §2.4 kind mismatch, runtime half: an ephemeral
            // collection cannot serve a row-query binding (checked before the
            // factory lookup — ephemeral sources live in options.ephemerals).
            deliverBindError({
              message: `Data query "${queryName}" is an ephemeral collection; bind it with \`ephemeral\`, not \`query\` (LLP 0284 §2.4)`,
            });
            return;
          }
          const factory = options.queries[queryName];
          if (!descriptor || !factory) {
            deliverBindError({ message: `Unknown data query "${queryName}"` });
            return;
          }
          try {
            const result = factory(args, boundary);
            if (isContractQueryHandle(result)) {
              activeQueryBindings.set(receipts.state.bindingId, { table: result.table });
              registered = true;
              const boundarySubscription = boundary.subscribe(result, (rows) => {
                deliver(readyDataCell([...rows], descriptor));
              });
              record.disposeLive = () => boundarySubscription.dispose();
            } else {
              activeQueryBindings.set(receipts.state.bindingId, { table: null });
              registered = true;
              deliver(readyDataCell([...result], descriptor));
            }
            receipts.established();
          } catch (error) {
            deliverBindError(serializeDataError(error));
          }
        },
      );

      return {
        dispose() {
          subscription.dispose();
          if (registered) {
            registered = false;
            activeQueryBindings.delete(receipts.state.bindingId);
          }
          receipts.disposed();
        },
      };
    },

    subscribeEphemeral<V>(
      name: string,
      args: Record<string, unknown>,
      observer: EphemeralObserver<V>,
    ): DataSubscription {
      const liveness = resolveLiveness(name);
      const receipts = createSubscriptionReceipts(name, args, liveness, liveness?.ephemeral === true);
      const scopeKey = normalizeForceScope(args);

      const subscription = ephemeralPlane.subscribe(
        name,
        scopeKey,
        observer as (cell: EphemeralMapCell) => void,
        (record) => {
          const deliver = (cell: EphemeralMapCell): void => {
            const stamped = receipts.note(cell);
            record.lastLiveCell = stamped;
            if (!record.disposed && !ephemeralPlane.isForced(name, scopeKey)) {
              record.observer(stamped);
            }
          };
          const deliverBindError = (): void => {
            const cell: EphemeralMapCell = { status: 'error', entries: [] };
            record.lastLiveCell = cell;
            if (!record.disposed && !ephemeralPlane.isForced(name, scopeKey)) {
              record.observer(cell);
            }
          };
          // EphemeralMapCell carries no error payload (§2.5 normative
          // shape), so each hard-error path also dev-warns with its reason —
          // mirroring the adapter's no-support warning.
          const descriptor = manifest.queries[name];
          const source = options.ephemerals?.[name];
          if (!descriptor || !source) {
            console.warn(
              `[contract] unknown ephemeral collection "${name}" (no ${!descriptor ? 'manifest descriptor' : 'provider source'}); map renders as error`,
            );
            deliverBindError();
            return;
          }
          if (!liveness?.ephemeral) {
            // LLP 0284 §2.4 kind mismatch: nothing can serve an ephemeral
            // map from a non-ephemeral descriptor.
            console.warn(
              `[contract] descriptor "${name}" is not an ephemeral collection; bind it with \`query\` (LLP 0284 §2.4 kind mismatch); map renders as error`,
            );
            deliverBindError();
            return;
          }
          try {
            const disposal = source(args, (cell) => deliver(cell));
            if (disposal) {
              record.disposeLive =
                typeof disposal === 'function' ? disposal : () => disposal.dispose();
            }
            // Established only when the live source actually started — a map
            // subscribed under force never reaches here (§2.5 local-only),
            // so forced maps emit no receipts by construction.
            receipts.established();
          } catch (error) {
            console.warn(`[contract] ephemeral source "${name}" threw during subscribe`, error);
            deliverBindError();
          }
        },
      );

      return {
        dispose() {
          subscription.dispose();
          receipts.disposed();
        },
      };
    },

    async mutate<T>(
      mutationName: string,
      args: Record<string, unknown>,
      correlation?: DataMutationCorrelation,
    ): Promise<DataMutationResult<T>> {
      const descriptor = manifest.mutations[mutationName];
      const mutation = options.mutations?.[mutationName];
      if (!descriptor || !mutation) {
        return { ok: false, error: { message: `Unknown data mutation "${mutationName}"` } };
      }
      // §2.6 adapter-stitched keys, captured at the synchronous entry —
      // `mutate` is called inside the action body, so the ambient action
      // invocation id (and the settling-flush wave id) join this receipt to
      // the LLP 0231 action log. In-process ambient truth wins; the caller's
      // correlation fills gaps (the out-of-process convention, LLP 0034
      // §3.2) and is echoed verbatim for the log's lift.
      const actionInvocationId = currentActionInvocationId() ?? correlation?.actionInvocationId;
      const optimisticWaveId = currentOptimisticWaveId() ?? correlation?.optimisticWaveId;
      const rootId = currentDataRootId();
      // Defensive: mutate() must never throw (it resolves to a
      // DataMutationResult). A malformed descriptor without a writes array
      // yields null — the §2.6 explicit-unknown convention.
      const affectedTables = Array.isArray(descriptor.writes) ? [...descriptor.writes] : null;
      const mutationReceipt = (outcome: 'confirmed' | 'rejected', rollbackReason?: string): void => {
        emitReceipt({
          kind: 'mutation',
          mutationId: `mut_${++mutationSeq}`,
          ...(actionInvocationId ? { actionInvocationId } : {}),
          ...(optimisticWaveId ? { optimisticWaveId } : {}),
          bindingIds: activeBindingIdsFor(affectedTables ?? []),
          rootId,
          affectedTables,
          outcome,
          ...(rollbackReason ? { rollbackReason } : {}),
          // In-process boundary mutations travel locally (provider-declared;
          // distinct from SubscriptionReceipt.transport's delta enum).
          transport: 'local',
          snapshotVersion: version,
          ...(correlation ? { correlation: { ...correlation } } : {}),
        });
      };
      try {
        const value = await mutation(args, boundary);
        // The boundary write's notifications have already flushed
        // synchronously, so `version` is the version the outcome landed at.
        mutationReceipt('confirmed');
        return { ok: true, value: value as T };
      } catch (error) {
        mutationReceipt('rejected', serializeDataError(error).message);
        return { ok: false, error: serializeDataError(error) };
      }
    },

    async getRowSyncState(table: string, rowId: string): Promise<DataRowSyncState | null> {
      return options.rowSyncState ? await options.rowSyncState(table, rowId) : null;
    },

    forceQueryState(
      queryName: string,
      state: ForcedDataState,
      options?: DataForceOptions,
    ): DataForceHandle {
      return queryPlane.force(
        queryName,
        state,
        options?.scope ? normalizeForceScope(options.scope) : null,
      );
    },

    // LOCAL-ONLY by construction (LLP 0284 §2.5): the forced cell reaches
    // local observers; provider sources are never invoked while forced.
    forceEphemeralState(
      name: string,
      state: ForcedEphemeralState,
      options?: DataForceOptions,
    ): DataForceHandle {
      return ephemeralPlane.force(
        name,
        state,
        options?.scope ? normalizeForceScope(options.scope) : null,
      );
    },

    // LLP 0284 §2.6 receipt observation — kit-shaped: callback returning a
    // plain unsubscribe, plus a pull ring (oldest first).
    onReceipt(listener: DataReceiptListener): () => void {
      receiptListeners.add(listener);
      return () => {
        receiptListeners.delete(listener);
      };
    },
    receipts(): DataReceipt[] {
      return receiptRing.slice();
    },
  };
}
