// @system @ref LLP 0208 A1 - Per-axis Design Mode layout relationships.
//
// This composes the A0 axis-scope ladder with LLP 0199 relationship values.
// It does not add a mutator or a measured-layout feedback channel.

import type { Expr, LayoutRelationOp } from '../compiler/ir.js';
import {
  createContractAxisScopedEdit,
  resolveContractAxisScopedOverride,
  type ContractAxisScope,
  type ContractAxisScopedAuthority,
  type ContractAxisScopedBaseOp,
  type ContractAxisScopedEdit,
  type ContractAxisScopedOverrideStore,
} from './axis-scope.js';
import {
  applyStyleValue,
  createContractRelation,
} from './layout-intent.js';

export const CONTRACT_AXIS_RELATIONS_SCHEMA_VERSION = 1;

export type ContractAxisRelationResolutionKind = 'relation' | 'literal';

export interface ContractAxisRelationIntent {
  kind: 'relation-intent';
  op: LayoutRelationOp;
  args: readonly unknown[];
  fallback: unknown;
  source?: string;
  measuredTier: boolean;
}

export interface ContractAxisRelationLiteral {
  kind: 'literal-fallback';
  value: unknown;
  degradedFrom?: LayoutRelationOp;
  source?: string;
}

export type ContractAxisRelationValue =
  | ContractAxisRelationIntent
  | ContractAxisRelationLiteral;

export interface ContractAxisRelationScopedEditInput {
  authority: ContractAxisScopedAuthority;
  op: ContractAxisScopedBaseOp;
  scope: ContractAxisScope;
  relation: ContractAxisRelationIntent;
  relationshipsAvailable?: boolean;
}

export interface ContractAxisRelationResolution {
  schemaVersion: typeof CONTRACT_AXIS_RELATIONS_SCHEMA_VERSION;
  kind: ContractAxisRelationResolutionKind;
  edit: ContractAxisScopedEdit;
  scope: ContractAxisScope;
  storage: ContractAxisScopedEdit['storage'];
  opTargetKey: string;
  styleProp: string;
  style: Record<string, unknown>;
  relation?: ContractAxisRelationIntent;
  literal?: ContractAxisRelationLiteral;
  measuredTierBlocked: boolean;
}

const MEASURED_RELATIONS = new Set<LayoutRelationOp>([
  'matchWidth',
  'matchHeight',
  'alignTo',
]);

function exprToRuntimeValue(expr: Expr): unknown {
  switch (expr.kind) {
    case 'number':
      return expr.value;
    case 'string':
      return expr.value;
    case 'boolean':
      return expr.value;
    case 'null':
      return null;
    case 'token':
      return `$${expr.path}`;
    case 'ident':
      return expr.name;
    default:
      return expr;
  }
}

function isAxisRelationIntent(value: unknown): value is ContractAxisRelationIntent {
  return (
    value !== null &&
    typeof value === 'object' &&
    (value as Record<string, unknown>).kind === 'relation-intent'
  );
}

function isAxisRelationLiteral(value: unknown): value is ContractAxisRelationLiteral {
  return (
    value !== null &&
    typeof value === 'object' &&
    (value as Record<string, unknown>).kind === 'literal-fallback'
  );
}

function relationStyleProp(op: ContractAxisScopedBaseOp): string {
  return typeof op.attr === 'string' ? op.attr : 'value';
}

export function createContractAxisRelationIntent(
  op: LayoutRelationOp,
  args: readonly unknown[],
  fallback: unknown,
  source?: string,
): ContractAxisRelationIntent {
  return {
    kind: 'relation-intent',
    op,
    args: [...args],
    fallback,
    source,
    measuredTier: MEASURED_RELATIONS.has(op),
  };
}

export function createContractAxisRelationIntentFromExpr(
  expr: Expr,
  fallback: unknown,
  source?: string,
): ContractAxisRelationIntent {
  if (expr.kind !== 'relation') {
    throw new Error(`Expected relation expression, got ${expr.kind}`);
  }
  return createContractAxisRelationIntent(
    expr.op,
    expr.args.map(exprToRuntimeValue),
    fallback,
    source,
  );
}

export function degradeContractAxisRelationIntent(
  relation: ContractAxisRelationIntent,
): ContractAxisRelationLiteral {
  return {
    kind: 'literal-fallback',
    value: relation.fallback,
    degradedFrom: relation.op,
    source: relation.source,
  };
}

export function createContractAxisRelationScopedEdit(
  input: ContractAxisRelationScopedEditInput,
): ContractAxisScopedEdit {
  const value =
    input.relationshipsAvailable === false
      ? degradeContractAxisRelationIntent(input.relation)
      : input.relation;
  return createContractAxisScopedEdit({
    authority: input.authority,
    op: {
      ...input.op,
      value,
    },
    scope: input.scope,
  });
}

export function resolveContractAxisRelation(
  store: ContractAxisScopedOverrideStore,
  op: ContractAxisScopedBaseOp,
  axisValues: Record<string, string>,
): ContractAxisRelationResolution | null {
  const edit = resolveContractAxisScopedOverride(store, op, axisValues);
  if (!edit) return null;

  const value = edit.op.value;
  const styleProp = relationStyleProp(edit.op);
  const style: Record<string, unknown> = {};

  if (isAxisRelationIntent(value)) {
    applyStyleValue(
      style,
      styleProp,
      createContractRelation(value.op, value.args, value.fallback),
    );
    return {
      schemaVersion: CONTRACT_AXIS_RELATIONS_SCHEMA_VERSION,
      kind: 'relation',
      edit,
      scope: edit.scope,
      storage: edit.storage,
      opTargetKey: edit.opTargetKey,
      styleProp,
      style,
      relation: value,
      measuredTierBlocked: value.measuredTier,
    };
  }

  const literal = isAxisRelationLiteral(value)
    ? value
    : { kind: 'literal-fallback' as const, value };
  applyStyleValue(style, styleProp, literal.value);
  return {
    schemaVersion: CONTRACT_AXIS_RELATIONS_SCHEMA_VERSION,
    kind: 'literal',
    edit,
    scope: edit.scope,
    storage: edit.storage,
    opTargetKey: edit.opTargetKey,
    styleProp,
    style,
    literal,
    measuredTierBlocked: false,
  };
}
