// @system @ref LLP 0208 M1 — Design Mode scenario matrix preview.
//
// The matrix is derived from Contract IR + the generated scenario manifest. It
// keeps contract checks ahead of paint and uses the shared list virtualizer so
// the selected sub-product never becomes an eager cross-product mount.

import {
  computeVirtualItemsFromPrepared,
  prepareVirtualList,
  type ListDiagnostics,
} from '@exact/list-core';

import type {
  ContractDesignModeScenarioManifest,
  ContractScenarioAxisId,
} from '../compiler/scenario-manifest.js';
import type { ComponentIR, ContractFileIR } from '../compiler/ir.js';
import { toUiContract, type EmittedUiContract } from './contracts.js';

type MatrixEmittedClause = EmittedUiContract['clauses'][number];

export const CONTRACT_DESIGN_MODE_MATRIX_SCHEMA_VERSION = 1;

export interface ContractScenarioSemanticsNode {
  text?: string;
  role?: string;
  label?: string;
  testId?: string;
  type?: string;
  value?: string | number | boolean;
  visible?: boolean;
  interactable?: boolean;
  disabled?: boolean;
  checked?: boolean | 'mixed';
}

export interface ContractScenarioMatrixCellInput {
  id: string;
  index: number;
  axisValues: Record<string, string>;
}

export type ContractScenarioSemanticsProvider = (
  cell: ContractScenarioMatrixCellInput,
) => readonly ContractScenarioSemanticsNode[];

export interface ContractScenarioMatrixOptions {
  selectedAxes?: readonly ContractScenarioAxisId[];
  viewportSize?: number;
  scrollOffset?: number;
  drawDistance?: number;
  estimatedCellSize?: number;
  maxMountedCells?: number;
  renderBudgetMs?: number;
  mountedCellCostMs?: number;
  contractCheckCostMs?: number;
  semantics?: ContractScenarioSemanticsProvider;
}

export interface ContractScenarioClauseResult {
  kind: string;
  ok: boolean;
  description: string;
  message: string;
  checkedBeforePaint: true;
}

export interface ContractScenarioContractBadge {
  status: 'pass' | 'fail';
  checkedBeforePaint: true;
  clauseCount: number;
  failureCount: number;
  failures: ContractScenarioClauseResult[];
}

export interface ContractScenarioMatrixCell {
  id: string;
  index: number;
  axisValues: Record<string, string>;
  contract: ContractScenarioContractBadge;
  mount: {
    inVirtualWindow: boolean;
    mounted: boolean;
    painted: boolean;
    stage: 'painted' | 'badged-before-paint' | 'not-mounted';
    reason: 'within-window' | 'contract-failed-before-paint' | 'offscreen';
  };
}

export interface ContractScenarioMatrixMetrics {
  availableAxisCellCount: number;
  selectedCellCount: number;
  checkedCellCount: number;
  virtualWindowCellCount: number;
  mountedCellCount: number;
  offscreenCellCount: number;
  offscreenMountedCount: number;
  failedCellCount: number;
  suppressedPaintCount: number;
  eagerSelectedProductWouldFail: boolean;
  estimatedRenderCostMs: number;
}

export interface ContractDesignModeScenarioMatrixPreview {
  schemaVersion: typeof CONTRACT_DESIGN_MODE_MATRIX_SCHEMA_VERSION;
  provenance: {
    authority: 'contract-ir+scenario-manifest';
    generator: '@exact/contract/runtime/scenario-matrix';
    command: 'bun scripts/check-contract-design-mode-matrix.mjs --write';
    llp: 'LLP 0208 M1';
  };
  surface: ContractDesignModeScenarioManifest['surface'];
  selectedAxes: ContractScenarioAxisId[];
  contract: {
    id: string;
    title: string;
    clauseCount: number;
  };
  virtualizer: {
    viewportSize: number;
    scrollOffset: number;
    drawDistance: number;
    estimatedCellSize: number;
    diagnostics: ListDiagnostics;
  };
  budget: {
    ok: boolean;
    maxMountedCells: number;
    renderBudgetMs: number;
    estimatedRenderCostMs: number;
  };
  metrics: ContractScenarioMatrixMetrics;
  cells: ContractScenarioMatrixCell[];
}

const DEFAULT_VIEWPORT_SIZE = 360;
const DEFAULT_ESTIMATED_CELL_SIZE = 120;
const DEFAULT_MAX_MOUNTED_CELLS = 6;
const DEFAULT_RENDER_BUDGET_MS = 12;
const DEFAULT_MOUNTED_CELL_COST_MS = 2;
const DEFAULT_CONTRACT_CHECK_COST_MS = 0.05;

function axisCellCount(manifest: ContractDesignModeScenarioManifest): number {
  return manifest.axes.reduce((total, axis) => total * Math.max(1, axis.values.length), 1);
}

function selectedAxesFor(
  manifest: ContractDesignModeScenarioManifest,
  options: ContractScenarioMatrixOptions,
): ContractScenarioAxisId[] {
  const available = new Set(manifest.axes.map((axis) => axis.id));
  const selected = [...(options.selectedAxes ?? manifest.defaultMatrix.selectedAxes)];
  for (const axisId of selected) {
    if (!available.has(axisId)) {
      throw new Error(`Scenario matrix axis ${axisId} is not available for ${manifest.surface.component}`);
    }
  }
  return selected;
}

function cellId(axisValues: Record<string, string>): string {
  return Object.entries(axisValues)
    .map(([axis, value]) => `${axis}=${value}`)
    .join('|');
}

function expandCells(
  manifest: ContractDesignModeScenarioManifest,
  selectedAxes: readonly ContractScenarioAxisId[],
): ContractScenarioMatrixCellInput[] {
  const axes = selectedAxes.map((axisId) => {
    const axis = manifest.axes.find((candidate) => candidate.id === axisId);
    if (!axis) {
      throw new Error(`Scenario matrix axis ${axisId} disappeared while expanding cells`);
    }
    return axis;
  });

  const cells: ContractScenarioMatrixCellInput[] = [];
  const visit = (index: number, axisValues: Record<string, string>): void => {
    if (index >= axes.length) {
      cells.push({
        id: cellId(axisValues),
        index: cells.length,
        axisValues: { ...axisValues },
      });
      return;
    }
    const axis = axes[index];
    for (const value of axis.values) {
      visit(index + 1, { ...axisValues, [axis.id]: value });
    }
  };

  visit(0, {});
  return cells;
}

function componentFor(file: ContractFileIR, name: string): ComponentIR {
  const component = file.components.find((candidate) => candidate.name === name) ?? file.components[0];
  if (!component) {
    throw new Error('Scenario matrix requires at least one Contract component');
  }
  return component;
}

function defaultSemantics(): readonly ContractScenarioSemanticsNode[] {
  return [];
}

function normalize(value: unknown): string {
  return typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '';
}

function describeSelector(selector: Record<string, unknown>): string {
  if (typeof selector.description === 'string') return selector.description;
  if (typeof selector.testId === 'string') return `node testId="${selector.testId}"`;
  if (typeof selector.role === 'string' && typeof selector.label === 'string') {
    return `${selector.role} "${selector.label}"`;
  }
  if (typeof selector.type === 'string' && typeof selector.label === 'string') {
    return `${selector.type} "${selector.label}"`;
  }
  if (typeof selector.text === 'string') return `text "${selector.text}"`;
  return 'selector';
}

function selectorMatches(
  node: ContractScenarioSemanticsNode,
  selector: Record<string, unknown>,
): boolean {
  if (selector.visible !== undefined && (node.visible ?? true) !== selector.visible) return false;
  if (selector.interactable !== undefined && (node.interactable ?? true) !== selector.interactable) {
    return false;
  }
  if (typeof selector.testId === 'string' && node.testId !== selector.testId) return false;
  if (typeof selector.role === 'string' && node.role !== selector.role) return false;
  if (typeof selector.type === 'string' && node.type !== selector.type) return false;
  if (typeof selector.label === 'string' && normalize(node.label) !== normalize(selector.label)) {
    return false;
  }
  if (typeof selector.text === 'string' && normalize(node.text) !== normalize(selector.text)) {
    return false;
  }
  return true;
}

function matchesFor(
  nodes: readonly ContractScenarioSemanticsNode[],
  selector: Record<string, unknown>,
): ContractScenarioSemanticsNode[] {
  return nodes.filter((node) => selectorMatches(node, selector));
}

function evaluateState(
  node: ContractScenarioSemanticsNode,
  expected: Record<string, unknown>,
): string[] {
  const failures: string[] = [];
  if (expected.value !== undefined && node.value !== expected.value) {
    failures.push(`value expected ${JSON.stringify(expected.value)} got ${JSON.stringify(node.value)}`);
  }
  if (expected.disabled !== undefined && (node.disabled ?? false) !== expected.disabled) {
    failures.push(`disabled expected ${String(expected.disabled)} got ${String(node.disabled ?? false)}`);
  }
  if (expected.checked !== undefined && node.checked !== expected.checked) {
    failures.push(`checked expected ${JSON.stringify(expected.checked)} got ${JSON.stringify(node.checked)}`);
  }
  if (expected.interactable !== undefined && (node.interactable ?? true) !== expected.interactable) {
    failures.push(`interactable expected ${String(expected.interactable)} got ${String(node.interactable ?? true)}`);
  }
  return failures;
}

function evaluateAssertionClause(
  clause: MatrixEmittedClause,
  nodes: readonly ContractScenarioSemanticsNode[],
): ContractScenarioClauseResult {
  const selector = (clause.selector && typeof clause.selector === 'object' ? clause.selector : {}) as Record<string, unknown>;
  const description = describeSelector(selector);
  const matches = matchesFor(nodes, selector);

  switch (clause.kind) {
    case 'has':
      return {
        kind: clause.kind,
        ok: matches.length > 0,
        description: `has ${description}`,
        message: matches.length > 0 ? `Found ${matches.length} pre-paint match(es).` : 'No pre-paint matches found.',
        checkedBeforePaint: true,
      };
    case 'missing':
      return {
        kind: clause.kind,
        ok: matches.length === 0,
        description: `missing ${description}`,
        message: matches.length === 0 ? 'Selector is absent before paint.' : `Expected no matches, found ${matches.length}.`,
        checkedBeforePaint: true,
      };
    case 'count': {
      const expected = typeof clause.expected === 'number' ? clause.expected : NaN;
      return {
        kind: clause.kind,
        ok: matches.length === expected,
        description: `count ${description}`,
        message: matches.length === expected
          ? `Found ${expected} pre-paint match(es).`
          : `Expected ${expected} match(es), found ${matches.length}.`,
        checkedBeforePaint: true,
      };
    }
    case 'state': {
      const expected = (clause.expected && typeof clause.expected === 'object' ? clause.expected : {}) as Record<string, unknown>;
      if (matches.length !== 1) {
        return {
          kind: clause.kind,
          ok: false,
          description: `state ${description}`,
          message: `Expected one pre-paint state target, found ${matches.length}.`,
          checkedBeforePaint: true,
        };
      }
      const failures = evaluateState(matches[0], expected);
      return {
        kind: clause.kind,
        ok: failures.length === 0,
        description: `state ${description}`,
        message: failures.length === 0 ? 'State matched before paint.' : failures.join('; '),
        checkedBeforePaint: true,
      };
    }
    default:
      return {
        kind: String(clause.kind),
        ok: true,
        description: String(clause.kind),
        message: 'Clause kind has no pre-paint assertion hook.',
        checkedBeforePaint: true,
      };
  }
}

function evaluatePressClause(
  clause: MatrixEmittedClause,
  nodes: readonly ContractScenarioSemanticsNode[],
): ContractScenarioClauseResult[] {
  const target = (clause.target && typeof clause.target === 'object' ? clause.target : {}) as Record<string, unknown>;
  const targetMatches = matchesFor(nodes, target);
  const targetDescription = describeSelector(target);
  const targetResult: ContractScenarioClauseResult = {
    kind: 'press',
    ok: targetMatches.length === 1,
    description: `press ${targetDescription}`,
    message: targetMatches.length === 1
      ? 'Press target exists in the pre-paint semantics tree.'
      : `Expected one press target before paint, found ${targetMatches.length}.`,
    checkedBeforePaint: true,
  };
  const expects = Array.isArray(clause.expects) ? clause.expects : [];
  return [
    targetResult,
    ...expects.map((expectation) => evaluateAssertionClause(expectation as MatrixEmittedClause, nodes)),
  ];
}

function evaluateContractBadge(
  contract: EmittedUiContract,
  nodes: readonly ContractScenarioSemanticsNode[],
): ContractScenarioContractBadge {
  const results = contract.clauses.flatMap((clause) =>
    clause.kind === 'press'
      ? evaluatePressClause(clause, nodes)
      : evaluateAssertionClause(clause, nodes),
  );
  const failures = results.filter((result) => !result.ok);
  return {
    status: failures.length === 0 ? 'pass' : 'fail',
    checkedBeforePaint: true,
    clauseCount: results.length,
    failureCount: failures.length,
    failures,
  };
}

export function buildContractDesignModeScenarioMatrix(
  file: ContractFileIR,
  manifest: ContractDesignModeScenarioManifest,
  options: ContractScenarioMatrixOptions = {},
): ContractDesignModeScenarioMatrixPreview {
  const selectedAxes = selectedAxesFor(manifest, options);
  const cells = expandCells(manifest, selectedAxes);
  const estimatedCellSize = options.estimatedCellSize ?? DEFAULT_ESTIMATED_CELL_SIZE;
  const viewportSize = options.viewportSize ?? DEFAULT_VIEWPORT_SIZE;
  const scrollOffset = options.scrollOffset ?? 0;
  const drawDistance = options.drawDistance ?? 0;
  const maxMountedCells = options.maxMountedCells ?? DEFAULT_MAX_MOUNTED_CELLS;
  const renderBudgetMs = options.renderBudgetMs ?? DEFAULT_RENDER_BUDGET_MS;
  const mountedCellCostMs = options.mountedCellCostMs ?? DEFAULT_MOUNTED_CELL_COST_MS;
  const contractCheckCostMs = options.contractCheckCostMs ?? DEFAULT_CONTRACT_CHECK_COST_MS;
  const semantics = options.semantics ?? defaultSemantics;
  const component = componentFor(file, manifest.surface.component);
  const contract = toUiContract(component, {
    basePath: manifest.surface.routePath ?? manifest.surface.sourcePath ?? '/',
    id: `contract/${manifest.surface.component}/scenario-matrix`,
    title: `${manifest.surface.component} scenario matrix contract`,
  });

  const prepared = prepareVirtualList({
    count: cells.length,
    estimatedItemSize: estimatedCellSize,
    getKey: (index) => cells[index]?.id ?? `cell-${index}`,
  });
  const virtualized = computeVirtualItemsFromPrepared(prepared, {
    scrollOffset,
    viewportSize,
    drawDistance,
  });
  const windowIndices = new Set(virtualized.items.map((item) => item.index));

  const renderedCells = cells.map((cell): ContractScenarioMatrixCell => {
    const contractBadge = evaluateContractBadge(contract, semantics(cell));
    const inVirtualWindow = windowIndices.has(cell.index);
    const mounted = inVirtualWindow && contractBadge.status === 'pass';
    const failedBeforePaint = inVirtualWindow && contractBadge.status === 'fail';
    return {
      ...cell,
      contract: contractBadge,
      mount: {
        inVirtualWindow,
        mounted,
        painted: mounted,
        stage: mounted ? 'painted' : failedBeforePaint ? 'badged-before-paint' : 'not-mounted',
        reason: mounted
          ? 'within-window'
          : failedBeforePaint
            ? 'contract-failed-before-paint'
            : 'offscreen',
      },
    };
  });

  const mountedCellCount = renderedCells.filter((cell) => cell.mount.mounted).length;
  const failedCellCount = renderedCells.filter((cell) => cell.contract.status === 'fail').length;
  const virtualWindowCellCount = renderedCells.filter((cell) => cell.mount.inVirtualWindow).length;
  const offscreenCellCount = renderedCells.length - virtualWindowCellCount;
  const offscreenMountedCount = renderedCells.filter((cell) => !cell.mount.inVirtualWindow && cell.mount.mounted).length;
  const suppressedPaintCount = renderedCells.filter(
    (cell) => cell.mount.inVirtualWindow && cell.contract.status === 'fail' && !cell.mount.painted,
  ).length;
  const checkedCellCount = renderedCells.length;
  const estimatedRenderCostMs =
    mountedCellCount * mountedCellCostMs + checkedCellCount * contractCheckCostMs;
  const budgetOk =
    mountedCellCount <= maxMountedCells &&
    offscreenMountedCount === 0 &&
    estimatedRenderCostMs <= renderBudgetMs;

  return {
    schemaVersion: CONTRACT_DESIGN_MODE_MATRIX_SCHEMA_VERSION,
    provenance: {
      authority: 'contract-ir+scenario-manifest',
      generator: '@exact/contract/runtime/scenario-matrix',
      command: 'bun scripts/check-contract-design-mode-matrix.mjs --write',
      llp: 'LLP 0208 M1',
    },
    surface: manifest.surface,
    selectedAxes,
    contract: {
      id: contract.id,
      title: contract.title,
      clauseCount: contract.clauses.length,
    },
    virtualizer: {
      viewportSize,
      scrollOffset,
      drawDistance,
      estimatedCellSize,
      diagnostics: {
        ...virtualized.diagnostics,
        mountedItemCount: mountedCellCount,
      },
    },
    budget: {
      ok: budgetOk,
      maxMountedCells,
      renderBudgetMs,
      estimatedRenderCostMs,
    },
    metrics: {
      availableAxisCellCount: axisCellCount(manifest),
      selectedCellCount: renderedCells.length,
      checkedCellCount,
      virtualWindowCellCount,
      mountedCellCount,
      offscreenCellCount,
      offscreenMountedCount,
      failedCellCount,
      suppressedPaintCount,
      eagerSelectedProductWouldFail: renderedCells.length > maxMountedCells,
      estimatedRenderCostMs,
    },
    cells: renderedCells,
  };
}
