// @system @ref LLP 0280 §2.1 — behavior template derive recompute on refresh.
//
// The state-preserving refresh path splices edited behavior derive formulas
// into the live IR in place (hot-patch.ts), but a computed only re-evaluates
// when its reactive dependencies change — a formula edit alone would leave
// stale derived output on screen. Every live behavior instance therefore
// threads a module-scoped revision signal through its derive computeds;
// bumping it after a splice recomputes every behavior derive of that module,
// at every instantiation site, in one flush. This is what lets behavior
// derive-body edits PRESERVE state (LLP 0280 §2.1's compatibility rule)
// where component derive edits still reset (`derive_formula_changed`).

import { signal, type Signal } from './signals.js';

const revisions = new Map<string, Signal<number>>();

/**
 * The revision signal for a module's behavior instances. Reading it inside
 * a derive computed subscribes the computed to refresh bumps.
 */
export function behaviorDeriveRevision(sourcePath: string): Signal<number> {
  let revision = revisions.get(sourcePath);
  if (!revision) {
    revision = signal(0);
    revisions.set(sourcePath, revision);
  }
  return revision;
}

/** Recomputes every live behavior derive of the module (hot-patch splice). */
export function bumpBehaviorDeriveRevisions(sourcePath: string): void {
  const revision = revisions.get(sourcePath);
  if (revision) {
    revision.set(revision.peek() + 1);
  }
}

export function _resetBehaviorDeriveRevisionsForTests(): void {
  revisions.clear();
}
