// @system @ref LLP 0166 §4.2 — the editable-slot catalog.
//
// A compiler-derived enumeration of every writable position in a parsed
// `.contract` file: text literals, attr values, prop defaults, state
// initials, and param defaults — each with its exact span, staleness guard
// (the exact current source text), value classification, writability (with
// the locked reason preserved), and hot-patch policy. The catalog is
// DERIVED, never stored: a pure function of the IR plus the source text, so
// it cannot drift from either. Every consumer of "what is editable here" —
// the Design Mode panel, the edit authority (§4.3), agent metadata, the
// prompt bundle, verification, and HMR classification — reads this
// enumeration instead of re-deriving writability.

import type { ComponentIR, ContractFileIR, Expr, ParsedType, Span } from './ir.js';
import { hashSource } from './hash.js';
import { walkStructuralPaths } from './identity.js';

export type SlotValueKind = 'literal' | 'token' | 'relation' | 'computed';

export type SlotWritability =
  | { ok: true }
  | { ok: false; reason: 'computed' | 'template' | 'unsupported' };

/** What a committed change to this slot costs at runtime (LLP 0166 §4.8). */
export type SlotHotPatchPolicy = 'host-prop' | 'text' | 'reset';

export type SlotRef =
  | { kind: 'text' }
  | { kind: 'attr'; name: string }
  | { kind: 'prop_default'; name: string }
  | { kind: 'state_initial'; name: string }
  | { kind: 'param_default'; name: string };

export interface EditableSlotIR {
  /** Stable within (sourcePath, sourceVersion). */
  slotId: string;
  component: string;
  /** Structural node id (§4.7 static derivation) for view-section slots. */
  nodeId?: string;
  section: 'view' | 'props' | 'state' | 'params';
  slot: SlotRef;
  span: Span;
  /** Exact current source text of the value — the staleness guard. */
  guard: string;
  value: Expr;
  valueKind: SlotValueKind;
  /** Structured type for typed slots (prop defaults; LLP 0166 §4.5). */
  type?: ParsedType;
  /**
   * Writability with the locked reason preserved — the panel's
   * locked-with-reason UX (LLP 0158 §4.3) renders straight from this.
   */
  writable: SlotWritability;
  hotPatch: SlotHotPatchPolicy;
}

export interface EditableSlotCatalog {
  sourcePath?: string;
  /**
   * Content hash of the source this catalog was derived from — the same
   * SHA-256-prefix hash the LLP 0158 staleness protocol exchanges.
   */
  sourceVersion: string;
  slots: EditableSlotIR[];
}

/**
 * A slot site without source-text fields — the pure-IR layer shared by the
 * catalog (which adds span + guard from the source) and the S4 hot-patch
 * differ (which has no source, only two IRs).
 */
export interface SlotSiteIR {
  slotId: string;
  component: string;
  nodeId?: string;
  section: EditableSlotIR['section'];
  slot: SlotRef;
  value: Expr;
  valueKind: SlotValueKind;
  type?: ParsedType;
  writable: SlotWritability;
  hotPatch: SlotHotPatchPolicy;
}

interface ValueClassification {
  valueKind: SlotValueKind;
  writable: SlotWritability;
}

function isNegativeNumber(expr: Expr): boolean {
  return expr.kind === 'unary' && expr.op === '-' && expr.operand.kind === 'number';
}

/** Dot path of a member chain rooted at a bare identifier, or null. */
function memberChainPath(expr: Expr): { root: string; path: string[] } | null {
  const path: string[] = [];
  let cursor: Expr = expr;
  while (cursor.kind === 'member') {
    path.unshift(cursor.property);
    cursor = cursor.object;
  }
  if (cursor.kind === 'ident' && path.length > 0) {
    return { root: cursor.name, path };
  }
  return null;
}

/**
 * Classifies one slot value. Literals (including negative numbers) are
 * writable; template strings are present-but-locked (`reason: 'template'`,
 * v0 — editing static template segments is a graduation question, LLP 0166
 * OQ5); theme-rooted member chains classify as token references (the pre-S1
 * static approximation of the provenance classifier's theme.* case);
 * everything else is computed and locked. Locked rows are information, not
 * omissions.
 */
function classifyValue(expr: Expr): ValueClassification {
  switch (expr.kind) {
    case 'string':
    case 'number':
    case 'boolean':
    case 'null':
      return { valueKind: 'literal', writable: { ok: true } };
    case 'token':
      // First-class `$` reference (LLP 0166 §4.4): statically token, exact.
      return { valueKind: 'token', writable: { ok: true } };
    case 'relation':
      // First-class layout relationship (LLP 0199): editable intent, not a
      // plain literal. The commit plane may still choose a richer control.
      return { valueKind: 'relation', writable: { ok: true } };
    case 'template':
      return { valueKind: 'computed', writable: { ok: false, reason: 'template' } };
    case 'unary':
      if (isNegativeNumber(expr)) {
        return { valueKind: 'literal', writable: { ok: true } };
      }
      return { valueKind: 'computed', writable: { ok: false, reason: 'computed' } };
    case 'member': {
      const chain = memberChainPath(expr);
      if (chain && chain.root === 'theme') {
        return { valueKind: 'token', writable: { ok: true } };
      }
      return { valueKind: 'computed', writable: { ok: false, reason: 'computed' } };
    }
    default:
      return { valueKind: 'computed', writable: { ok: false, reason: 'computed' } };
  }
}

function semanticAttrType(name: string, value: Expr): Pick<ValueSlotInput, 'type' | 'writable'> {
  if (name === 'live') {
    const span = value.span ?? { line: 0, col: 0, offset: 0, len: 0 };
    return {
      type: {
        raw: '"polite" | "assertive"',
        ir: { kind: 'literal-union', values: ['polite', 'assertive'] },
        span,
        diagnostics: [],
      },
    };
  }
  if (name === 'presence') {
    const span = value.span ?? { line: 0, col: 0, offset: 0, len: 0 };
    return {
      type: {
        raw: '"entering" | "entered" | "exiting"',
        ir: { kind: 'literal-union', values: ['entering', 'entered', 'exiting'] },
        span,
        diagnostics: [],
      },
      writable: { ok: false, reason: 'unsupported' },
    };
  }
  if (name === 'headingLevel' || name === 'for' || name === 'labelledBy') {
    return { writable: { ok: false, reason: 'unsupported' } };
  }
  if (
    name === 'dismiss' ||
    name === 'focusTrap' ||
    name === 'focusRestore' ||
    name === 'anchor' ||
    name === 'anchorPlacement' ||
    name === 'anchorStrategy' ||
    name === 'anchorOffset'
  ) {
    return { writable: { ok: false, reason: 'unsupported' } };
  }
  return {};
}

/**
 * Derives the editable-slot catalog for a parsed file. `source` must be the
 * exact text the file was parsed from: guards are sliced from it and
 * `sourceVersion` hashes it (the catalog addresses THIS version and no
 * other).
 */
export function collectEditableSlots(file: ContractFileIR, source: string): EditableSlotCatalog {
  const slots: EditableSlotIR[] = [];
  file.components.forEach((component) => {
    collectSlotSites(component).forEach((site) => {
      const span = site.value.span;
      if (!span) {
        // No span (a compiler gap — the corpus gate catches it): not
        // addressable in source.
        return;
      }
      slots.push({
        ...site,
        span,
        guard: source.slice(span.offset, span.offset + span.len),
      });
    });
  });

  return {
    sourcePath: file.sourcePath,
    sourceVersion: hashSource(source),
    slots,
  };
}

/** Every slot site in one component — a pure function of the IR. */
export function collectSlotSites(component: ComponentIR): SlotSiteIR[] {
  const sites: SlotSiteIR[] = [];
  collectComponentSlots(component, sites);
  return sites;
}

function collectComponentSlots(component: ComponentIR, sites: SlotSiteIR[]): void {
  component.props.forEach((prop) => {
    pushValueSlot(sites, {
      component: component.name,
      section: 'props',
      slot: { kind: 'prop_default', name: prop.name },
      slotId: `${component.name}:prop:${prop.name}`,
      value: prop.defaultValue,
      type: prop.parsedType,
      hotPatch: 'reset',
    });
  });

  component.states.forEach((state) => {
    pushValueSlot(sites, {
      component: component.name,
      section: 'state',
      slot: { kind: 'state_initial', name: state.name },
      slotId: `${component.name}:state:${state.name}`,
      value: state.initial,
      type: state.parsedType,
      hotPatch: 'reset',
    });
  });

  const params = component.params;
  if (params) {
    params.forEach((param) => {
      pushValueSlot(sites, {
        component: component.name,
        section: 'params',
        slot: { kind: 'param_default', name: param.name },
        slotId: `${component.name}:param:${param.name}`,
        value: param.defaultValue,
        // A param's declared kind acts as its type for commit-plane
        // validation (LLP 0163 §5.3: kind feeds inference + validation).
        type: param.kind
          ? { raw: param.kind, ir: { kind: 'value-kind', name: param.kind }, span: param.span, diagnostics: [] }
          : undefined,
        hotPatch: 'reset',
      });
    });
  }

  // View-section slots ride the shared §4.7 structural-id derivation —
  // one path grammar for the catalog, the runtime registry, and the
  // hot-patch differ.
  walkStructuralPaths(component, (node, path) => {
    const nodeId = `${component.name}/${path}`;
    if (node.kind === 'element' || node.kind === 'component') {
      const isElement = node.kind === 'element';
      Object.keys(node.props).forEach((name) => {
        const semantic = isElement ? semanticAttrType(name, node.props[name]) : {};
        pushValueSlot(sites, {
          component: component.name,
          nodeId,
          section: 'view',
          slot: { kind: 'attr', name },
          slotId: `${nodeId}:attr:${name}`,
          value: node.props[name],
          type: semantic.type,
          // Built-in element attrs (style/layout/paint literals and token
          // refs) patch through host-ops; component-call props reset in v0
          // (child re-evaluation is a graduation candidate, §4.8).
          hotPatch: isElement ? 'host-prop' : 'reset',
          writable: semantic.writable,
        });
      });
      Object.keys(node.events).forEach((name) => {
        pushValueSlot(sites, {
          component: component.name,
          nodeId,
          section: 'view',
          slot: { kind: 'attr', name },
          slotId: `${nodeId}:attr:${name}`,
          value: node.events[name],
          hotPatch: 'reset',
          // Event attrs are behavior, not design values — locked.
          writable: { ok: false, reason: 'unsupported' },
        });
      });
    } else if (node.kind === 'text') {
      pushValueSlot(sites, {
        component: component.name,
        nodeId,
        section: 'view',
        slot: { kind: 'text' },
        slotId: `${nodeId}:text`,
        value: node.expr,
        hotPatch: 'text',
      });
    }
  });
}

interface ValueSlotInput {
  component: string;
  nodeId?: string;
  section: EditableSlotIR['section'];
  slot: SlotRef;
  slotId: string;
  value: Expr | undefined;
  type?: ParsedType;
  hotPatch: SlotHotPatchPolicy;
  /** Forced writability (e.g. event attrs are never design-editable). */
  writable?: SlotWritability;
}

function pushValueSlot(sites: SlotSiteIR[], input: ValueSlotInput): void {
  const value = input.value;
  if (!value) {
    // No value (e.g. a prop without a default): nothing to address.
    return;
  }
  const classification = classifyValue(value);
  const writable = input.writable ?? classification.writable;
  sites.push({
    slotId: input.slotId,
    component: input.component,
    nodeId: input.nodeId,
    section: input.section,
    slot: input.slot,
    value,
    valueKind: classification.valueKind,
    type: input.type,
    writable,
    hotPatch: writable.ok ? input.hotPatch : 'reset',
  });
}
