/**
 * Color Parsing
 *
 * This module provides utilities for parsing CSS color strings
 * into RGBA values for the protocol.
 *
 * Supported formats:
 * - Hex: #RGB, #RRGGBB, #RRGGBBAA
 * - RGB: rgb(r, g, b), rgba(r, g, b, a)
 * - Named colors: white, black, red, green, blue, etc.
 *
 * Relocated from `@exact/renderer` per LLP 0157 F0 so framework-neutral
 * packages (`@exact/facet-core`) can share one color implementation. The
 * renderer re-exports this module for back-compat.
 */

/**
 * RGBA color representation for protocol serialization.
 * All values are 0-255 integers.
 */
export interface RGBAColor {
  readonly r: number;
  readonly g: number;
  readonly b: number;
  readonly a: number;
}

/**
 * Common named colors.
 * Expanded set to match CSS Level 1 + commonly used colors.
 */
const namedColors: Record<string, RGBAColor> = {
  // CSS Level 1 colors
  black: { r: 0, g: 0, b: 0, a: 255 },
  silver: { r: 192, g: 192, b: 192, a: 255 },
  gray: { r: 128, g: 128, b: 128, a: 255 },
  grey: { r: 128, g: 128, b: 128, a: 255 },
  white: { r: 255, g: 255, b: 255, a: 255 },
  maroon: { r: 128, g: 0, b: 0, a: 255 },
  red: { r: 255, g: 0, b: 0, a: 255 },
  purple: { r: 128, g: 0, b: 128, a: 255 },
  fuchsia: { r: 255, g: 0, b: 255, a: 255 },
  green: { r: 0, g: 128, b: 0, a: 255 },
  lime: { r: 0, g: 255, b: 0, a: 255 },
  olive: { r: 128, g: 128, b: 0, a: 255 },
  yellow: { r: 255, g: 255, b: 0, a: 255 },
  navy: { r: 0, g: 0, b: 128, a: 255 },
  blue: { r: 0, g: 0, b: 255, a: 255 },
  teal: { r: 0, g: 128, b: 128, a: 255 },
  aqua: { r: 0, g: 255, b: 255, a: 255 },
  cyan: { r: 0, g: 255, b: 255, a: 255 },

  // Additional common colors
  orange: { r: 255, g: 165, b: 0, a: 255 },
  pink: { r: 255, g: 192, b: 203, a: 255 },
  brown: { r: 165, g: 42, b: 42, a: 255 },
  coral: { r: 255, g: 127, b: 80, a: 255 },
  crimson: { r: 220, g: 20, b: 60, a: 255 },
  gold: { r: 255, g: 215, b: 0, a: 255 },
  indigo: { r: 75, g: 0, b: 130, a: 255 },
  violet: { r: 238, g: 130, b: 238, a: 255 },

  // Special
  transparent: { r: 0, g: 0, b: 0, a: 0 },
};

/**
 * Parse a hex digit (0-9, a-f, A-F) to a number.
 */
function parseHexDigit(char: string): number {
  const code = char.charCodeAt(0);
  if (code >= 48 && code <= 57) return code - 48; // 0-9
  if (code >= 65 && code <= 70) return code - 55; // A-F
  if (code >= 97 && code <= 102) return code - 87; // a-f
  return -1;
}

/**
 * Parse two hex digits to a byte (0-255).
 */
function parseHexByte(s: string, offset: number): number {
  const high = parseHexDigit(s[offset]);
  const low = parseHexDigit(s[offset + 1]);
  if (high < 0 || low < 0) return -1;
  return (high << 4) | low;
}

/**
 * Parse a 3-digit hex color (#RGB).
 */
function parseHex3(hex: string): RGBAColor | null {
  const r = parseHexDigit(hex[0]);
  const g = parseHexDigit(hex[1]);
  const b = parseHexDigit(hex[2]);
  if (r < 0 || g < 0 || b < 0) return null;
  return {
    r: (r << 4) | r,
    g: (g << 4) | g,
    b: (b << 4) | b,
    a: 255,
  };
}

/**
 * Parse a 6-digit hex color (#RRGGBB).
 */
function parseHex6(hex: string): RGBAColor | null {
  const r = parseHexByte(hex, 0);
  const g = parseHexByte(hex, 2);
  const b = parseHexByte(hex, 4);
  if (r < 0 || g < 0 || b < 0) return null;
  return { r, g, b, a: 255 };
}

/**
 * Parse an 8-digit hex color (#RRGGBBAA).
 */
function parseHex8(hex: string): RGBAColor | null {
  const r = parseHexByte(hex, 0);
  const g = parseHexByte(hex, 2);
  const b = parseHexByte(hex, 4);
  const a = parseHexByte(hex, 6);
  if (r < 0 || g < 0 || b < 0 || a < 0) return null;
  return { r, g, b, a };
}

/**
 * Parse a 4-digit hex color (#RGBA).
 */
function parseHex4(hex: string): RGBAColor | null {
  const r = parseHexDigit(hex[0]);
  const g = parseHexDigit(hex[1]);
  const b = parseHexDigit(hex[2]);
  const a = parseHexDigit(hex[3]);
  if (r < 0 || g < 0 || b < 0 || a < 0) return null;
  return {
    r: (r << 4) | r,
    g: (g << 4) | g,
    b: (b << 4) | b,
    a: (a << 4) | a,
  };
}

/**
 * Parse a hex color string (#RGB, #RGBA, #RRGGBB, or #RRGGBBAA).
 */
function parseHexColor(color: string): RGBAColor | null {
  if (!color.startsWith('#')) return null;
  const hex = color.slice(1);

  switch (hex.length) {
    case 3:
      return parseHex3(hex);
    case 4:
      return parseHex4(hex);
    case 6:
      return parseHex6(hex);
    case 8:
      return parseHex8(hex);
    default:
      return null;
  }
}

/**
 * Regular expression for rgb/rgba colors.
 * Matches: rgb(r, g, b) and rgba(r, g, b, a)
 */
const rgbRegex = /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+)\s*)?\)$/;

/**
 * Parse an rgb() or rgba() color string.
 */
function parseRgbColor(color: string): RGBAColor | null {
  const match = color.match(rgbRegex);
  if (!match) return null;

  const r = parseInt(match[1], 10);
  const g = parseInt(match[2], 10);
  const b = parseInt(match[3], 10);

  // Validate RGB values are in range
  if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
    return null;
  }

  let a = 255;
  if (match[4] !== undefined) {
    const alphaFloat = parseFloat(match[4]);
    if (isNaN(alphaFloat) || alphaFloat < 0 || alphaFloat > 1) {
      return null;
    }
    a = Math.round(alphaFloat * 255);
  }

  return { r, g, b, a };
}

/**
 * Convert HSL values to RGB.
 */
function hslToRgb(h: number, s: number, l: number): [number, number, number] {
  h = ((h % 360) + 360) % 360;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs((h / 60) % 2 - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; }
  else if (h < 120) { r = x; g = c; }
  else if (h < 180) { g = c; b = x; }
  else if (h < 240) { g = x; b = c; }
  else if (h < 300) { r = x; b = c; }
  else { r = c; b = x; }
  return [
    Math.round((r + m) * 255),
    Math.round((g + m) * 255),
    Math.round((b + m) * 255),
  ];
}

const hslRegex = /^hsla?\(\s*(-?[\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%\s*(?:,\s*([\d.]+)\s*)?\)$/;

/**
 * Parse an hsl() or hsla() color string.
 */
function parseHslColor(color: string): RGBAColor | null {
  const match = color.match(hslRegex);
  if (!match) return null;
  const h = parseFloat(match[1]);
  const s = parseFloat(match[2]) / 100;
  const l = parseFloat(match[3]) / 100;
  if (isNaN(h) || isNaN(s) || isNaN(l) || s < 0 || s > 1 || l < 0 || l > 1) return null;
  const [r, g, b] = hslToRgb(h, s, l);
  let a = 255;
  if (match[4] !== undefined) {
    const alphaFloat = parseFloat(match[4]);
    if (isNaN(alphaFloat) || alphaFloat < 0 || alphaFloat > 1) return null;
    a = Math.round(alphaFloat * 255);
  }
  return { r, g, b, a };
}

/**
 * Parse a named color.
 */
function parseNamedColor(color: string): RGBAColor | null {
  return namedColors[color.toLowerCase()] ?? null;
}

/**
 * Parse a color string into an RGBA color object.
 *
 * Supported formats:
 * - Hex: #RGB, #RGBA, #RRGGBB, #RRGGBBAA
 * - RGB: rgb(r, g, b), rgba(r, g, b, a)
 * - HSL: hsl(h, s%, l%), hsla(h, s%, l%, a)
 * - Named: white, black, red, transparent, etc.
 *
 * @param color - The color string to parse
 * @returns The parsed RGBA color, or null if invalid
 */
export function parseColor(color: string | undefined | null): RGBAColor | null {
  if (!color) return null;

  // Trim whitespace
  color = color.trim();
  if (!color) return null;

  // Try hex first (most common)
  if (color.startsWith('#')) {
    return parseHexColor(color);
  }

  // Try rgb/rgba
  if (color.startsWith('rgb')) {
    return parseRgbColor(color);
  }

  // Try hsl/hsla
  if (color.startsWith('hsl')) {
    return parseHslColor(color);
  }

  // Try named color
  return parseNamedColor(color);
}

/**
 * Check if a string is a valid color.
 *
 * @param color - The string to check
 */
export function isValidColor(color: string): boolean {
  return parseColor(color) !== null;
}

/**
 * Convert an RGBA color to a hex string.
 *
 * @param color - The RGBA color
 * @param includeAlpha - Whether to include the alpha channel
 */
export function colorToHex(color: RGBAColor, includeAlpha: boolean = false): string {
  const r = color.r.toString(16).padStart(2, '0');
  const g = color.g.toString(16).padStart(2, '0');
  const b = color.b.toString(16).padStart(2, '0');

  if (includeAlpha && color.a !== 255) {
    const a = color.a.toString(16).padStart(2, '0');
    return `#${r}${g}${b}${a}`;
  }

  return `#${r}${g}${b}`;
}

/**
 * Convert an RGBA color to an rgba() string.
 *
 * @param color - The RGBA color
 */
export function colorToRgba(color: RGBAColor): string {
  if (color.a === 255) {
    return `rgb(${color.r}, ${color.g}, ${color.b})`;
  }
  return `rgba(${color.r}, ${color.g}, ${color.b}, ${(color.a / 255).toFixed(2)})`;
}
