// @system @ref LLP 0185 S1 — Contract expression IR compiled to cached closures.

import type { Expr } from '../compiler/ir.js';
import { isExprSpread } from '../compiler/ir.js';
import { getContractTokenResolver, readTokenPathFrom, warnUnresolvedToken } from './tokens.js';
import {
  Scope,
  spreadIntoArray,
  spreadIntoObject,
  type Binding,
  type EvalOptions,
} from './interpreter.js';
import { createContractRelation } from './layout-intent.js';

export type CompiledExpr = (scope: Scope, options?: EvalOptions) => unknown;

let compiledExprCache = new WeakMap<Expr, CompiledExpr>();
const warnedIdents = new Set<string>();

export function compileExpr(expr: Expr): CompiledExpr {
  const cached = compiledExprCache.get(expr);
  if (cached) {
    return cached;
  }
  const compiled = compileExprUncached(expr);
  compiledExprCache.set(expr, compiled);
  return compiled;
}

export function evalCompiledExpr(expr: Expr, scope: Scope, options?: EvalOptions): unknown {
  return compileExpr(expr)(scope, options);
}

export function resetCompiledExprCacheForTests(): void {
  compiledExprCache = new WeakMap();
  warnedIdents.clear();
}

function compileExprUncached(expr: Expr): CompiledExpr {
  switch (expr.kind) {
    case 'string':
      return () => expr.value;
    case 'number':
      return () => expr.value;
    case 'boolean':
      return () => expr.value;
    case 'null':
      return () => null;
    case 'token':
      return (scope) => readToken(scope, expr.path);
    case 'relation': {
      const args = expr.args.map(compileExpr);
      const fallback = expr.fallback ? compileExpr(expr.fallback) : null;
      return (scope, options) =>
        createContractRelation(
          expr.op,
          args.map((arg) => arg(scope, options)),
          fallback ? fallback(scope, options) : undefined,
        );
    }
    case 'ident':
      return (scope, options) => readIdent(scope, expr.name, options);
    case 'member': {
      const object = compileExpr(expr.object);
      return (scope, options) => {
        const receiver = object(scope, options);
        if (receiver == null) {
          if (expr.optional) {
            return undefined;
          }
          throw new Error(`[contract] cannot read "${expr.property}" of ${receiver === null ? 'null' : 'undefined'}`);
        }
        const value = (receiver as Record<string, unknown>)[expr.property];
        return typeof value === 'function'
          ? (value as (...args: unknown[]) => unknown).bind(receiver)
          : value;
      };
    }
    case 'index': {
      const object = compileExpr(expr.object);
      const index = compileExpr(expr.index);
      return (scope, options) => {
        const receiver = object(scope, options);
        const key = index(scope, options);
        if (receiver == null) {
          throw new Error('[contract] cannot index into null/undefined');
        }
        return (receiver as Record<string | number, unknown>)[key as string | number];
      };
    }
    case 'call': {
      const callee = compileExpr(expr.callee);
      const args = expr.args.map(compileExpr);
      return (scope, options) => {
        const fn = callee(scope, options);
        if (typeof fn !== 'function') {
          throw new Error(`[contract] attempted to call a non-function (${describeCallee(expr.callee)})`);
        }
        return (fn as (...args: unknown[]) => unknown)(
          ...args.map((arg) => arg(scope, options)),
        );
      };
    }
    case 'unary': {
      const operand = compileExpr(expr.operand);
      return (scope, options) => {
        const value = operand(scope, options);
        return expr.op === '!' ? !value : -(value as number);
      };
    }
    case 'binary': {
      const left = compileExpr(expr.left);
      const right = compileExpr(expr.right);
      return (scope, options) => {
        if (expr.op === '&&') {
          return left(scope, options) && right(scope, options);
        }
        if (expr.op === '||') {
          return left(scope, options) || right(scope, options);
        }
        if (expr.op === '??') {
          return left(scope, options) ?? right(scope, options);
        }
        const l = left(scope, options) as never;
        const r = right(scope, options) as never;
        switch (expr.op) {
          case '+': return (l as number) + (r as number);
          case '-': return (l as number) - (r as number);
          case '*': return (l as number) * (r as number);
          case '/': return (l as number) / (r as number);
          case '%': return (l as number) % (r as number);
          case '==': return l === r;
          case '!=': return l !== r;
          case '<': return l < r;
          case '<=': return l <= r;
          case '>': return l > r;
          case '>=': return l >= r;
        }
        throw new Error('[contract] unknown binary operator');
      };
    }
    case 'ternary': {
      const test = compileExpr(expr.test);
      const consequent = compileExpr(expr.consequent);
      const alternate = compileExpr(expr.alternate);
      return (scope, options) =>
        test(scope, options) ? consequent(scope, options) : alternate(scope, options);
    }
    case 'template': {
      const parts = expr.parts.map((part) =>
        part.kind === 'text'
          ? ({ kind: 'text' as const, text: part.text })
          : ({ kind: 'expr' as const, expr: compileExpr(part.expr) }),
      );
      return (scope, options) => {
        let out = '';
        for (const part of parts) {
          if (part.kind === 'text') {
            out += part.text;
          } else {
            const value = part.expr(scope, options);
            out += value == null ? '' : String(value);
          }
        }
        return out;
      };
    }
    case 'array': {
      const items = expr.items.map((item) =>
        isExprSpread(item)
          ? { spread: true as const, value: compileExpr(item.value) }
          : { spread: false as const, value: compileExpr(item) },
      );
      return (scope, options) => {
        const out: unknown[] = [];
        for (const item of items) {
          if (item.spread) {
            spreadIntoArray(out, item.value(scope, options));
          } else {
            out.push(item.value(scope, options));
          }
        }
        return out;
      };
    }
    case 'object': {
      const entries = expr.entries.map((entry) =>
        isExprSpread(entry)
          ? { key: null, value: compileExpr(entry.value) }
          : { key: entry.key, value: compileExpr(entry.value) },
      );
      return (scope, options) => {
        const out: Record<string, unknown> = {};
        for (const entry of entries) {
          if (entry.key === null) {
            spreadIntoObject(out, entry.value(scope, options));
          } else {
            out[entry.key] = entry.value(scope, options);
          }
        }
        return out;
      };
    }
    case 'arrow': {
      const body = compileExpr(expr.body);
      return (scope, options) =>
        (...args: unknown[]) => {
          const arrowScope = scope.child();
          expr.params.forEach((param, index) => {
            arrowScope.defineLocal(param, args[index]);
          });
          return body(arrowScope, options);
        };
    }
  }
}

function readToken(scope: Scope, path: string): unknown {
  const themeBinding = scope.lookup('theme');
  if (themeBinding) {
    const themeValue = readBinding(themeBinding);
    if (themeValue !== null && typeof themeValue === 'object') {
      const resolved = readTokenPathFrom(themeValue, path);
      if (resolved !== undefined) {
        return resolved;
      }
    }
  }
  const resolver = getContractTokenResolver();
  if (resolver) {
    const resolved = resolver(path);
    if (resolved !== undefined) {
      return resolved;
    }
  }
  warnUnresolvedToken(path);
  return undefined;
}

function readIdent(scope: Scope, name: string, options: EvalOptions | undefined): unknown {
  const binding = scope.lookup(name);
  if (!binding) {
    if (options?.identFallbackToString) {
      if (!warnedIdents.has(name)) {
        warnedIdents.add(name);
        console.warn(
          `[contract] "${name}" is not in scope; treating it as the string "${name}" (quote it to silence this warning)`,
        );
      }
      return name;
    }
    throw new Error(`[contract] "${name}" is not defined`);
  }
  return readBinding(binding);
}

function readBinding(binding: Binding): unknown {
  switch (binding.kind) {
    case 'value':
    case 'local':
      return binding.value;
    case 'getter':
    case 'state':
      return binding.get();
  }
}

function describeCallee(expr: Expr): string {
  if (expr.kind === 'ident') return expr.name;
  if (expr.kind === 'member') return expr.property;
  return expr.kind;
}
