// @system @ref LLP 0003 — Shared binary protocol constants
// @system @ref LLP 0150 — Protocol ABI constants are generated, not hand-mirrored
/**
 * OpCode definitions matching the Rust kernel protocol.
 *
 * The constant tables (OpCode, NodeType, PropId, EventType, transition enums,
 * DimensionType, StyleMask, StyleMask128, header sizes, protocol
 * versions) are generated from `tests/protocol/protocol-inventory.json` by
 * `bun packages/exact-devtools/src/scripts/generate-protocol-tables.mjs` and
 * live in `./opcodes.generated.ts`. Do not add protocol constants here — add
 * them to the inventory and regenerate. CI enforces this via the
 * `protocol-parity-gate` check in exact-verify.json.
 *
 * Only hand-authored helper *behavior* (mask construction/combination) stays
 * in this file. Everything is plain `as const` objects and plain functions so
 * the package stays loadable through Node's strip-only TypeScript loader
 * during config-time evaluation.
 */

export * from './opcodes.generated.js';

import type { Mask64, Mask128 } from './opcodes.generated.js';

/**
 * Create a 128-bit mask from a bit position (0-127)
 * For bits 0-63, only loLow and loHigh are set.
 * For bits 64-127, only hiLow and hiHigh are set.
 */
export function mask128(bit: number): Mask128 {
  const maskedBit = (bit >>> 0) & 31;
  const toMaskWord = (b: number) => (1 << (b & 31)) >>> 0;

  if (bit < 32) {
    return { loLow: toMaskWord(maskedBit), loHigh: 0, hiLow: 0, hiHigh: 0 };
  } else if (bit < 64) {
    return { loLow: 0, loHigh: toMaskWord(maskedBit), hiLow: 0, hiHigh: 0 };
  } else if (bit < 96) {
    return { loLow: 0, loHigh: 0, hiLow: toMaskWord(maskedBit), hiHigh: 0 };
  } else {
    return { loLow: 0, loHigh: 0, hiLow: 0, hiHigh: toMaskWord(maskedBit) };
  }
}

/**
 * Combine multiple 64-bit masks with OR
 */
export function combineMasks(...masks: Mask64[]): Mask64 {
  let low = 0;
  let high = 0;
  for (const m of masks) {
    low = (low | m.low) >>> 0;
    high = (high | m.high) >>> 0;
  }
  return { low, high };
}

/**
 * Combine multiple 128-bit masks with OR
 */
export function combineMasks128(...masks: Mask128[]): Mask128 {
  let loLow = 0;
  let loHigh = 0;
  let hiLow = 0;
  let hiHigh = 0;
  for (const m of masks) {
    loLow = (loLow | m.loLow) >>> 0;
    loHigh = (loHigh | m.loHigh) >>> 0;
    hiLow = (hiLow | m.hiLow) >>> 0;
    hiHigh = (hiHigh | m.hiHigh) >>> 0;
  }
  return { loLow, loHigh, hiLow, hiHigh };
}

/**
 * Convert a Mask64 to Mask128 (sets high word to zero)
 */
export function mask64to128(m: Mask64): Mask128 {
  return { loLow: m.low, loHigh: m.high, hiLow: 0, hiHigh: 0 };
}

/**
 * Check if a 128-bit mask needs protocol version 2 (has any high bits set)
 */
export function maskNeedsV2(m: Mask128): boolean {
  return m.hiLow !== 0 || m.hiHigh !== 0;
}
