import type {
  FacetComponentInfo,
  FloatingPositionData,
  ThemeSnapshotData,
} from './types.js';

interface ExperienceRegistryState {
  theme: ThemeSnapshotData | null;
  themeOverride: Record<string, unknown> | null;
  facetComponents: Map<string, FacetComponentInfo>;
  floatingPositions: Map<string, FloatingPositionData>;
  themeOverrideListeners: Set<() => void>;
}

declare global {
  var __exactExperienceRegistryState: ExperienceRegistryState | undefined;
}

function getRegistryState(): ExperienceRegistryState {
  if (globalThis.__exactExperienceRegistryState) {
    return globalThis.__exactExperienceRegistryState;
  }

  const state: ExperienceRegistryState = {
    theme: null,
    themeOverride: null,
    facetComponents: new Map(),
    floatingPositions: new Map(),
    themeOverrideListeners: new Set(),
  };
  globalThis.__exactExperienceRegistryState = state;
  return state;
}

const registry = getRegistryState();

export function setThemeSnapshot(snapshot: ThemeSnapshotData): void {
  registry.theme = { ...snapshot, tokens: { ...snapshot.tokens } };
}

export function getThemeSnapshot(): ThemeSnapshotData | null {
  return registry.theme
    ? { ...registry.theme, tokens: { ...registry.theme.tokens } }
    : null;
}

export function setThemeOverride(override: Record<string, unknown> | null): void {
  registry.themeOverride = override ? { ...override } : null;
  for (const listener of registry.themeOverrideListeners) {
    listener();
  }
}

export function getThemeOverride(): Record<string, unknown> | null {
  return registry.themeOverride ? { ...registry.themeOverride } : null;
}

export function subscribeThemeOverride(listener: () => void): () => void {
  registry.themeOverrideListeners.add(listener);
  return () => {
    registry.themeOverrideListeners.delete(listener);
  };
}

export function registerFacetComponents(components: FacetComponentInfo[]): void {
  for (const component of components) {
    registry.facetComponents.set(component.name, {
      ...component,
      props: component.props?.map((entry) => ({ ...entry })),
      variants: component.variants?.map((entry) => ({
        ...entry,
        values: entry.values.slice(),
      })),
      dependencies: component.dependencies?.slice(),
      annotations: component.annotations ? { ...component.annotations } : undefined,
    });
  }
}

export function getFacetComponents(): FacetComponentInfo[] {
  return Array.from(registry.facetComponents.values()).sort((left, right) =>
    left.name.localeCompare(right.name),
  );
}

export function upsertFloatingPosition(position: FloatingPositionData): void {
  registry.floatingPositions.set(position.id, { ...position });
}

export function removeFloatingPosition(id: string): void {
  registry.floatingPositions.delete(id);
}

export function getFloatingPositions(): FloatingPositionData[] {
  return Array.from(registry.floatingPositions.values()).sort(
    (left, right) => left.updatedAt - right.updatedAt,
  );
}

export function findFloatingPositionByViewId(viewId: number): FloatingPositionData | null {
  for (const position of registry.floatingPositions.values()) {
    if (position.viewId === viewId) {
      return { ...position };
    }
  }
  return null;
}

export function _resetExperienceRegistryForTests(): void {
  registry.theme = null;
  registry.themeOverride = null;
  registry.facetComponents.clear();
  registry.floatingPositions.clear();
  registry.themeOverrideListeners.clear();
}
