// @system @ref LLP 0221 — Contract lexical vocabulary authority.
//
// These lists are intentionally small and syntax-facing: parser validation,
// language-service completions, structural-edit event handling, and generated
// editor grammars consume this module instead of carrying parallel token copies.

import {
  CONTRACT_SCHEMA_ATTRS,
  CONTRACT_SCHEMA_EVENT_ATTRS,
  CONTRACT_SCHEMA_VIEW_TAGS,
} from './builtin-schema.js';

const unique = <T extends string>(values: readonly T[]): readonly T[] =>
  Array.from(new Set(values));

export const CONTRACT_VIEW_TAGS = CONTRACT_SCHEMA_VIEW_TAGS;

export type ContractViewTag = (typeof CONTRACT_VIEW_TAGS)[number];
export const CONTRACT_VIEW_TAG_SET: ReadonlySet<string> = new Set(CONTRACT_VIEW_TAGS);

// `stale` is the LLP 0284 §2.2 connection-axis arm (matches when the binding
// is ready but its connection is 'stale' or 'disconnected', before `empty`);
// the spelling is provisional pending the LLP 0194 amendment / B-4 freeze.
export const CONTRACT_RESOURCE_SLOT_KINDS = ['loading', 'error', 'stale', 'empty', 'ready'] as const;
export type ContractResourceSlotKind = (typeof CONTRACT_RESOURCE_SLOT_KINDS)[number];
export const CONTRACT_RESOURCE_SLOT_KIND_SET: ReadonlySet<string> = new Set(CONTRACT_RESOURCE_SLOT_KINDS);

export const CONTRACT_EVENT_ATTRS = CONTRACT_SCHEMA_EVENT_ATTRS;

export type ContractEventAttr = (typeof CONTRACT_EVENT_ATTRS)[number];
export const CONTRACT_EVENT_ATTR_SET: ReadonlySet<string> = new Set(CONTRACT_EVENT_ATTRS);

// `behavior` declares a top-level behavior template (LLP 0280 §2.1); the
// spelling is provisional pending the B-4 notation freeze, exactly like the
// `ephemeral` binding below.
export const CONTRACT_TOP_LEVEL_KEYWORDS = ['use', 'component', 'behavior'] as const;

// `ephemeral` is the LLP 0284 §2.5 presence-map binding (distinct keyword per
// OQ1's lean); the spelling is provisional pending the B-4 notation freeze,
// exactly like the `stale` slot kind above.
export const CONTRACT_COMPONENT_BLOCK_KEYWORDS = [
  'props',
  'params',
  'design',
  'state',
  'derive',
  'resource',
  'query',
  'ephemeral',
  'mutation',
  'use',
  'action',
  'task',
  'snippet',
  'contract',
  'view',
] as const;

// Blocks legal inside a `behavior` template (LLP 0280 §2.1): no `view`
// (behaviors may not render), no `props`/`use` (inputs enter as reactive
// parameters), plus the required `expose` interface line. `expose` is
// provisional pending the B-4 notation freeze like `behavior` above.
export const CONTRACT_BEHAVIOR_BLOCK_KEYWORDS = [
  'state',
  'derive',
  'action',
  'task',
  'contract',
  'expose',
] as const;

export const CONTRACT_DECLARATION_KEYWORDS = unique([
  ...CONTRACT_TOP_LEVEL_KEYWORDS,
  ...CONTRACT_COMPONENT_BLOCK_KEYWORDS,
  ...CONTRACT_BEHAVIOR_BLOCK_KEYWORDS,
] as const);

/**
 * Names the runtime's builtin scope defines for every component and behavior
 * body (`runtime/instance.ts` builtinScope + the per-instance managed
 * helpers). The analyzer's closed-scope check for behavior template bodies
 * (LLP 0280 §2.1: params + own declarations + builtins only) reads this
 * list; `behavior-templates.test.ts` pins it against the live runtime scope
 * so the two cannot drift.
 */
export const CONTRACT_RUNTIME_BUILTIN_NAMES = [
  'Math',
  'JSON',
  'String',
  'Number',
  'Boolean',
  'console',
  'form',
  'now',
  'every',
  'after',
  // LLP 0281 §3.4 — the explicit channel→action crossing. The analyzer
  // confines it to edge pointer-event arguments; the runtime seals the
  // channel's current value. Provisional pending B-4 like `ephemeral`.
  'sample',
] as const;

