// @system @ref LLP 0087 — Contract v0 expression/statement interpreter.
//
// v0's deliberate execution strategy: the IR is the artifact and the
// runtime interprets it (no codegen), so the same ComponentIR that travels
// as the wire format also runs. Reads through scope bindings are tracked by
// the signal runtime automatically — each view binding evaluates inside its
// own effect, giving fine-grained updates for free.

import type { AssignTarget, Expr, Stmt } from '../compiler/ir.js';
import { isExprSpread } from '../compiler/ir.js';
import { decorateContractError } from './error-locus.js';
import {
  getContractTokenResolver,
  readTokenPathFrom,
  warnUnresolvedToken,
} from './tokens.js';
import { createContractRelation } from './layout-intent.js';

export type Binding =
  | { kind: 'value'; value: unknown }
  | { kind: 'local'; value: unknown }
  | { kind: 'getter'; get: () => unknown }
  | { kind: 'state'; get: () => unknown; set: (value: unknown) => void };

export class Scope {
  private readonly bindings = new Map<string, Binding>();

  constructor(readonly parent: Scope | null = null) {}

  define(name: string, binding: Binding): void {
    this.bindings.set(name, binding);
  }

  defineValue(name: string, value: unknown): void {
    this.define(name, { kind: 'value', value });
  }

  /** Assignable interpreter-created locals (let, params, loop vars). */
  defineLocal(name: string, value: unknown): void {
    this.define(name, { kind: 'local', value });
  }

  lookup(name: string): Binding | null {
    return this.bindings.get(name) ?? this.parent?.lookup(name) ?? null;
  }

  child(): Scope {
    return new Scope(this);
  }
}

export interface EvalOptions {
  /**
   * View-prop position: unresolved bare identifiers evaluate to their own
   * name as a string with a dev warning (web-like graceful degradation for
   * enum-ish semantic props like `emphasis=primary`).
   */
  identFallbackToString?: boolean;
}

const warnedIdents = new Set<string>();

export function evalExpr(expr: Expr, scope: Scope, options?: EvalOptions): unknown {
  switch (expr.kind) {
    case 'string':
      return expr.value;
    case 'number':
      return expr.value;
    case 'boolean':
      return expr.value;
    case 'null':
      return null;
    case 'token': {
      // LLP 0166 §4.4: scope-correct first — a `theme` capability binding in
      // the evaluating scope resolves the path reactively (its proxy reads
      // are signal-tracked); otherwise the registered resolver (the theme
      // store's default scope); otherwise dev-warn + unset.
      const themeBinding = scope.lookup('theme');
      if (themeBinding) {
        const themeValue = readBinding(themeBinding);
        if (themeValue !== null && typeof themeValue === 'object') {
          const resolved = readTokenPathFrom(themeValue, expr.path);
          if (resolved !== undefined) {
            return resolved;
          }
        }
      }
      const resolver = getContractTokenResolver();
      if (resolver) {
        const resolved = resolver(expr.path);
        if (resolved !== undefined) {
          return resolved;
        }
      }
      warnUnresolvedToken(expr.path);
      return undefined;
    }
    case 'relation':
      return createContractRelation(
        expr.op,
        expr.args.map((arg) => evalExpr(arg, scope, options)),
        expr.fallback ? evalExpr(expr.fallback, scope, options) : undefined,
      );
    case 'ident': {
      const binding = scope.lookup(expr.name);
      if (!binding) {
        if (options?.identFallbackToString) {
          if (!warnedIdents.has(expr.name)) {
            warnedIdents.add(expr.name);
            console.warn(
              `[contract] "${expr.name}" is not in scope; treating it as the string "${expr.name}" (quote it to silence this warning)`,
            );
          }
          return expr.name;
        }
        throw new Error(`[contract] "${expr.name}" is not defined`);
      }
      return readBinding(binding);
    }
    case 'member': {
      const object = evalExpr(expr.object, scope, options);
      if (object == null) {
        if (expr.optional) {
          return undefined;
        }
        throw new Error(`[contract] cannot read "${expr.property}" of ${object === null ? 'null' : 'undefined'}`);
      }
      const value = (object as Record<string, unknown>)[expr.property];
      return typeof value === 'function' ? (value as (...args: unknown[]) => unknown).bind(object) : value;
    }
    case 'index': {
      const object = evalExpr(expr.object, scope, options);
      const index = evalExpr(expr.index, scope, options);
      if (object == null) {
        throw new Error('[contract] cannot index into null/undefined');
      }
      return (object as Record<string | number, unknown>)[index as string | number];
    }
    case 'call': {
      const callee = evalExpr(expr.callee, scope, options);
      if (typeof callee !== 'function') {
        throw new Error(`[contract] attempted to call a non-function (${describeCallee(expr.callee)})`);
      }
      const args = expr.args.map((arg) => evalExpr(arg, scope, options));
      return (callee as (...args: unknown[]) => unknown)(...args);
    }
    case 'unary': {
      const operand = evalExpr(expr.operand, scope, options);
      return expr.op === '!' ? !operand : -(operand as number);
    }
    case 'binary': {
      if (expr.op === '&&') {
        return evalExpr(expr.left, scope, options) && evalExpr(expr.right, scope, options);
      }
      if (expr.op === '||') {
        return evalExpr(expr.left, scope, options) || evalExpr(expr.right, scope, options);
      }
      if (expr.op === '??') {
        const left = evalExpr(expr.left, scope, options);
        return left ?? evalExpr(expr.right, scope, options);
      }
      const left = evalExpr(expr.left, scope, options) as never;
      const right = evalExpr(expr.right, scope, options) as never;
      switch (expr.op) {
        case '+': return (left as number) + (right as number);
        case '-': return (left as number) - (right as number);
        case '*': return (left as number) * (right as number);
        case '/': return (left as number) / (right as number);
        case '%': return (left as number) % (right as number);
        case '==': return left === right;
        case '!=': return left !== right;
        case '<': return left < right;
        case '<=': return left <= right;
        case '>': return left > right;
        case '>=': return left >= right;
      }
      throw new Error(`[contract] unknown binary operator`);
    }
    case 'ternary':
      return evalExpr(expr.test, scope, options)
        ? evalExpr(expr.consequent, scope, options)
        : evalExpr(expr.alternate, scope, options);
    case 'template': {
      let out = '';
      for (const part of expr.parts) {
        if (part.kind === 'text') {
          out += part.text;
        } else {
          const value = evalExpr(part.expr, scope, options);
          out += value == null ? '' : String(value);
        }
      }
      return out;
    }
    case 'array': {
      const out: unknown[] = [];
      for (const item of expr.items) {
        if (isExprSpread(item)) {
          spreadIntoArray(out, evalExpr(item.value, scope, options));
        } else {
          out.push(evalExpr(item, scope, options));
        }
      }
      return out;
    }
    case 'object': {
      const out: Record<string, unknown> = {};
      for (const entry of expr.entries) {
        if (isExprSpread(entry)) {
          spreadIntoObject(out, evalExpr(entry.value, scope, options));
        } else {
          out[entry.key] = evalExpr(entry.value, scope, options);
        }
      }
      return out;
    }
    case 'arrow': {
      return (...args: unknown[]) => {
        const arrowScope = scope.child();
        expr.params.forEach((param, index) => {
          arrowScope.defineLocal(param, args[index]);
        });
        return evalExpr(expr.body, arrowScope, options);
      };
    }
  }
}

function describeCallee(expr: Expr): string {
  if (expr.kind === 'ident') return expr.name;
  if (expr.kind === 'member') return expr.property;
  return expr.kind;
}

/**
 * Spread helpers (LLP 0277 §4.2), shared with the compiled-expression path
 * so the dual-mode conformance is by construction, not by parallel code.
 * Semantics follow JS: array spread requires an iterable; object spread
 * copies own enumerable properties and ignores null/undefined.
 */
export function spreadIntoArray(out: unknown[], value: unknown): void {
  if (
    value == null ||
    typeof (value as { [Symbol.iterator]?: unknown })[Symbol.iterator] !== 'function'
  ) {
    throw new Error('[contract] array spread ("...") requires an iterable value');
  }
  for (const item of value as Iterable<unknown>) {
    out.push(item);
  }
}

export function spreadIntoObject(out: Record<string, unknown>, value: unknown): void {
  if (value == null) {
    return; // JS object-spread semantics: null/undefined spread to nothing.
  }
  Object.assign(out, value);
}

function readBinding(binding: Binding): unknown {
  switch (binding.kind) {
    case 'value':
    case 'local':
      return binding.value;
    case 'getter':
    case 'state':
      return binding.get();
  }
}

// ---------------------------------------------------------------------------
// Statements (action/task bodies)
// ---------------------------------------------------------------------------

class ReturnSignal {
  constructor(readonly value: unknown) {}
}

/**
 * Executes a statement list. Synchronous until the first `await`; from there
 * the continuation chains on the promise (each sync segment batches state
 * writes per LLP 0082 — the caller wraps segments in batch()).
 */
export function execStatements(
  statements: Stmt[],
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
): unknown | Promise<unknown> {
  try {
    return execFrom(statements, 0, scope, runSegment);
  } catch (signal) {
    if (signal instanceof ReturnSignal) {
      return signal.value;
    }
    throw signal;
  }
}

function execFrom(
  statements: Stmt[],
  start: number,
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
): unknown | Promise<unknown> {
  let i = start;

  while (i < statements.length) {
    const statement = statements[i];

    if (statement.kind === 'await-assign') {
      let promise: unknown;
      try {
        promise = runSegment(() => evalExpr(statement.value, scope));
      } catch (error) {
        decorateContractError(error, { span: statement.span });
        throw error;
      }
      return Promise.resolve(promise).then(
        (resolved) => {
          if (statement.target) {
            runSegment(() => {
              if (statement.isLet && statement.target!.kind === 'name') {
                scope.defineLocal(statement.target!.name, resolved);
              } else {
                assign(statement.target!, resolved, scope);
              }
            });
          }
          try {
            return execFrom(statements, i + 1, scope, runSegment);
          } catch (signal) {
            if (signal instanceof ReturnSignal) {
              return signal.value;
            }
            throw signal;
          }
        },
        (error) => {
          // ENG-22443: an awaited rejection carries the awaiting statement's
          // authored span (unless something deeper already decorated it).
          decorateContractError(error, { span: statement.span });
          throw error;
        },
      );
    }

    // One segment per synchronous run of statements (everything until the
    // next await), so a multi-statement action flushes and commits ONCE —
    // the LLP 0082 batching contract. Nested if/for execute inside this
    // same segment (their runSegment calls nest harmlessly).
    let escaped: Promise<unknown> | null = null;
    let escapedAt = i;
    runSegment(() => {
      for (let j = i; j < statements.length; j += 1) {
        const current = statements[j];
        if (current.kind === 'await-assign') {
          escapedAt = j;
          escaped = null;
          return;
        }
        let result: unknown;
        try {
          result = execOne(current, scope, runSegment);
        } catch (error) {
          // ENG-22443: statement spans are required IR, so every failing
          // action/task statement reports its authored line. ReturnSignal is
          // not an Error and passes through undecorated.
          decorateContractError(error, { span: current.span });
          throw error;
        }
        if (result instanceof Promise) {
          // A nested block (if/for) hit an await; the rest of this list
          // chains after it in a fresh segment.
          escaped = result;
          escapedAt = j;
          return;
        }
        escapedAt = j + 1;
      }
    });

    if (escaped) {
      const pending: Promise<unknown> = escaped;
      const resumeAt = escapedAt + 1;
      return pending.then(() => {
        try {
          return execFrom(statements, resumeAt, scope, runSegment);
        } catch (signal) {
          if (signal instanceof ReturnSignal) {
            return signal.value;
          }
          throw signal;
        }
      });
    }

    i = escapedAt;
  }
  return undefined;
}

function execOne(
  statement: Stmt,
  scope: Scope,
  runSegment: <T>(fn: () => T) => T,
): unknown | Promise<unknown> {
  switch (statement.kind) {
    case 'let':
      scope.defineLocal(statement.name, evalExpr(statement.value, scope));
      return undefined;
    case 'assign':
      assign(statement.target, evalExpr(statement.value, scope), scope);
      return undefined;
    case 'expr':
      return evalExpr(statement.expr, scope);
    case 'if': {
      const test = evalExpr(statement.test, scope);
      const branch = test ? statement.then : statement.else;
      if (!branch) {
        return undefined;
      }
      return execFrom(branch, 0, scope.child(), runSegment);
    }
    case 'for': {
      const iterable = evalExpr(statement.iterable, scope);
      if (!Array.isArray(iterable)) {
        throw new Error('[contract] for ... in expects an array');
      }
      // Sequential; if any iteration awaits, chain the remaining iterations.
      const runIteration = (index: number): unknown | Promise<unknown> => {
        if (index >= iterable.length) {
          return undefined;
        }
        const loopScope = scope.child();
        loopScope.defineLocal(statement.item, iterable[index]);
        const result = execFrom(statement.body, 0, loopScope, runSegment);
        if (result instanceof Promise) {
          return result.then(() => runIteration(index + 1));
        }
        return runIteration(index + 1);
      };
      return runIteration(0);
    }
    case 'return':
      throw new ReturnSignal(statement.value ? evalExpr(statement.value, scope) : undefined);
    case 'await-assign':
      throw new Error('[contract] internal: await handled by execFrom');
  }
}

function assign(target: AssignTarget, value: unknown, scope: Scope): void {
  switch (target.kind) {
    case 'name': {
      const binding = scope.lookup(target.name);
      if (!binding) {
        throw new Error(`[contract] cannot assign to undeclared "${target.name}"`);
      }
      if (binding.kind === 'state') {
        binding.set(value);
        return;
      }
      if (binding.kind === 'local') {
        binding.value = value;
        return;
      }
      throw new Error(
        `[contract] "${target.name}" is read-only (only state slots and local lets are assignable)`,
      );
    }
    case 'member': {
      const object = evalExpr(target.object, scope);
      if (object == null || typeof object !== 'object') {
        throw new Error('[contract] cannot assign to a property of a non-object');
      }
      (object as Record<string, unknown>)[target.property] = value;
      return;
    }
    case 'index': {
      const object = evalExpr(target.object, scope);
      const index = evalExpr(target.index, scope);
      if (object == null) {
        throw new Error('[contract] cannot assign into null/undefined');
      }
      (object as Record<string | number, unknown>)[index as string | number] = value;
      return;
    }
  }
}
