// @system @ref LLP 0082 — Contract v0 reactive core.
//
// Fine-grained signals with the 0082 scheduling contract: state writes mark
// bindings dirty, dirty bindings coalesce, a single microtask flush updates
// derived values and view subscribers, and one commit closes the batch
// (multiple synchronous writes -> one render/commit wave).

import { reportContractRuntimeError } from './error-locus.js';

export interface ReadonlySignal<T> {
  get(): T;
}

export interface Signal<T> extends ReadonlySignal<T> {
  set(value: T): void;
  peek(): T;
}

interface Computation {
  execute(force?: boolean): void;
  invalidate(): void;
  deps: Set<SignalCore<unknown>>;
  seenVersions: Map<SignalCore<unknown>, number>;
  readHeight: number;
  disposed: boolean;
}

interface SignalCore<T> {
  value: T;
  version: number;
  height: number;
  producer?: ComputedImpl<T>;
  observers: Set<Computation>;
}

let currentComputation: Computation | null = null;
let batchDepth = 0;
let nextVersion = 1;
let nextCreationOrder = 1;

type ComputationState = 'clean' | 'check' | 'dirty';

export interface ReactiveChurnSnapshot {
  wave: number;
  effectRuns: number;
  skippedEffects: number;
  computedRecomputes: number;
  cascadePasses: number;
  nodes?: ReactiveNodeChurnSnapshot[];
}

export interface ReactiveNodeChurnSnapshot {
  nodeId: string;
  kind: ReactiveNodeKind;
  recomputes: number;
  effectRuns: number;
  skippedEffects: number;
  writes: number;
}

export type ReactiveNodeKind = 'signal' | 'computed' | 'effect';

export type ReactiveNodeState = 'clean' | 'check' | 'dirty' | 'disposed';

export interface ReactiveNodeSnapshot {
  id: string;
  kind: ReactiveNodeKind;
  label: string;
  value?: unknown;
  version?: number;
  state?: ReactiveNodeState;
  height?: number;
  readHeight?: number;
  observerCount: number;
  depCount: number;
  disposed: boolean;
  churn: ReactiveNodeChurnSnapshot;
}

export interface ReactiveEdgeSnapshot {
  from: string;
  to: string;
}

export interface ReactiveGraphSnapshot {
  schemaVersion: 0;
  wave: number;
  nodes: ReactiveNodeSnapshot[];
  edges: ReactiveEdgeSnapshot[];
}

export type ReactiveCauseKind = 'write' | 'invalidate' | 'recompute' | 'effect';

export interface ReactiveCauseHop {
  kind: ReactiveCauseKind;
  wave: number;
  nodeId: string;
  from?: string;
  value?: unknown;
  previous?: unknown;
}

export interface ReactiveCauseTrace {
  nodeId: string;
  wave: number;
  hops: ReactiveCauseHop[];
}

const reactiveChurnState: ReactiveChurnSnapshot = {
  wave: 0,
  effectRuns: 0,
  skippedEffects: 0,
  computedRecomputes: 0,
  cascadePasses: 0,
};

interface ReactiveNodeMeta {
  id: string;
  kind: ReactiveNodeKind;
  label: string;
  createdOrder: number;
}

interface ReactiveNodeChurnMutable {
  recomputes: number;
  effectRuns: number;
  skippedEffects: number;
  writes: number;
}

const reactiveCores = new Set<SignalCore<unknown>>();
const reactiveEffects = new Set<EffectImpl>();
const reactiveCoreMeta = new WeakMap<SignalCore<unknown>, ReactiveNodeMeta>();
const reactiveEffectMeta = new WeakMap<EffectImpl, ReactiveNodeMeta>();
const reactiveNodeChurnByWave = new Map<string, Map<number, ReactiveNodeChurnMutable>>();
const reactiveCauseByNodeId = new Map<string, ReactiveCauseHop[]>();
let pendingComputationCause = new WeakMap<Computation, ReactiveCauseHop[]>();
let nextReactiveNodeOrder = 1;

// ---------------------------------------------------------------------------
// Introspection gate (LLP 0192). Recording cause traces + per-node churn is a
// dev-only diagnostic; the codex base recorded both on EVERY write (with a
// JSON deep-clone of each value) unconditionally, and never pruned the per-node
// churn map — an unbounded prod memory + hot-path regression. We pull the
// cursor effort's dev/prod gate idea (default off in production, explicit
// override) while keeping codex's public introspection API, and additionally
// bound the churn-wave retention so the map cannot grow without limit even when
// recording is on.
const MAX_RETAINED_CHURN_WAVES = 2048;
let forcedIntrospection: boolean | null = null;

function introspectionDevDefault(): boolean {
  const runtime = globalThis as typeof globalThis & {
    __DEV__?: boolean;
    process?: { env?: { NODE_ENV?: string } };
  };
  if (typeof runtime.__DEV__ === 'boolean') {
    return runtime.__DEV__;
  }
  return runtime.process?.env?.NODE_ENV !== 'production';
}

function introspectionEnabled(): boolean {
  return forcedIntrospection ?? introspectionDevDefault();
}

/**
 * Force reactive introspection recording on/off (LLP 0192). `null` restores the
 * dev-mode default. Disabling clears accumulated cause/churn state so a
 * production or perf-sensitive surface pays neither the per-write recording cost
 * nor retains the reactive graph in memory.
 */
export function setReactiveIntrospectionEnabled(enabled: boolean | null): void {
  forcedIntrospection = enabled;
  if (enabled === false) {
    reactiveNodeChurnByWave.clear();
    reactiveCauseByNodeId.clear();
  }
}

function currentReactiveWave(): number {
  return reactiveChurnState.wave + (flushing ? 0 : 1);
}

/**
 * LLP 0284 §2.6 — the wave identity currently-batching writes will settle in
 * (during a flush, the flushing wave itself). `MutationReceipt.
 * optimisticWaveId` derives from this at `mutate()` entry: provider mutate
 * calls run synchronously inside the action body, so this is the flush that
 * applies the action's optimistic writes.
 */
export function reactiveSettlingWave(): number {
  return currentReactiveWave();
}

function registerCore<T>(core: SignalCore<T>, kind: Exclude<ReactiveNodeKind, 'effect'>): void {
  if (reactiveCoreMeta.has(core as SignalCore<unknown>)) {
    return;
  }
  const order = nextReactiveNodeOrder++;
  const id = `${kind}:${order}`;
  reactiveCoreMeta.set(core as SignalCore<unknown>, {
    id,
    kind,
    label: id,
    createdOrder: order,
  });
  reactiveCores.add(core as SignalCore<unknown>);
}

function registerEffect(effect: EffectImpl): void {
  if (reactiveEffectMeta.has(effect)) {
    return;
  }
  const order = nextReactiveNodeOrder++;
  const id = `effect:${order}`;
  reactiveEffectMeta.set(effect, {
    id,
    kind: 'effect',
    label: id,
    createdOrder: order,
  });
  reactiveEffects.add(effect);
}

function clearReactiveNodeBookkeeping(meta: ReactiveNodeMeta | undefined): void {
  if (!meta) {
    return;
  }
  reactiveNodeChurnByWave.delete(meta.id);
  reactiveCauseByNodeId.delete(meta.id);
}

function unregisterCore(core: SignalCore<unknown>): void {
  const meta = reactiveCoreMeta.get(core);
  reactiveCores.delete(core);
  core.observers.clear();
  clearReactiveNodeBookkeeping(meta);
  reactiveCoreMeta.delete(core);
}

function unregisterEffect(effect: EffectImpl): void {
  const meta = reactiveEffectMeta.get(effect);
  reactiveEffects.delete(effect);
  pendingEffects.delete(effect);
  clearReactiveNodeBookkeeping(meta);
  reactiveEffectMeta.delete(effect);
}

function metaForCore(core: SignalCore<unknown>): ReactiveNodeMeta {
  const existing = reactiveCoreMeta.get(core);
  if (existing) {
    return existing;
  }
  registerCore(core, core.producer ? 'computed' : 'signal');
  return reactiveCoreMeta.get(core)!;
}

function metaForComputation(computation: Computation): ReactiveNodeMeta | undefined {
  if (computation instanceof ComputedImpl) {
    return metaForCore(computation.debugCore());
  }
  if (computation instanceof EffectImpl) {
    return reactiveEffectMeta.get(computation);
  }
  return undefined;
}

function emptyNodeChurn(): ReactiveNodeChurnMutable {
  return {
    recomputes: 0,
    effectRuns: 0,
    skippedEffects: 0,
    writes: 0,
  };
}

function nodeChurnForWave(nodeId: string, wave: number): ReactiveNodeChurnMutable {
  let byWave = reactiveNodeChurnByWave.get(nodeId);
  if (!byWave) {
    byWave = new Map();
    reactiveNodeChurnByWave.set(nodeId, byWave);
  }
  let churn = byWave.get(wave);
  if (!churn) {
    churn = emptyNodeChurn();
    byWave.set(wave, churn);
    // Bound per-node churn history: waves are recorded monotonically, so Map
    // insertion order is wave order — evict the oldest beyond the window so a
    // long-running session cannot accumulate one bucket per wave forever.
    if (byWave.size > MAX_RETAINED_CHURN_WAVES) {
      const overflow = byWave.size - MAX_RETAINED_CHURN_WAVES;
      let evicted = 0;
      for (const oldWave of byWave.keys()) {
        if (evicted >= overflow) {
          break;
        }
        byWave.delete(oldWave);
        evicted += 1;
      }
    }
  }
  return churn;
}

function recordNodeChurn(nodeId: string, wave: number, key: keyof ReactiveNodeChurnMutable): void {
  if (!introspectionEnabled()) {
    return;
  }
  nodeChurnForWave(nodeId, wave)[key] += 1;
}

function nodeChurnSince(
  nodeId: string,
  kind: ReactiveNodeKind,
  sinceWave = -1,
): ReactiveNodeChurnSnapshot {
  const out = emptyNodeChurn();
  for (const [wave, churn] of reactiveNodeChurnByWave.get(nodeId) ?? []) {
    if (wave <= sinceWave) {
      continue;
    }
    out.recomputes += churn.recomputes;
    out.effectRuns += churn.effectRuns;
    out.skippedEffects += churn.skippedEffects;
    out.writes += churn.writes;
  }
  return { nodeId, kind, ...out };
}

function safeReactiveValue(value: unknown): unknown {
  if (
    value == null ||
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return value;
  }
  if (typeof value === 'function') {
    return { kind: 'function' };
  }
  try {
    return JSON.parse(JSON.stringify(value)) as unknown;
  } catch {
    return { kind: typeof value };
  }
}

function recordCause(nodeId: string, hops: ReactiveCauseHop[]): void {
  if (!introspectionEnabled()) {
    return;
  }
  reactiveCauseByNodeId.set(nodeId, hops);
}

function causeForCore(core: SignalCore<unknown>): ReactiveCauseHop[] | undefined {
  return reactiveCauseByNodeId.get(metaForCore(core).id);
}

function causeFromDeps(deps: Iterable<SignalCore<unknown>>): ReactiveCauseHop[] | undefined {
  let latest: ReactiveCauseHop[] | undefined;
  for (const dep of deps) {
    const cause = causeForCore(dep);
    if (!cause || cause.length === 0) {
      continue;
    }
    const causeWave = cause[cause.length - 1]!.wave;
    const latestWave = latest?.[latest.length - 1]?.wave ?? -1;
    if (causeWave >= latestWave) {
      latest = cause;
    }
  }
  return latest;
}

function propagateInvalidation(source: SignalCore<unknown>, observer: Computation): void {
  const sourceMeta = metaForCore(source);
  const observerMeta = metaForComputation(observer);
  if (!observerMeta) {
    return;
  }
  const sourceCause = causeForCore(source) ?? [];
  const wave = currentReactiveWave();
  pendingComputationCause.set(observer, [
    ...sourceCause,
    {
      kind: 'invalidate',
      wave,
      nodeId: observerMeta.id,
      from: sourceMeta.id,
    },
  ]);
}

function recordComputedCause(computed: ComputedImpl<unknown>): ReactiveCauseHop[] {
  const core = computed.debugCore();
  const meta = metaForCore(core);
  const wave = currentReactiveWave();
  const upstream = pendingComputationCause.get(computed) ?? causeFromDeps(computed.deps) ?? [];
  const hops = [
    ...upstream,
    {
      kind: 'recompute' as const,
      wave,
      nodeId: meta.id,
    },
  ];
  recordCause(meta.id, hops);
  pendingComputationCause.delete(computed);
  return hops;
}

function recordEffectCause(effect: EffectImpl, force: boolean): void {
  const meta = reactiveEffectMeta.get(effect);
  if (!meta) {
    return;
  }
  const wave = currentReactiveWave();
  const upstream = force
    ? []
    : pendingComputationCause.get(effect) ?? causeFromDeps(effect.deps) ?? [];
  const hops = [
    ...upstream,
    {
      kind: 'effect' as const,
      wave,
      nodeId: meta.id,
    },
  ];
  recordCause(meta.id, hops);
  pendingComputationCause.delete(effect);
}

const pendingEffects = new Set<EffectImpl>();
const afterFlushCallbacks = new Set<() => void>();
let flushScheduled = false;

function scheduleFlush(): void {
  if (batchDepth > 0 || flushScheduled) {
    return;
  }
  flushScheduled = true;
  queueMicrotask(() => {
    flushScheduled = false;
    runPendingEffects();
  });
}

let flushing = false;

function runPendingEffects(): void {
  // Re-entrant calls (a batch() inside an executing effect, e.g. resource
  // settlement) defer to the outer drain loop, which picks up their newly
  // enqueued effects — preserving one commit per wave.
  if (flushing) {
    return;
  }
  // A stray microtask after a synchronous batch drain has nothing to do; in
  // particular it must not re-fire the afterFlush (commit) callbacks.
  if (pendingEffects.size === 0) {
    return;
  }
  flushing = true;
  const errors: unknown[] = [];
  try {
    // Effects can enqueue more effects (e.g. region remounts); drain fully,
    // then notify commit listeners exactly once.
    let guard = 0;
    reactiveChurnState.wave += 1;
    while (pendingEffects.size > 0) {
      if (guard++ > 10_000) {
        throw new Error('[contract] reactive flush did not settle (possible infinite update loop)');
      }
      reactiveChurnState.cascadePasses += 1;
      const batch = [...pendingEffects].sort((a, b) => {
        const height = a.readHeight - b.readHeight;
        return height !== 0 ? height : a.creationOrder - b.creationOrder;
      });
      pendingEffects.clear();
      for (const effect of batch) {
        if (!effect.disposed) {
          try {
            effect.execute();
          } catch (error) {
            errors.push(error);
          }
        }
      }
    }
  } finally {
    flushing = false;
  }
  for (const callback of [...afterFlushCallbacks]) {
    callback();
  }
  if (errors.length > 0) {
    // ENG-22443: effect errors are isolated per effect (the flush completed
    // and committed — surviving UI keeps its last-good state); report each
    // with its authored Contract locus (dev-only, deduped per Error) before
    // rethrowing the first so failures stay loud.
    for (const error of errors) {
      reportContractRuntimeError(error);
    }
    const first = errors[0];
    if (first instanceof Error) {
      throw first;
    }
    throw new Error(String(first));
  }
}

/** Registers a callback that runs once after each effect flush (commit point). */
export function onFlush(callback: () => void): () => void {
  afterFlushCallbacks.add(callback);
  return () => {
    afterFlushCallbacks.delete(callback);
  };
}

export function batch<T>(fn: () => T): T {
  batchDepth += 1;
  try {
    return fn();
  } finally {
    batchDepth -= 1;
    if (batchDepth === 0 && pendingEffects.size > 0) {
      // Synchronous flush at the end of the outermost batch keeps event ->
      // commit latency to one tick.
      runPendingEffects();
    }
  }
}

export function untrack<T>(fn: () => T): T {
  const previous = currentComputation;
  currentComputation = null;
  try {
    return fn();
  } finally {
    currentComputation = previous;
  }
}

function track(core: SignalCore<unknown>): void {
  if (currentComputation) {
    core.observers.add(currentComputation);
    currentComputation.deps.add(core);
    currentComputation.seenVersions.set(core, core.version);
    currentComputation.readHeight = Math.max(currentComputation.readHeight, core.height + 1);
  }
}

function notify(core: SignalCore<unknown>): void {
  for (const observer of [...core.observers]) {
    propagateInvalidation(core, observer);
    observer.invalidate();
  }
  scheduleFlush();
}

export function signal<T>(initial: T): Signal<T> {
  const core: SignalCore<T> = { value: initial, version: nextVersion++, height: 0, observers: new Set() };
  registerCore(core, 'signal');
  currentOwner?.register(() => unregisterCore(core as SignalCore<unknown>));
  return {
    get(): T {
      track(core as SignalCore<unknown>);
      return core.value;
    },
    peek(): T {
      return core.value;
    },
    set(value: T): void {
      if (Object.is(core.value, value)) {
        return;
      }
      const previous = core.value;
      core.value = value;
      core.version = nextVersion++;
      // Introspection recording (incl. the value deep-clone) is dev-only and
      // skipped wholesale in production — see setReactiveIntrospectionEnabled.
      if (introspectionEnabled()) {
        const meta = metaForCore(core as SignalCore<unknown>);
        const wave = currentReactiveWave();
        recordNodeChurn(meta.id, wave, 'writes');
        recordCause(meta.id, [
          {
            kind: 'write',
            wave,
            nodeId: meta.id,
            previous: safeReactiveValue(previous),
            value: safeReactiveValue(value),
          },
        ]);
      }
      notify(core as SignalCore<unknown>);
    },
  };
}

class ComputedImpl<T> implements Computation {
  deps = new Set<SignalCore<unknown>>();
  seenVersions = new Map<SignalCore<unknown>, number>();
  readHeight = 0;
  disposed = false;
  private state: ComputationState = 'dirty';
  private core: SignalCore<T>;

  constructor(private readonly fn: () => T) {
    this.core = {
      value: undefined as T,
      version: nextVersion++,
      height: 1,
      producer: this,
      observers: new Set(),
    };
    registerCore(this.core, 'computed');
  }

  debugCore(): SignalCore<unknown> {
    return this.core as SignalCore<unknown>;
  }

  debugState(): ComputationState {
    return this.disposed ? 'dirty' : this.state;
  }

  get(): T {
    if (this.state !== 'clean' && !this.disposed) {
      this.settle();
    }
    track(this.core as SignalCore<unknown>);
    return this.core.value;
  }

  settle(): void {
    if (this.disposed || this.state === 'clean') {
      return;
    }
    if (this.state === 'dirty' || this.depsChanged()) {
      this.recompute();
    } else {
      this.state = 'clean';
    }
  }

  private depsChanged(): boolean {
    for (const dep of this.deps) {
      settleCore(dep);
      if (dep.version !== this.seenVersions.get(dep)) {
        return true;
      }
    }
    return false;
  }

  private recompute(): void {
    const meta = metaForCore(this.core as SignalCore<unknown>);
    const wave = currentReactiveWave();
    recordComputedCause(this);
    this.cleanupDeps();
    const previous = currentComputation;
    currentComputation = this;
    this.readHeight = 0;
    reactiveChurnState.computedRecomputes += 1;
    recordNodeChurn(meta.id, wave, 'recomputes');
    try {
      const next = this.fn();
      this.state = 'clean';
      if (!Object.is(next, this.core.value)) {
        this.core.value = next;
        this.core.version = nextVersion++;
      }
      this.core.height = this.readHeight;
    } finally {
      currentComputation = previous;
    }
  }

  execute(): void {
    // Computeds are pull-based; nothing runs at flush time.
  }

  invalidate(): void {
    if (this.state === 'dirty') {
      return;
    }
    this.state = 'dirty';
    const cause = pendingComputationCause.get(this);
    if (cause) {
      recordCause(metaForCore(this.core as SignalCore<unknown>).id, cause);
    }
    // Direct dependency changed; downstream observers need only check whether
    // this computed's value version changes after it settles.
    for (const observer of [...this.core.observers]) {
      propagateInvalidation(this.core as SignalCore<unknown>, observer);
      markCheck(observer);
    }
  }

  markCheck(): void {
    if (this.state !== 'clean') {
      return;
    }
    this.state = 'check';
    for (const observer of [...this.core.observers]) {
      propagateInvalidation(this.core as SignalCore<unknown>, observer);
      markCheck(observer);
    }
  }

  dispose(): void {
    this.disposed = true;
    this.cleanupDeps();
    unregisterCore(this.core as SignalCore<unknown>);
  }

  private cleanupDeps(): void {
    for (const dep of this.deps) {
      dep.observers.delete(this);
    }
    this.deps.clear();
    this.seenVersions.clear();
  }
}

export interface Computed<T> extends ReadonlySignal<T> {
  dispose(): void;
}

export function computed<T>(fn: () => T): Computed<T> {
  const impl = new ComputedImpl(fn);
  return {
    get: () => impl.get(),
    dispose: () => impl.dispose(),
  };
}

class EffectImpl implements Computation {
  deps = new Set<SignalCore<unknown>>();
  seenVersions = new Map<SignalCore<unknown>, number>();
  readHeight = 0;
  disposed = false;
  readonly creationOrder = nextCreationOrder++;

  constructor(private readonly fn: () => void) {
    registerEffect(this);
  }

  execute(force = false): void {
    if (this.disposed) {
      return;
    }
    if (!force && !this.depsChanged()) {
      reactiveChurnState.skippedEffects += 1;
      const meta = reactiveEffectMeta.get(this);
      if (meta) {
        recordNodeChurn(meta.id, currentReactiveWave(), 'skippedEffects');
      }
      return;
    }
    const meta = reactiveEffectMeta.get(this);
    const wave = currentReactiveWave();
    recordEffectCause(this, force);
    this.cleanupDeps();
    const previous = currentComputation;
    currentComputation = this;
    this.readHeight = 0;
    reactiveChurnState.effectRuns += 1;
    if (meta) {
      recordNodeChurn(meta.id, wave, 'effectRuns');
    }
    try {
      this.fn();
    } finally {
      currentComputation = previous;
    }
  }

  invalidate(): void {
    if (!this.disposed) {
      pendingEffects.add(this);
      scheduleFlush();
    }
  }

  dispose(): void {
    this.disposed = true;
    this.cleanupDeps();
    unregisterEffect(this);
  }

  private cleanupDeps(): void {
    for (const dep of this.deps) {
      dep.observers.delete(this);
    }
    this.deps.clear();
    this.seenVersions.clear();
  }

  private depsChanged(): boolean {
    for (const dep of this.deps) {
      settleCore(dep);
      if (dep.version !== this.seenVersions.get(dep)) {
        return true;
      }
    }
    return false;
  }
}

export interface EffectHandle {
  dispose(): void;
}

/** Runs immediately, re-runs on dependency change (coalesced per flush). */
export function effect(fn: () => void): EffectHandle {
  const impl = new EffectImpl(fn);
  impl.execute(true);
  return {
    dispose: () => impl.dispose(),
  };
}

function markCheck(computation: Computation): void {
  if (computation.disposed) {
    return;
  }
  if (computation instanceof ComputedImpl) {
    computation.markCheck();
    return;
  }
  computation.invalidate();
}

function settleCore(core: SignalCore<unknown>): void {
  core.producer?.settle();
}

function reactiveNodeSnapshotForCore(core: SignalCore<unknown>): ReactiveNodeSnapshot {
  const meta = metaForCore(core);
  const disposed = core.producer?.disposed ?? false;
  return {
    id: meta.id,
    kind: meta.kind,
    label: meta.label,
    value: safeReactiveValue(core.value),
    version: core.version,
    state: disposed ? 'disposed' : (core.producer?.debugState() ?? 'clean'),
    height: core.height,
    observerCount: core.observers.size,
    depCount: core.producer?.deps.size ?? 0,
    disposed,
    churn: nodeChurnSince(meta.id, meta.kind),
  };
}

function reactiveNodeSnapshotForEffect(effect: EffectImpl): ReactiveNodeSnapshot {
  const meta = reactiveEffectMeta.get(effect)!;
  return {
    id: meta.id,
    kind: 'effect',
    label: meta.label,
    state: effect.disposed ? 'disposed' : 'clean',
    readHeight: effect.readHeight,
    observerCount: 0,
    depCount: effect.deps.size,
    disposed: effect.disposed,
    churn: nodeChurnSince(meta.id, 'effect'),
  };
}

export function snapshotReactiveGraph(): ReactiveGraphSnapshot {
  const nodes = [
    ...[...reactiveCores]
      .filter((core) => !(core.producer?.disposed ?? false))
      .map(reactiveNodeSnapshotForCore),
    ...[...reactiveEffects]
      .filter((effect) => !effect.disposed)
      .map(reactiveNodeSnapshotForEffect),
  ].sort((a, b) => a.id.localeCompare(b.id));
  const edges: ReactiveEdgeSnapshot[] = [];
  for (const core of reactiveCores) {
    if (core.producer?.disposed) {
      continue;
    }
    const from = metaForCore(core).id;
    for (const observer of core.observers) {
      if (observer.disposed) {
        continue;
      }
      const to = metaForComputation(observer)?.id;
      if (to) {
        edges.push({ from, to });
      }
    }
  }
  return {
    schemaVersion: 0,
    wave: reactiveChurnState.wave,
    nodes,
    edges: edges.sort((a, b) => `${a.from}->${a.to}`.localeCompare(`${b.from}->${b.to}`)),
  };
}

export function whyDidNodeUpdate(nodeId: string): ReactiveCauseTrace | null {
  const hops = reactiveCauseByNodeId.get(nodeId);
  if (!hops || hops.length === 0) {
    return null;
  }
  return {
    nodeId,
    wave: hops[hops.length - 1]!.wave,
    hops: hops.map((hop) => ({ ...hop })),
  };
}

export function reactiveChurn(options: { sinceWave?: number } = {}): ReactiveChurnSnapshot {
  const knownNodes = [
    ...[...reactiveCores].map((core) => metaForCore(core)),
    ...[...reactiveEffects]
      .map((effect) => reactiveEffectMeta.get(effect))
      .filter((meta): meta is ReactiveNodeMeta => Boolean(meta)),
  ].sort((a, b) => a.createdOrder - b.createdOrder);
  return {
    ...reactiveChurnState,
    nodes: knownNodes.map((meta) =>
      nodeChurnSince(meta.id, meta.kind, options.sinceWave),
    ),
  };
}

export function _resetReactiveChurnForTests(): void {
  reactiveChurnState.wave = 0;
  reactiveChurnState.effectRuns = 0;
  reactiveChurnState.skippedEffects = 0;
  reactiveChurnState.computedRecomputes = 0;
  reactiveChurnState.cascadePasses = 0;
  reactiveNodeChurnByWave.clear();
  reactiveCauseByNodeId.clear();
  pendingComputationCause = new WeakMap<Computation, ReactiveCauseHop[]>();
  forcedIntrospection = null;
}

export function _resetReactiveIntrospectionForTests(): void {
  _resetReactiveChurnForTests();
  reactiveCores.clear();
  reactiveEffects.clear();
  nextReactiveNodeOrder = 1;
}

// ---------------------------------------------------------------------------
// Owners (disposal scopes; LLP 0155 A4's affine-disposal substrate)
// ---------------------------------------------------------------------------

export interface Owner {
  register(dispose: () => void): void;
  dispose(): void;
}

let currentOwner: Owner | null = null;

export function createOwner(): Owner {
  const disposables: Array<() => void> = [];
  let disposed = false;
  return {
    register(dispose: () => void): void {
      if (disposed) {
        dispose();
        return;
      }
      disposables.push(dispose);
    },
    dispose(): void {
      if (disposed) {
        return;
      }
      disposed = true;
      // Dispose in reverse creation order.
      for (let i = disposables.length - 1; i >= 0; i -= 1) {
        disposables[i]();
      }
      disposables.length = 0;
    },
  };
}

export function getOwner(): Owner | null {
  return currentOwner;
}

export function runWithOwner<T>(owner: Owner | null, fn: () => T): T {
  const previous = currentOwner;
  currentOwner = owner;
  try {
    return fn();
  } finally {
    currentOwner = previous;
  }
}

/** effect() that registers its disposal with the current owner. */
export function ownedEffect(fn: () => void): EffectHandle {
  const handle = effect(fn);
  currentOwner?.register(() => handle.dispose());
  return handle;
}

export function ownedComputed<T>(fn: () => T): Computed<T> {
  const handle = computed(fn);
  currentOwner?.register(() => handle.dispose());
  return handle;
}
