// @system @ref LLP 0230 — Local-capable protocol/event tap.
import {
  BUFFER_HEADER_SIZE,
  BUFFER_HEADER_V3_SIZE,
  EventType,
  NodeType,
  OpCode,
  OP_HEADER_SIZE,
  PropId,
  PROTOCOL_VERSION_3,
} from "../protocol/opcodes.js";

export type ProtocolTapDirection = "outbound" | "inbound";

export interface ProtocolTapRecord {
  seq: number;
  direction: ProtocolTapDirection;
  atMs: number;
  rootId?: number;
  viewId: number | null;
  opcode?: string;
  opcodeHex?: string;
  eventType?: string;
  eventTypeId?: number;
  handlerId?: number;
  summary?: Record<string, unknown>;
  payloadSummary?: Record<string, unknown>;
  frameSeq?: number;
  byteLen?: number;
  mappingMissing?: boolean;
}

export interface ProtocolTapQuery {
  rootId?: number;
  viewId?: number;
  direction?: ProtocolTapDirection | "both";
  sinceSeq?: number;
  limit?: number;
  includePayloads?: "none" | "summary";
}

export interface ProtocolTapQueryResult {
  rootId?: number;
  viewId?: number;
  highWaterSeq: number;
  ops: ProtocolTapRecord[];
  truncated: boolean;
}

interface HandlerBinding {
  rootId?: number;
  viewId: number;
  eventTypeId: number;
  eventType: string;
}

const MAX_RECORDS = 500;
let nextSeq = 1;
const records: ProtocolTapRecord[] = [];
const handlerBindings = new Map<number, HandlerBinding>();

const opNames = reverseLookup(OpCode);
const nodeTypeNames = reverseLookup(NodeType);
const propNames = reverseLookup(PropId);
const eventTypeNames = reverseLookup(EventType);

function reverseLookup(table: Record<string, number>): Map<number, string> {
  const result = new Map<number, string>();
  for (const [name, value] of Object.entries(table)) {
    result.set(value, name);
  }
  return result;
}

function pushRecord(record: Omit<ProtocolTapRecord, "seq" | "atMs">): void {
  records.push({
    seq: nextSeq++,
    atMs: Date.now(),
    ...record,
  });
  while (records.length > MAX_RECORDS) {
    records.shift();
  }
}

function hexByte(value: number): string {
  return `0x${value.toString(16).padStart(2, "0").toUpperCase()}`;
}

function stringSummary(value: string): Record<string, unknown> {
  return {
    valueKind: "string",
    redacted: true,
    utf16Length: value.length,
  };
}

function summarizeUnknown(value: unknown): Record<string, unknown> {
  if (typeof value === "string") {
    return stringSummary(value);
  }
  if (typeof value === "number") {
    return { valueKind: "number" };
  }
  if (typeof value === "boolean") {
    return { valueKind: "boolean" };
  }
  if (value === null) {
    return { valueKind: "null" };
  }
  if (Array.isArray(value)) {
    return { valueKind: "array", length: value.length };
  }
  if (typeof value === "object") {
    return {
      valueKind: "object",
      keys: Object.keys(value as Record<string, unknown>).slice(0, 8),
    };
  }
  return { valueKind: typeof value };
}

function summarizeInboundPayload(payload: unknown): Record<string, unknown> {
  if (!payload || typeof payload !== "object") {
    return summarizeUnknown(payload);
  }
  const object = payload as Record<string, unknown>;
  const nativeEvent =
    object.nativeEvent && typeof object.nativeEvent === "object"
      ? (object.nativeEvent as Record<string, unknown>)
      : {};
  const summary: Record<string, unknown> = {
    valueKind: "object",
    keys: Object.keys(object).slice(0, 8),
  };
  const candidate =
    object.value ??
    object.text ??
    nativeEvent.value ??
    nativeEvent.text;
  if (candidate !== undefined) {
    summary.valueSummary = summarizeUnknown(candidate);
  }
  const textRevision =
    nativeEvent.textRevision ?? nativeEvent.revision ?? object.textRevision ?? object.revision;
  if (
    (typeof textRevision === "number" && Number.isFinite(textRevision)) ||
    typeof textRevision === "string"
  ) {
    summary.textRevision = textRevision;
  }
  const classification =
    nativeEvent.classification ??
    nativeEvent.textClassification ??
    object.classification ??
    object.textClassification;
  if (typeof classification === "string") {
    summary.textClassification = classification;
  }
  const textChanged = nativeEvent.textChanged ?? object.textChanged;
  if (typeof textChanged === "boolean") {
    summary.textChanged = textChanged;
  }
  const isComposing =
    nativeEvent.isComposing ?? nativeEvent.composing ?? object.isComposing ?? object.composing;
  if (typeof isComposing === "boolean") {
    summary.isComposing = isComposing;
  }
  const selection = nativeEvent.selection ?? object.selection;
  if (selection && typeof selection === "object") {
    const range = selection as Record<string, unknown>;
    if (typeof range.start === "number" && typeof range.end === "number") {
      summary.selection = { start: range.start, end: range.end };
    }
  }
  const compositionRange = nativeEvent.compositionRange ?? object.compositionRange;
  if (compositionRange && typeof compositionRange === "object") {
    const range = compositionRange as Record<string, unknown>;
    if (typeof range.start === "number" && typeof range.end === "number") {
      summary.compositionRange = { start: range.start, end: range.end };
    }
  }
  return summary;
}

function readProtocolHeader(data: Uint8Array): {
  frameSeq: number;
  opCount: number;
  rootId?: number;
  offset: number;
} | null {
  if (data.byteLength < BUFFER_HEADER_SIZE) {
    return null;
  }
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const protocolVersion = view.getUint16(6, true);
  const offset =
    protocolVersion >= PROTOCOL_VERSION_3
      ? BUFFER_HEADER_V3_SIZE
      : BUFFER_HEADER_SIZE;
  if (data.byteLength < offset) {
    return null;
  }
  return {
    frameSeq: view.getUint32(0, true),
    opCount: view.getUint16(4, true),
    rootId:
      protocolVersion >= PROTOCOL_VERSION_3 ? view.getUint32(8, true) : 0,
    offset,
  };
}

function decodeStringPayload(
  view: DataView,
  data: Uint8Array,
  payloadOffset: number,
  payloadLen: number,
): Record<string, unknown> {
  if (payloadLen < 4) {
    return { malformed: true, payloadLen };
  }
  const propId = view.getUint16(payloadOffset, true);
  const byteLength = view.getUint16(payloadOffset + 2, true);
  const available = Math.max(0, Math.min(byteLength, payloadLen - 4));
  let utf16Length: number | undefined;
  try {
    utf16Length = new TextDecoder()
      .decode(data.subarray(payloadOffset + 4, payloadOffset + 4 + available))
      .length;
  } catch {
    utf16Length = undefined;
  }
  return {
    propId: propNames.get(propId) ?? propId,
    valueKind: "string",
    redacted: true,
    byteLength,
    ...(utf16Length === undefined ? {} : { utf16Length }),
  };
}

function decodeSummary(
  opcode: number,
  view: DataView,
  data: Uint8Array,
  payloadOffset: number,
  payloadLen: number,
): Record<string, unknown> {
  if (opcode === OpCode.CreateView && payloadLen >= 1) {
    const nodeType = view.getUint8(payloadOffset);
    return { nodeType: nodeTypeNames.get(nodeType) ?? nodeType };
  }
  if (opcode === OpCode.SetProp) {
    return decodeStringPayload(view, data, payloadOffset, payloadLen);
  }
  if (opcode === OpCode.SetChildren && payloadLen >= 2) {
    return { childCount: view.getUint16(payloadOffset, true) };
  }
  if (opcode === OpCode.BindEvent && payloadLen >= 5) {
    const eventTypeId = view.getUint8(payloadOffset);
    return {
      eventType: eventTypeNames.get(eventTypeId) ?? eventTypeId,
      handlerId: view.getUint32(payloadOffset + 1, true),
    };
  }
  if (opcode === OpCode.UnbindEvent && payloadLen >= 1) {
    const eventTypeId = view.getUint8(payloadOffset);
    return { eventType: eventTypeNames.get(eventTypeId) ?? eventTypeId };
  }
  if (opcode === OpCode.ComputeLayout && payloadLen >= 8) {
    return {
      width: view.getFloat32(payloadOffset, true),
      height: view.getFloat32(payloadOffset + 4, true),
    };
  }
  return { payloadBytes: payloadLen };
}

export function recordProtocolFrame(data: Uint8Array): void {
  const header = readProtocolHeader(data);
  if (!header) {
    return;
  }
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  let offset = header.offset;
  for (let index = 0; index < header.opCount; index += 1) {
    if (offset + OP_HEADER_SIZE > data.byteLength) {
      return;
    }
    const opcode = view.getUint8(offset);
    const viewId = view.getUint32(offset + 1, true);
    const payloadLen = view.getUint16(offset + 5, true);
    const payloadOffset = offset + OP_HEADER_SIZE;
    if (payloadOffset + payloadLen > data.byteLength) {
      return;
    }
    const summary = decodeSummary(opcode, view, data, payloadOffset, payloadLen);
    const opcodeName = opNames.get(opcode);
    pushRecord({
      direction: "outbound",
      rootId: header.rootId,
      viewId,
      opcode: opcodeName ?? `Unknown(${opcode})`,
      opcodeHex: hexByte(opcode),
      summary,
      frameSeq: header.frameSeq,
      byteLen: OP_HEADER_SIZE + payloadLen,
    });

    if (opcode === OpCode.BindEvent && payloadLen >= 5) {
      const eventTypeId = view.getUint8(payloadOffset);
      const handlerId = view.getUint32(payloadOffset + 1, true);
      handlerBindings.set(handlerId, {
        rootId: header.rootId,
        viewId,
        eventTypeId,
        eventType: eventTypeNames.get(eventTypeId) ?? String(eventTypeId),
      });
    } else if (opcode === OpCode.UnbindEvent && payloadLen >= 1) {
      const eventTypeId = view.getUint8(payloadOffset);
      for (const [handlerId, binding] of handlerBindings) {
        if (binding.viewId === viewId && binding.eventTypeId === eventTypeId) {
          handlerBindings.delete(handlerId);
        }
      }
    }

    offset = payloadOffset + payloadLen;
  }
}

export function recordInboundProtocolEvent(
  handlerId: number,
  payload: unknown,
): void {
  const binding = handlerBindings.get(handlerId);
  pushRecord({
    direction: "inbound",
    rootId: binding?.rootId,
    viewId: binding?.viewId ?? null,
    eventType: binding?.eventType,
    eventTypeId: binding?.eventTypeId,
    handlerId,
    payloadSummary: summarizeInboundPayload(payload),
    mappingMissing: !binding,
  });
}

export function queryProtocolTap(query: ProtocolTapQuery = {}): ProtocolTapQueryResult {
  const limit = Math.max(0, Math.min(query.limit ?? 50, 500));
  const direction = query.direction ?? "both";
  const includePayloads = query.includePayloads ?? "summary";
  const filtered = records.filter((record) => {
    if (query.sinceSeq !== undefined && record.seq <= query.sinceSeq) {
      return false;
    }
    if (query.rootId !== undefined && record.rootId !== query.rootId) {
      return false;
    }
    if (query.viewId !== undefined && record.viewId !== query.viewId) {
      return false;
    }
    return direction === "both" || record.direction === direction;
  });
  const selected = filtered.slice(-limit).map((record) => {
    if (includePayloads === "summary") {
      return { ...record };
    }
    const { summary: _summary, payloadSummary: _payloadSummary, ...rest } = record;
    return rest;
  });
  return {
    rootId: query.rootId,
    viewId: query.viewId,
    highWaterSeq: nextSeq - 1,
    ops: selected,
    truncated: filtered.length > selected.length,
  };
}

export function resetProtocolTapForTests(): void {
  records.length = 0;
  handlerBindings.clear();
  nextSeq = 1;
}
