import type {
  DisplayInfo,
  KeyboardState,
  RootWindowMetricsSnapshot,
  SafeAreaInsets,
  SafeAreaRegionInsets,
  WindowPosition,
  WindowSize,
  WindowState,
} from './window-types.js';

export type Unsubscribe = () => void;
export type WindowRendererKind = 'react' | 'solid' | 'vue';

export interface WindowRuntimeSnapshot {
  readonly size: Readonly<WindowSize>;
  readonly position: Readonly<WindowPosition>;
  readonly state: WindowState;
  readonly isFocused: boolean;
  readonly isVisible: boolean;
  readonly display: DisplayInfo;
  readonly safeAreaInsets: Readonly<SafeAreaInsets>;
  readonly safeAreaRegions: Readonly<SafeAreaRegionInsets>;
  readonly keyboardState: Readonly<KeyboardState>;
  readonly devicePixelRatio: number;
}

export const DEFAULT_VIEWPORT_WIDTH = 393;
export const DEFAULT_VIEWPORT_HEIGHT = 852;
export const DEFAULT_SCALE = 1;
export const MAIN_WINDOW_ID = 'main';

export const snapshotListenersByWindow = new Map<string, Set<() => void>>();
export const viewportChangeListeners = new Set<
  (width?: number, height?: number) => void
>();
export const windowSnapshots = new Map<string, WindowRuntimeSnapshot>();
export const rootWindowIds = new Map<number, string>([[0, MAIN_WINDOW_ID]]);
export const rootViewportOverrides = new Map<number, Readonly<WindowSize>>();

let activeWindowRenderer: WindowRendererKind = 'react';

export function zeroInsets(): Readonly<SafeAreaInsets> {
  return Object.freeze({
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
  });
}

export function emptySafeAreaRegions(): Readonly<SafeAreaRegionInsets> {
  return Object.freeze({
    container: zeroInsets(),
    displayCutout: zeroInsets(),
    gestures: zeroInsets(),
  });
}

export function emptyKeyboardState(): Readonly<KeyboardState> {
  return Object.freeze({
    visible: false,
    occlusion: Object.freeze({
      x: 0,
      y: 0,
      width: 0,
      height: 0,
    }),
    progress: 0,
    animating: false,
    mode: 'docked',
    animationCurve: 0,
    animationDurationMs: 0,
    interactive: false,
    accessoryHeight: 0,
    source: 'software',
  });
}

export function freezeSize(size: WindowSize): Readonly<WindowSize> {
  return Object.freeze({
    width: size.width,
    height: size.height,
  });
}

export function freezePosition(
  position: WindowPosition,
): Readonly<WindowPosition> {
  return Object.freeze({
    x: position.x,
    y: position.y,
  });
}

export function freezeInsets(
  insets: SafeAreaInsets,
): Readonly<SafeAreaInsets> {
  return Object.freeze({
    top: insets.top,
    right: insets.right,
    bottom: insets.bottom,
    left: insets.left,
  });
}

export function freezeSafeAreaRegions(
  regions: SafeAreaRegionInsets,
): Readonly<SafeAreaRegionInsets> {
  return Object.freeze({
    container: freezeInsets(regions.container),
    displayCutout: freezeInsets(regions.displayCutout),
    gestures: freezeInsets(regions.gestures),
  });
}

export function freezeDisplay(display: DisplayInfo): DisplayInfo {
  return Object.freeze({
    id: display.id,
    size: freezeSize(display.size),
    workArea: Object.freeze({
      x: display.workArea.x,
      y: display.workArea.y,
      width: display.workArea.width,
      height: display.workArea.height,
    }),
    scaleFactor: display.scaleFactor,
  });
}

export function getWindowSnapshotFromStore(
  windowId: string,
): WindowRuntimeSnapshot {
  return windowSnapshots.get(windowId) ?? createDefaultSnapshot(windowId);
}

export function setWindowSnapshot(
  windowId: string,
  snapshot: WindowRuntimeSnapshot,
): void {
  windowSnapshots.set(windowId, snapshot);
}

export function deleteWindowSnapshot(windowId: string): void {
  windowSnapshots.delete(windowId);
}

export function setRootWindowId(
  rootId: number,
  windowId: string | null,
): void {
  if (windowId) {
    rootWindowIds.set(rootId, windowId);
    return;
  }

  rootWindowIds.delete(rootId);
}

export function getAssignedRootWindowId(rootId: number): string | undefined {
  return rootWindowIds.get(rootId);
}

export function setRootViewportOverride(
  rootId: number,
  size: WindowSize | null,
): void {
  if (size) {
    rootViewportOverrides.set(rootId, freezeSize(size));
    return;
  }

  rootViewportOverrides.delete(rootId);
}

export function notifySnapshotListeners(windowId: string): void {
  for (const listener of [...getSnapshotListeners(windowId)]) {
    listener();
  }
}

export function notifyViewportChangeListeners(
  width?: number,
  height?: number,
): void {
  for (const listener of [...viewportChangeListeners]) {
    listener(width, height);
  }
}

export function subscribeToWindowState(
  listener: () => void,
  windowId: string = MAIN_WINDOW_ID,
): Unsubscribe {
  const listeners = getSnapshotListeners(windowId);
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function subscribeToRootWindowState(
  rootId: number,
  listener: () => void,
): Unsubscribe {
  const windowId = getWindowIdForRoot(rootId);
  return subscribeToWindowState(listener, windowId);
}

export function getWindowViewportForRoot(rootId: number): Readonly<WindowSize> {
  const override = rootViewportOverrides.get(rootId);
  if (override) {
    return override;
  }

  return getWindowSnapshotFromStore(getWindowIdForRoot(rootId)).size;
}

export function getWindowIdForRoot(rootId: number): string {
  return rootWindowIds.get(rootId) ?? MAIN_WINDOW_ID;
}

export function getSafeAreaInsetsForRoot(
  rootId: number,
): Readonly<SafeAreaInsets> {
  return getWindowSnapshotFromStore(getWindowIdForRoot(rootId)).safeAreaInsets;
}

export function getKeyboardStateForRoot(
  rootId: number,
): Readonly<KeyboardState> {
  return getWindowSnapshotFromStore(getWindowIdForRoot(rootId)).keyboardState;
}

export function getRootWindowMetrics(
  rootId: number,
): RootWindowMetricsSnapshot {
  const windowId = getWindowIdForRoot(rootId);
  const snapshot = getWindowSnapshotFromStore(windowId);
  return {
    windowId,
    regions: snapshot.safeAreaRegions,
    keyboard: snapshot.keyboardState,
  };
}

export function listWindowMetricsSnapshots(): RootWindowMetricsSnapshot[] {
  return Array.from(windowSnapshots.entries())
    .map(([windowId, snapshot]) => ({
      windowId,
      regions: snapshot.safeAreaRegions,
      keyboard: snapshot.keyboardState,
    }))
    .sort((left, right) => left.windowId.localeCompare(right.windowId));
}

export function __setActiveWindowRenderer(
  renderer: WindowRendererKind,
): void {
  activeWindowRenderer = renderer;
}

export function getActiveWindowRenderer(): WindowRendererKind {
  return activeWindowRenderer;
}

export function addViewportChangeListener(
  listener: (width?: number, height?: number) => void,
): Unsubscribe {
  viewportChangeListeners.add(listener);
  return () => {
    viewportChangeListeners.delete(listener);
  };
}

export function resetWindowStateStoreForTests(): void {
  snapshotListenersByWindow.clear();
  viewportChangeListeners.clear();
  windowSnapshots.clear();
  rootWindowIds.clear();
  rootWindowIds.set(0, MAIN_WINDOW_ID);
  rootViewportOverrides.clear();
  activeWindowRenderer = 'react';
}

function getSnapshotListeners(windowId: string): Set<() => void> {
  let listeners = snapshotListenersByWindow.get(windowId);
  if (!listeners) {
    listeners = new Set();
    snapshotListenersByWindow.set(windowId, listeners);
  }
  return listeners;
}

function createDefaultSnapshot(windowId: string): WindowRuntimeSnapshot {
  const size = freezeSize({
    width: DEFAULT_VIEWPORT_WIDTH,
    height: DEFAULT_VIEWPORT_HEIGHT,
  });
  const display = freezeDisplay({
    id: windowId,
    size,
    workArea: {
      x: 0,
      y: 0,
      width: size.width,
      height: size.height,
    },
    scaleFactor: DEFAULT_SCALE,
  });

  return {
    size,
    position: freezePosition({ x: 0, y: 0 }),
    state: 'normal',
    isFocused: true,
    isVisible: true,
    display,
    safeAreaInsets: zeroInsets(),
    safeAreaRegions: emptySafeAreaRegions(),
    keyboardState: emptyKeyboardState(),
    devicePixelRatio: DEFAULT_SCALE,
  };
}
