// @system @ref LLP 0265 P0 — Contract-facing data authoring diagnostics.

import { normalizeQueryLiveness } from './data-provider.js';
import type { ContractDataManifest, DataProviderDiagnostic } from './data-provider.js';

export type ContractDataDoctorSeverity = 'error' | 'warning' | 'info';

export interface ContractDataDescriptorUse {
  name: string;
  kind: 'query' | 'mutation';
  spec?: string;
  source?: {
    file?: string;
    line?: number;
    column?: number;
  };
}

export interface ContractDataDoctorDiagnostic {
  code: string;
  severity: ContractDataDoctorSeverity;
  message: string;
  owner: 'contract' | 'provider' | 'vite' | 'schema' | 'handler' | 'generated';
  source?: ContractDataDescriptorUse['source'];
  queryName?: string;
  mutationName?: string;
  suggestedFix?: string;
}

export interface ContractDataDoctorInput {
  manifest: ContractDataManifest;
  descriptorUses?: ContractDataDescriptorUse[];
  providerDiagnostics?: DataProviderDiagnostic[];
  expectedInputsHash?: string;
}

export interface ContractDataDoctorReport {
  ok: boolean;
  provider: string;
  diagnostics: ContractDataDoctorDiagnostic[];
}

export function doctorContractDataProject(input: ContractDataDoctorInput): ContractDataDoctorReport {
  const diagnostics: ContractDataDoctorDiagnostic[] = [];
  const { manifest } = input;

  if (!manifest.inputsHash) {
    diagnostics.push({
      code: 'manifest_freshness_unknown',
      severity: 'warning',
      message: 'Contract data manifest has no inputsHash; freshness cannot be checked.',
      owner: 'generated',
      suggestedFix: 'Regenerate provider descriptors with manifest hashing enabled.',
    });
  } else if (input.expectedInputsHash && input.expectedInputsHash !== manifest.inputsHash) {
    diagnostics.push({
      code: 'manifest_hash_mismatch',
      severity: 'error',
      message: `Contract data manifest is stale: expected ${input.expectedInputsHash}, found ${manifest.inputsHash}.`,
      owner: 'generated',
      suggestedFix: 'Regenerate Snapback Contract descriptors before running the app.',
    });
  }

  for (const use of input.descriptorUses ?? []) {
    if (use.kind === 'query') {
      const descriptor = manifest.queries[use.name];
      if (!descriptor) {
        diagnostics.push({
          code: 'descriptor_missing',
          severity: 'error',
          message: `Query descriptor "${use.name}" is imported but missing from the Contract data manifest.`,
          owner: 'generated',
          source: use.source,
          queryName: use.name,
          suggestedFix: 'Regenerate Contract query descriptors or fix the import name.',
        });
        continue;
      }
      if (
        (descriptor.result.kind === 'list' && descriptor.result.row.shape === 'unknown') ||
        (descriptor.result.kind === 'single' && descriptor.result.value.shape === 'unknown') ||
        (descriptor.result.kind === 'scalar' && descriptor.result.value.shape === 'unknown')
      ) {
        diagnostics.push({
          code: 'row_shape_unknown',
          severity: 'warning',
          message: `Query "${use.name}" has an unknown result shape; Contract field checks are degraded.`,
          owner: 'provider',
          source: use.source,
          queryName: use.name,
          suggestedFix: 'Generate a table row or query-result shape for this descriptor.',
        });
      }
      // LLP 0284 §2.4: liveness facts resolve through the one normalization
      // helper (legacy `subscription` + v2 fields + global capabilities), and
      // old-vs-new contradictions surface as diagnostics.
      const liveness = normalizeQueryLiveness(descriptor, manifest.capabilities);
      for (const livenessDiagnostic of liveness.diagnostics) {
        diagnostics.push({
          code: livenessDiagnostic.code,
          severity: livenessDiagnostic.severity,
          message: livenessDiagnostic.message,
          owner: livenessDiagnostic.owner,
          source: use.source,
          queryName: use.name,
          suggestedFix: livenessDiagnostic.suggestedFix,
        });
      }
      if (!liveness.initialSnapshot && manifest.capabilities.initialSnapshot) {
        diagnostics.push({
          code: 'query_change_only',
          severity: 'info',
          message: `Query "${use.name}" is change-only; async ready/empty verification may need explicit priming.`,
          owner: 'provider',
          source: use.source,
          queryName: use.name,
        });
      }
      continue;
    }

    if (!manifest.mutations[use.name]) {
      diagnostics.push({
        code: 'descriptor_missing',
        severity: 'error',
        message: `Mutation descriptor "${use.name}" is imported but missing from the Contract data manifest.`,
        owner: 'generated',
        source: use.source,
        mutationName: use.name,
        suggestedFix: 'Regenerate Contract mutation descriptors or fix the import name.',
      });
    }
  }

  for (const providerDiagnostic of input.providerDiagnostics ?? manifest.diagnostics ?? []) {
    diagnostics.push({
      code: providerDiagnostic.code,
      severity: providerDiagnostic.severity,
      message: providerDiagnostic.message,
      owner: providerDiagnostic.owner,
      source: providerDiagnostic.source,
      queryName: providerDiagnostic.queryName,
      mutationName: providerDiagnostic.mutationName,
      suggestedFix: providerDiagnostic.suggestedFix,
    });
  }

  return {
    ok: diagnostics.every((diagnostic) => diagnostic.severity !== 'error'),
    provider: manifest.provider,
    diagnostics,
  };
}
