export const CUSTOM_FONT_FAMILY_ID_START = 1024;

export interface AssetRef {
  readonly __exactAsset: true;
  readonly fileName: string;
  readonly relativePath: string;
  readonly sourcePath?: string;
  readonly url: string;
}

export interface FontRegistryRecord {
  error: Error | null;
  id: number;
  loaded: boolean;
  loadPromise: Promise<void>;
  name: string;
  refCount: number;
  sourceKey: string;
}

const builtinFontFamilyIds = new Map<string, number>([
  ['system-ui', 1],
  ['ui-sans-serif', 1],
  ['sans-serif', 1],
  // CSS keywords for the platform UI font (WebKit/Blink). Browsers resolve
  // these to the system font, so a stack like `-apple-system, ...,
  // Arial, sans-serif` paints the system font. Without these aliases the
  // resolver skips the unrecognized keywords and lands on `arial` (a static
  // family that renders heavier weights as regular on native), so bold text
  // came out thin while the same stack was bold on web (ENG-22195).
  ['-apple-system', 1],
  ['blinkmacsystemfont', 1],
  ['ui-monospace', 2],
  ['monospace', 2],
  ['ui-serif', 3],
  ['serif', 3],
  ['ui-rounded', 1],
  ['helvetica neue', 4],
  ['arial', 5],
  ['georgia', 6],
  ['times new roman', 7],
  ['courier new', 8],
  ['menlo', 9],
]);

export const fontRecordsByFamily = new Map<string, FontRegistryRecord>();

let nextCustomFontFamilyId = CUSTOM_FONT_FAMILY_ID_START;

export function asset(path: string): AssetRef {
  const normalizedPath = String(path);
  const segments = normalizedPath.split('/');
  const fileName = segments[segments.length - 1] ?? normalizedPath;

  return {
    __exactAsset: true,
    url: normalizedPath,
    fileName,
    relativePath: normalizedPath,
  };
}

export function isAssetRef(value: unknown): value is AssetRef {
  return (
    value != null &&
    typeof value === 'object' &&
    (value as { __exactAsset?: unknown }).__exactAsset === true &&
    typeof (value as { url?: unknown }).url === 'string'
  );
}

export function reserveCustomFontFamilyId(): number {
  return nextCustomFontFamilyId++;
}

export function resolveFontFamilyId(
  value: string | readonly string[] | undefined,
): number | undefined {
  if (value == null) {
    return undefined;
  }

  for (const family of normalizeFontFamilyEntries(value)) {
    const key = normalizeFontFamilyKey(family);
    const customRecord = fontRecordsByFamily.get(key);
    if (customRecord?.loaded) {
      return customRecord.id;
    }

    const builtin = builtinFontFamilyIds.get(key);
    if (builtin !== undefined) {
      return builtin;
    }
  }

  return undefined;
}

export function normalizeFontFamilyKey(value: string): string {
  return sanitizeFontFamilyName(value).toLowerCase();
}

function normalizeFontFamilyEntries(
  value: string | readonly string[],
): string[] {
  if (Array.isArray(value)) {
    return value
      .map((entry) => sanitizeFontFamilyName(entry))
      .filter(Boolean);
  }

  return String(value)
    .split(',')
    .map((entry) => sanitizeFontFamilyName(entry))
    .filter(Boolean);
}

function sanitizeFontFamilyName(value: string): string {
  return value.trim().replace(/^['"]|['"]$/g, '');
}
