// @system @ref LLP 0166 §4.4 — runtime resolution of `$` token references.
//
// Token references name positions in the facet-core theme schema, never
// concrete themes. The runtime stays framework-neutral: a binding (e.g.
// @exact/facet-contract) registers the resolver that reads through the
// active theme store. Resolution order in the interpreter: a `theme`
// capability binding in the evaluating scope wins (scope-correct themes —
// LLP 0163 §4.4 isolated panel scopes ride this), then the registered
// resolver, then a dev warning with unset/inherit fallback — a missing
// token never crashes.

export type ContractTokenResolver = (path: string) => unknown;

let resolver: ContractTokenResolver | null = null;

/** Registered by the theme binding (one per runtime; last write wins).
    Pass null to unregister (tests). */
export function registerContractTokenResolver(fn: ContractTokenResolver | null): void {
  resolver = fn;
}

export function getContractTokenResolver(): ContractTokenResolver | null {
  return resolver;
}

const warnedTokenPaths = new Set<string>();

/** Dev-warn once per dangling path; resolution falls back to undefined. */
export function warnUnresolvedToken(path: string): void {
  if (warnedTokenPaths.has(path)) {
    return;
  }
  warnedTokenPaths.add(path);
  console.warn(
    `[contract] token reference $${path} did not resolve (no theme in scope and no token resolver registered, or the path is not in the schema); the property is left unset`,
  );
}

/** Walks a dot path through a theme-like object; undefined when absent. */
export function readTokenPathFrom(target: unknown, path: string): unknown {
  let cursor: unknown = target;
  const segments = path.split('.');
  for (let i = 0; i < segments.length; i += 1) {
    if (cursor === null || typeof cursor !== 'object') {
      return undefined;
    }
    cursor = (cursor as Record<string, unknown>)[segments[i]];
  }
  return cursor;
}
